/// ⚠ **Six, not nine, since 2026-08-10.** `desired_cities` is
/// `floor + turn / cadence`, so removing the production floor of six lowers
/// what the ramp reaches inside the window as well as where it starts. That
/// consequence is **inside the measurement**, not a side effect of it: the
/// arm that passed the promotion matrix at +41 Elo on deployment-online
/// (125/65, p=0.0000) is exactly this agent, reaching six here rather than
/// nine. The nine-city reach was part of what cost the thirty Elo.
///
/// What the test still pins is the shape that matters — that the window is
/// open at turn 270, that the plan is Expansion, and that a settler is not
/// vetoed — so a regression that stops the ramp climbing at all still
/// fails here.
#[test]
fn expansion_window_still_climbs_and_wants_a_settler_before_endgame() {
    // A longer turn cap no longer postpones Standard's development boundary
    // past t250. Exercise the expansion ramp inside that boundary.
    let mut game = Game::new_full(1, 30, 18, 7_113, 600, 0, false);
    let settler = game
        .player_unit_ids(0)
        .into_iter()
        .find(|unit| game.units[unit].kind == "settler")
        .unwrap();
    game.apply(0, &Action::FoundCity { unit: settler }).unwrap();
    for tile in game.map.tiles.values_mut() {
        tile.terrain = crate::name!("grassland");
        tile.feature = None;
    }
    let city = game.player_city_ids(0)[0];
    game.cities.get_mut(&city).unwrap().pop = 6;
    game.turn = 240;

    let ai = AdvancedAi::new();
    let plan = ai.assess(&game, 0);
    assert_eq!(plan.desired_cities, 5);
    assert!(
        plan.desired_cities > 3,
        "the ramp must still climb above the base floor inside the window"
    );
    assert_eq!(plan.strategy, GrandStrategy::Expansion);
    let item = Item::Unit {
        unit: crate::name!("settler"),
    };
    let counts = ai.counts(&game, 0);
    assert!(ai.production_value(&game, 0, city, &item, &plan, &counts) > -9_000.0);

    game.turn = 300;
    assert!(!AdvancedAi::expansion_window_open(&game));
    assert!(ai.production_value(&game, 0, city, &item, &plan, &counts) < -9_000.0);
}

#[test]
fn campaign_masks_allied_rivals_and_their_suzerained_city_states() {
    let mut game = Game::new_full(2, 30, 18, 7_112, 300, 1, false);
    for pid in 0..2 {
        let settler = game
            .player_unit_ids(pid)
            .into_iter()
            .find(|unit| game.units[unit].kind == "settler")
            .unwrap();
        game.current = pid;
        game.apply(pid, &Action::FoundCity { unit: settler })
            .unwrap();
    }
    game.current = 0;
    game.turn = 200;
    let minor = game
        .players
        .iter()
        .find(|player| player.is_minor && !player.is_barbarian)
        .unwrap()
        .id;
    game.players[1].envoys = vec![(minor, 3)];
    assert_eq!(game.suzerain_of(minor), Some(1));

    let alliance = crate::game::AllianceState {
        kind: "military".to_string(),
        points: 0.0,
        level: 1,
        ends: game.turn + 30,
    };
    game.players[0].alliances.insert(1, alliance.clone());
    game.players[1].alliances.insert(0, alliance);

    let ai = AdvancedAi::targeting(VictoryTarget::Domination);
    assert!(!ai.campaign_target_legal(&game, 0, 1));
    assert!(!ai.campaign_target_legal(&game, 0, minor));
    assert_eq!(ai.assess(&game, 0).target_player, None);

    let mut stale_ai = AdvancedAi::targeting(VictoryTarget::Domination);
    stale_ai.plan = Some(StrategicPlan {
        strategy: GrandStrategy::Conquest,
        target_player: Some(1),
        target_city: game.player_city_ids(1).first().copied(),
        threatened_city: None,
        desired_cities: 3,
        assessed_turn: game.turn,
        rush: false,
    });
    assert!(
        stale_ai.plan_stale(&game, 0),
        "a new alliance must interrupt a cached hostile plan immediately"
    );

    // A loaded legacy position can contain contradictory relationship
    // state or omit the contact record. An actual war remains a forcing
    // objective until peace.
    game.players[0].met.remove(&1);
    game.players[1].met.remove(&0);
    game.at_war.insert((0, 1));
    assert!(ai.campaign_target_legal(&game, 0, 1));
    assert!(
        ai.assess(&game, 0)
            .target_player
            .is_some_and(|target| target == 1 || target == minor),
        "the suzerain or the city-state that joined its war must remain actionable"
    );
}

#[test]
fn domination_prices_a_fresh_wall_as_a_real_first_capture_delay() {
    let mut game = Game::new_full(2, 30, 18, 7_112, 300, 0, false);
    for pid in 0..2 {
        game.current = pid;
        let settler = game
            .player_unit_ids(pid)
            .into_iter()
            .find(|unit| game.units[unit].kind == "settler")
            .unwrap();
        game.apply(pid, &Action::FoundCity { unit: settler })
            .unwrap();
    }
    let enemy = game.player_city_ids(1)[0];
    let mut domination = AdvancedAi::targeting(VictoryTarget::Domination);
    let mut ordinary = AdvancedAi::new();
    domination.battlefront_observation = false;
    ordinary.battlefront_observation = false;
    let score = |ai: &AdvancedAi, game: &Game| {
        ai.campaign_city_value(game, 0, &game.cities[&enemy], GrandStrategy::Conquest)
    };
    let open_domination = score(&domination, &game);
    let open_ordinary = score(&ordinary, &game);
    game.cities.get_mut(&enemy).unwrap().wall_hp = 100;
    let wall_domination = score(&domination, &game);
    let wall_ordinary = score(&ordinary, &game);
    assert!(
        wall_domination - open_domination > 60.0,
        "the first wall must cost more than five tiles of marching toward an open foothold"
    );
    assert!(
        wall_ordinary - open_ordinary < 60.0,
        "ordinary Conquest keeps its established city ranking"
    );
}

#[test]
fn campaign_city_ordering_prefers_a_breach_then_the_domination_capital() {
    let mut game = Game::new_full(2, 30, 18, 7_111, 300, 0, false);
    for pid in 0..2 {
        game.current = pid;
        let settler = game
            .player_unit_ids(pid)
            .into_iter()
            .find(|unit| game.units[unit].kind == "settler")
            .unwrap();
        game.apply(pid, &Action::FoundCity { unit: settler })
            .unwrap();
    }
    let own_capital = game.player_city_ids(0)[0];
    let enemy_capital = game.player_city_ids(1)[0];
    let enemy_position = game.cities[&enemy_capital].pos;
    let capital_distance = game.wdist(game.cities[&own_capital].pos, enemy_position);
    let outpost_position = game
        .map
        .tiles
        .iter()
        .filter(|(position, tile)| {
            game.rules.is_passable(tile)
                && !game.rules.is_water(tile)
                && tile.owner_city.is_none()
                && game.wdist(enemy_position, **position) >= 9
                && game
                    .cities
                    .values()
                    .all(|city| game.wdist(city.pos, **position) >= 4)
        })
        .min_by_key(|(position, _)| {
            (
                (game.wdist(game.cities[&own_capital].pos, **position) - capital_distance).abs(),
                **position,
            )
        })
        .map(|(position, _)| *position)
        .expect("test map has a comparable second-city site");
    game.current = 1;
    let settler = game.spawn_test_unit("settler", 1, outpost_position);
    game.apply(1, &Action::FoundCity { unit: settler }).unwrap();
    let enemy_outpost = game
        .player_city_ids(1)
        .into_iter()
        .find(|city| *city != enemy_capital)
        .unwrap();
    for unit in game.units.keys().copied().collect::<Vec<_>>() {
        game.remove_unit(unit);
    }

    let fortify = |game: &mut Game, city: u32| {
        let position = {
            let target = game.cities.get_mut(&city).unwrap();
            target.hp = 200;
            target.wall_hp = 400;
            target.buildings.extend([
                crate::name!("walls"),
                crate::name!("medieval_walls"),
                crate::name!("renaissance_walls"),
            ]);
            target.pos
        };
        for _ in 0..3 {
            game.spawn_test_unit("giant_death_robot", 1, position);
        }
    };
    let breach = |game: &mut Game, city: u32| {
        let target = game.cities.get_mut(&city).unwrap();
        target.hp = 25;
        target.wall_hp = 0;
        target.buildings.retain(|building| {
            !matches!(
                building.as_str(),
                "walls" | "medieval_walls" | "renaissance_walls"
            )
        });
    };
    let _capital_observer = game.spawn_test_unit("scout", 0, game.cities[&enemy_capital].pos);
    let _outpost_observer = game.spawn_test_unit("scout", 0, game.cities[&enemy_outpost].pos);
    let mut ai = AdvancedAi::targeting(VictoryTarget::Domination);

    fortify(&mut game, enemy_capital);
    breach(&mut game, enemy_outpost);
    ai.belief.observe(&game, 0);
    let exposed_outpost = ai.campaign_city_value(
        &game,
        0,
        &game.cities[&enemy_outpost],
        GrandStrategy::Conquest,
    );
    let fortified_capital = ai.campaign_city_value(
        &game,
        0,
        &game.cities[&enemy_capital],
        GrandStrategy::Conquest,
    );
    assert!(
            exposed_outpost < fortified_capital,
            "an exposed breach ({exposed_outpost}) should be searched before a fully defended capital ({fortified_capital})"
        );

    for unit in game.units.keys().copied().collect::<Vec<_>>() {
        game.remove_unit(unit);
    }
    breach(&mut game, enemy_capital);
    fortify(&mut game, enemy_outpost);
    let _capital_refresh = game.spawn_test_unit("scout", 0, game.cities[&enemy_capital].pos);
    let _outpost_refresh = game.spawn_test_unit("scout", 0, game.cities[&enemy_outpost].pos);
    ai.belief.observe(&game, 0);
    assert!(
            ai.campaign_city_value(
                &game,
                0,
                &game.cities[&enemy_capital],
                GrandStrategy::Conquest,
            ) < ai.campaign_city_value(
                &game,
                0,
                &game.cities[&enemy_outpost],
                GrandStrategy::Conquest,
            ),
            "once both geometry and defenses favor it, Domination must order the original capital first"
        );
}

#[test]
fn conquest_army_stages_before_diplomacy_opens_the_war() {
    let mut game = Game::new_full(2, 30, 18, 7_114, 300, 0, false);
    // A war has to be declarable, which means the two have met.
    game.record_contact(0, 1);
    for pid in 0..2 {
        game.current = pid;
        let settler = game
            .player_unit_ids(pid)
            .into_iter()
            .find(|unit| game.units[unit].kind == "settler")
            .unwrap();
        game.apply(pid, &Action::FoundCity { unit: settler })
            .unwrap();
    }
    game.current = 0;
    game.turn = 60;
    let target_city = game.player_city_ids(1)[0];
    let objective = game.cities[&target_city].pos;

    // The declaration rule also requires a two-city operating base. Put
    // the second city close enough that this test isolates army staging.
    let second_site = game
        .map
        .tiles
        .iter()
        .filter(|(position, tile)| {
            game.rules.is_passable(tile)
                && !game.rules.is_water(tile)
                && tile.owner_city.is_none()
                && game.wdist(**position, objective) <= 18
                && game
                    .cities
                    .values()
                    .all(|city| game.wdist(city.pos, **position) >= 4)
        })
        .map(|(position, _)| *position)
        .next()
        .expect("test map has a legal second-city site");
    let settler = game.spawn_test_unit("settler", 0, second_site);
    game.apply(0, &Action::FoundCity { unit: settler }).unwrap();

    for unit in game.units.keys().copied().collect::<Vec<_>>() {
        game.remove_unit(unit);
    }
    for tile in game.map.tiles.values_mut() {
        tile.terrain = crate::name!("grassland");
        tile.feature = None;
        tile.hills = false;
    }
    let remote = game
        .map
        .tiles
        .keys()
        .copied()
        .find(|position| {
            game.wdist(*position, objective) >= 10
                && game.city_at(*position).is_none()
                && game.map.tiles[position]
                    .owner_city
                    .and_then(|city| game.cities.get(&city))
                    .is_none_or(|city| city.owner != 1)
        })
        .expect("test map has a remote muster position");
    let mut army: Vec<u32> = (0..3)
        .map(|_| game.spawn_test_unit("crossbowman", 0, remote))
        .collect();
    army.push(game.spawn_test_unit("swordsman", 0, remote));
    let plan = StrategicPlan {
        strategy: GrandStrategy::Conquest,
        target_player: Some(1),
        target_city: Some(target_city),
        threatened_city: None,
        desired_cities: 3,
        assessed_turn: game.turn,
        rush: false,
    };
    let mut ai = AdvancedAi::targeting(VictoryTarget::Domination);

    assert!(!ai.campaign_staged_for_war(&game, 0, 1, objective, true));
    let before = game.wdist(game.units[&army[0]].pos, objective);
    assert_eq!(
        ai.campaign_staging_step(&mut game, 0, army[0], &plan),
        Some(true)
    );
    assert!(game.wdist(game.units[&army[0]].pos, objective) < before);

    ai.advanced_diplomacy(&mut game, 0, &plan);
    assert!(
        !game.players[0]
            .denounced_until
            .get(&1)
            .is_some_and(|until| *until > game.turn),
        "remote global power must not begin the diplomatic war countdown"
    );

    let staging: Vec<Pos> = game
        .wdisk(objective, 7)
        .into_iter()
        .filter(|position| {
            (3..=5).contains(&game.wdist(*position, objective)) && game.city_at(*position).is_none()
        })
        .take(army.len())
        .collect();
    assert_eq!(staging.len(), army.len());
    for (unit, position) in army.iter().zip(staging) {
        let tile = game.map.tiles.get_mut(&position).unwrap();
        tile.terrain = crate::name!("grassland");
        tile.feature = None;
        tile.hills = false;
        tile.owner_city = None;
        game.units.get_mut(unit).unwrap().pos = position;
    }
    assert!(ai.campaign_staged_for_war(&game, 0, 1, objective, true));

    let taker_ring = game.units[&army[3]].pos;
    let near_taker = game
        .wdisk(objective, 7)
        .into_iter()
        .find(|position| game.wdist(*position, objective) == 7 && game.city_at(*position).is_none())
        .expect("test map has a tile for the following taker");
    let tile = game.map.tiles.get_mut(&near_taker).unwrap();
    tile.terrain = crate::name!("grassland");
    tile.feature = None;
    tile.hills = false;
    tile.owner_city = None;
    game.units.get_mut(&army[3]).unwrap().pos = near_taker;
    assert!(
        ai.campaign_staged_for_war(&game, 0, 1, objective, true),
        "an unwalled city can be opened with three staged shooters and a strong taker close behind"
    );
    assert!(
        !ai.campaign_staged_for_war(&game, 0, 1, objective, false),
        "the shortened taker march belongs only to committed Domination"
    );
    game.cities.get_mut(&target_city).unwrap().wall_hp = 100;
    assert!(
        !ai.campaign_staged_for_war(&game, 0, 1, objective, true),
        "standing walls still require a melee unit on the staging ring"
    );
    game.cities.get_mut(&target_city).unwrap().wall_hp = 0;
    game.units.get_mut(&army[3]).unwrap().pos = taker_ring;

    ai.advanced_diplomacy(&mut game, 0, &plan);
    assert!(
        game.players[0]
            .denounced_until
            .get(&1)
            .is_some_and(|until| *until > game.turn),
        "the staged capture force should begin the formal-war countdown"
    );

    // A terminal threat must use the already-staged force even when the
    // rival's total military is too large for an elective war. Keep the
    // reinforcements away from the objective so this isolates the global
    // readiness gate from the local staging test above.
    game.players[0].denounced_until.remove(&1);
    game.players[1].science_projects.extend([
        "launch_earth_satellite".to_string(),
        "launch_moon_landing".to_string(),
        "launch_mars_colony".to_string(),
        "exoplanet_expedition".to_string(),
    ]);
    let rival_muster = game
        .map
        .tiles
        .keys()
        .copied()
        .find(|position| {
            game.wdist(*position, objective) >= 10 && game.city_at(*position).is_none()
        })
        .expect("test map has a remote rival muster position");
    for _ in 0..12 {
        game.spawn_test_unit("swordsman", 1, rival_muster);
    }
    assert!(
        game.military_power(0) <= game.military_power(1) * 1.32 + 12.0,
        "the usual elective-war margin must reject this outnumbered army"
    );

    ai.advanced_diplomacy(&mut game, 0, &plan);
    assert!(
        game.is_at_war(0, 1),
        "a staged counterforce must immediately deny a terminal science threat"
    );
}

#[test]
fn recovery_requires_material_local_danger_and_ends_when_it_clears() {
    let mut game = Game::new_full(2, 30, 18, 7_218, 300, 0, false);
    for pid in 0..2 {
        game.current = pid;
        let settler = game
            .player_unit_ids(pid)
            .into_iter()
            .find(|unit| game.units[unit].kind == "settler")
            .unwrap();
        game.apply(pid, &Action::FoundCity { unit: settler })
            .unwrap();
    }
    for unit in game.units.keys().copied().collect::<Vec<_>>() {
        game.remove_unit(unit);
    }
    game.current = 0;
    game.turn = 90;
    game.at_war.insert((0, 1));
    let home = game.player_city_ids(0)[0];
    let home_pos = game.cities[&home].pos;
    let intruder_pos = game
        .wdisk(home_pos, 6)
        .into_iter()
        .find(|position| game.wdist(*position, home_pos) == 3 && game.city_at(*position).is_none())
        .unwrap();
    let observer_pos = game
        .nbrs(intruder_pos)
        .into_iter()
        .find(|position| {
            *position != home_pos
                && game.city_at(*position).is_none()
                && game.unit_ids_at(*position).is_empty()
        })
        .unwrap();
    let far_pos = game
        .map
        .tiles
        .keys()
        .copied()
        .find(|position| game.wdist(*position, home_pos) >= 9 && game.city_at(*position).is_none())
        .unwrap();
    for position in [intruder_pos, observer_pos, far_pos] {
        let tile = game.map.tiles.get_mut(&position).unwrap();
        tile.terrain = crate::name!("grassland");
        tile.feature = None;
        tile.hills = false;
    }
    game.spawn_test_unit("scout", 0, observer_pos);
    assert!(
        game.player_can_see(0, intruder_pos),
        "the staged attackers must be visible to the defender"
    );
    for _ in 0..4 {
        game.spawn_test_unit("modern_armor", 0, far_pos);
    }
    let mut intruders = vec![game.spawn_test_unit("warrior", 1, intruder_pos)];
    let mut ai = AdvancedAi::new();

    assert_eq!(
        ai.threatened_city(&game, 0),
        None,
        "one losing contact in the outer radius must not recall a dominant army"
    );
    assert_eq!(ai.assess(&game, 0).strategy, GrandStrategy::Conquest);

    for _ in 0..4 {
        intruders.push(game.spawn_test_unit("modern_armor", 1, intruder_pos));
    }
    assert_eq!(ai.threatened_city(&game, 0), Some(home));
    let recovery = ai.assess(&game, 0);
    assert_eq!(recovery.strategy, GrandStrategy::Recovery);
    assert_eq!(recovery.threatened_city, Some(home));

    ai.plan = Some(recovery);
    for unit in intruders {
        game.remove_unit(unit);
    }
    assert!(
        ai.plan_stale(&game, 0),
        "clearing the emergency must resume the campaign immediately"
    );
    assert_eq!(ai.assess(&game, 0).strategy, GrandStrategy::Conquest);
}

#[test]
fn imminent_city_attack_triggers_before_the_aggregate_ratio_is_critical() {
    let mut game = Game::new_full(2, 30, 18, 7_219, 300, 0, false);
    let city = found_test_city(&mut game, 0);
    for unit in game.units.keys().copied().collect::<Vec<_>>() {
        game.remove_unit(unit);
    }
    game.current = 0;
    game.turn = 90;
    game.at_war.insert((0, 1));
    let city_pos = game.cities[&city].pos;
    let attack_tile = game
        .nbrs(city_pos)
        .into_iter()
        .find(|position| {
            game.map
                .get(*position)
                .is_some_and(|tile| game.rules.is_passable(tile) && !game.rules.is_water(tile))
        })
        .expect("test city needs an accessible attack tile");
    let horseman = game.spawn_test_unit("horseman", 1, attack_tile);
    game.spawn_test_unit("archer", 0, city_pos);
    game.spawn_test_unit("warrior", 0, city_pos);

    let pressure = AdvancedAi::city_pressure(&game, 0, city);
    assert!(
        (0.45..0.90).contains(&pressure),
        "fixture must be dangerous but below the old emergency ratio: {pressure:.3}"
    );
    assert!(
        game.attack_reach(horseman).contains(&city_pos),
        "the hostile must be able to attack the City Center next turn"
    );
    assert_eq!(
        AdvancedAi::new().threatened_city(&game, 0),
        Some(city),
        "an imminent legal city attack must not wait for a second hostile; pressure={pressure:.3}, defense={:.3}, attack={:.3}",
        game.city_strength(city),
        crate::game::effective_strength(game.unit_strength(&game.units[&horseman], false), game.units[&horseman].hp),
    );

    game.remove_unit(horseman);
    let warrior = game.spawn_test_unit("warrior", 1, attack_tile);
    assert!(
        game.attack_reach(warrior).contains(&city_pos),
        "the weak hostile must still be able to attack the City Center"
    );
    let visible = game.player_vision_frame(0);
    assert!(
        !AdvancedAi::imminent_city_attack(&game, 0, city, &visible),
        "a legal but underpowered attack must not raise the imminent alarm"
    );
}

#[test]
fn a_freshly_hit_city_outranks_an_undamaged_city_under_the_same_army() {
    let (mut game, recent, enemy_city) = timed_war_fixture(7_220);
    let quiet = game
        .player_city_ids(0)
        .into_iter()
        .find(|city| *city != recent)
        .expect("the fixture has a second home city");
    for unit in game.units.keys().copied().collect::<Vec<_>>() {
        game.remove_unit(unit);
    }
    game.current = 0;
    game.turn = 90;
    game.at_war.insert((0, 1));
    game.at_war.insert((1, 0));

    let recent_pos = game.cities[&recent].pos;
    let quiet_pos = game.cities[&quiet].pos;
    assert_ne!(recent_pos, quiet_pos);
    let attack_pos =
        game.map
            .tiles
            .keys()
            .copied()
            .find(|position| {
                game.city_at(*position).is_none()
                    && game.map.get(*position).is_some_and(|tile| {
                        game.rules.is_passable(tile) && !game.rules.is_water(tile)
                    })
                    && game.wdist(recent_pos, *position) <= 6
                    && game.wdist(quiet_pos, *position) <= 6
            })
            .expect("the two home cities share a visible pressure radius");
    let observer_pos =
        game.nbrs(attack_pos)
            .into_iter()
            .find(|position| {
                game.city_at(*position).is_none()
                    && game.unit_ids_at(*position).is_empty()
                    && game.map.get(*position).is_some_and(|tile| {
                        game.rules.is_passable(tile) && !game.rules.is_water(tile)
                    })
            })
            .expect("the staged army has an adjacent observation tile");
    game.spawn_test_unit("scout", 0, observer_pos);
    assert!(game.player_can_see(0, attack_pos));

    for _ in 0..4 {
        game.spawn_test_unit("modern_armor", 1, attack_pos);
    }
    // Use the host-observed city strengths to reproduce the live shape: the
    // recently hit city can have more local support while an undamaged
    // neighbour has the worse raw hostile/friendly ratio.
    std::sync::Arc::make_mut(&mut game.observed_city_strength).insert(recent, 200.0);
    std::sync::Arc::make_mut(&mut game.observed_city_strength).insert(quiet, 190.0);
    game.cities.get_mut(&recent).unwrap().hp = 180;
    game.cities.get_mut(&recent).unwrap().last_attacked = game.turn;

    let recent_pressure = AdvancedAi::city_pressure(&game, 0, recent);
    let quiet_pressure = AdvancedAi::city_pressure(&game, 0, quiet);
    assert!(
        recent_pressure < quiet_pressure,
        "the raw radius ratio must reproduce the live overlap: recent {recent_pressure:.3}, quiet {quiet_pressure:.3}"
    );
    assert!(recent_pressure >= 0.90 && quiet_pressure >= 0.90);
    assert!(
        quiet_pressure - recent_pressure < FRESH_CITY_DAMAGE_PRIORITY,
        "the recency credit must only cover a modest overlap: recent {recent_pressure:.3}, quiet {quiet_pressure:.3}"
    );
    assert!(game.cities.contains_key(&enemy_city));
    assert_eq!(
        AdvancedAi::new().threatened_city(&game, 0),
        Some(recent),
        "a fresh city hit must outrank a slightly worse ratio at an undamaged neighbour"
    );

    std::sync::Arc::make_mut(&mut game.observed_city_strength).insert(quiet, 20.0);
    let overwhelming_quiet_pressure = AdvancedAi::city_pressure(&game, 0, quiet);
    assert!(
        overwhelming_quiet_pressure - recent_pressure >= FRESH_CITY_DAMAGE_PRIORITY,
        "the quiet city must be materially more dangerous in the guard case: recent {recent_pressure:.3}, quiet {overwhelming_quiet_pressure:.3}"
    );
    assert_eq!(
        AdvancedAi::new().threatened_city(&game, 0),
        Some(quiet),
        "recency must not override an overwhelmingly more dangerous city"
    );

    // A bridge restart or a skipped export can lose the last-hit timestamp,
    // while the host still reports the city's breached health bars. The
    // critically damaged city must remain the emergency target when the
    // neighbouring ratio is only modestly worse.
    std::sync::Arc::make_mut(&mut game.observed_city_strength).insert(quiet, 190.0);
    game.cities.get_mut(&recent).unwrap().hp = 120;
    game.cities.get_mut(&recent).unwrap().last_attacked = 0;
    let damaged_pressure = AdvancedAi::city_pressure(&game, 0, recent);
    let quiet_pressure = AdvancedAi::city_pressure(&game, 0, quiet);
    assert!(
        quiet_pressure > damaged_pressure,
        "the raw ratio should still mildly prefer the healthy neighbour: damaged {damaged_pressure:.3}, quiet {quiet_pressure:.3}"
    );
    assert!(
        quiet_pressure - damaged_pressure
            < CRITICAL_CITY_DAMAGE_PRIORITY * f64::from(200 - 120) / 200.0,
        "the damage credit should cover only a modest ratio gap: damaged {damaged_pressure:.3}, quiet {quiet_pressure:.3}"
    );
    assert_eq!(
        AdvancedAi::new().threatened_city(&game, 0),
        Some(recent),
        "a breached city remains the emergency target even without recency metadata"
    );
}

/// A seat playing under an assigned victory target has always stood its
/// whole denial apparatus down. Five of the twelve runs the live seat was
/// LEADING on 2026-08-16/17 ended at t229-245 on a rival's victory the
/// counter never engaged — that seat plays `--victory science`. With
/// `deny_while_targeted`, match point overrides the lane's focus, and
/// ordinary pressure still does not.
#[test]
fn match_point_overrides_an_assigned_lane_when_enabled() {
    let mut game = Game::new_full(4, 30, 18, 7_215, 300, 0, false);
    for pid in 0..4 {
        game.current = pid;
        let settler = game
            .player_unit_ids(pid)
            .into_iter()
            .find(|unit| game.units[unit].kind == "settler")
            .unwrap();
        game.apply(pid, &Action::FoundCity { unit: settler })
            .unwrap();
    }
    game.current = 0;
    game.players[1].religion = Some("Rival Faith".to_string());
    for owner in [1, 2, 3] {
        let city = game.player_city_ids(owner)[0];
        game.cities
            .get_mut(&city)
            .unwrap()
            .pressure
            .insert("Rival Faith".to_string(), 1_000.0);
    }

    let mut targeted = AdvancedAi::targeting(VictoryTarget::Science);
    assert!(targeted.urgent_victory_threat(&game, 1));
    assert_eq!(
        targeted.victory_denial(&game, 0),
        None,
        "an assigned lane keeps its focus while the flag is off"
    );
    targeted.enable_deny_while_targeted();
    assert_eq!(
        targeted.victory_denial(&game, 0),
        Some((1, GrandStrategy::Conquest)),
        "match point overrides the lane's focus"
    );

    // Ordinary pressure must not: below the match-point bar the assigned
    // lane's focus stands, flag or no flag.
    let city = game.player_city_ids(3)[0];
    game.cities.get_mut(&city).unwrap().pressure.clear();
    assert!(!targeted.urgent_victory_threat(&game, 1));
    assert_eq!(
        targeted.victory_denial(&game, 0),
        None,
        "sub-match-point pressure never distracts an assigned lane"
    );
}

/// An assigned lane reports 100% progress by design, but that must not erase
/// an observed rival's diplomatic match clock. This is the live Civ VI shape:
/// DVP comes directly from the public World Rankings screen, not a modeled
/// projection.
#[test]
fn urgent_diplomatic_stock_pressure_interrupts_a_completed_targeted_race() {
    let mut game = Game::new_full(3, 30, 18, 7_220, 300, 0, false);
    game.victory_conditions = crate::game::VictoryConditions::default();
    game.players[1].dvp = 16;

    let mut ai = AdvancedAi::targeting(VictoryTarget::Diplomacy);
    ai.enable_deny_while_targeted();
    assert_eq!(
        ai.rival_pressure(&game, 1),
        (GrandStrategy::Diplomacy, 80),
        "sixteen DVP is an 80% public diplomatic clock"
    );
    assert!(
        !ai.denial_is_urgent(&game, 1),
        "the stock lead-time flag remains the explicit opt-in"
    );
    assert_eq!(
        ai.victory_denial(&game, 0),
        None,
        "ordinary pressure must not distract a completed assigned race"
    );

    ai.enable_stock_denial_lead_time();
    assert!(
        ai.denial_is_urgent(&game, 1),
        "the live bridge must recognize the DVP clock before the general 90 bar"
    );
    assert_eq!(
        ai.victory_denial(&game, 0),
        Some((1, GrandStrategy::Diplomacy)),
        "an urgent DVP leader must not be discarded by the assigned-lane margin"
    );
}

fn settlement_forecast_fixture(seed: u64) -> (Game, Pos, Vec<Pos>, Vec<Pos>) {
    let mut game = Game::new_full(1, 24, 16, seed, 120, 0, false);
    let center =
        game.map
            .tiles
            .keys()
            .copied()
            .find(|position| {
                game.wdisk(*position, 2).len() == 19
                    && game.map.get(*position).is_some_and(|tile| {
                        !game.rules.is_water(tile) && game.rules.is_passable(tile)
                    })
            })
            .expect("forecast fixture has an interior land tile");
    for position in game.wdisk(center, 2) {
        let tile = game.map.tiles.get_mut(&position).unwrap();
        tile.terrain = crate::name!("desert");
        tile.feature = None;
        tile.hills = false;
        tile.resource = None;
        tile.improvement = None;
        tile.pillaged = false;
        tile.district = None;
        tile.district_foundation = None;
        tile.wonder = None;
        tile.owner_city = None;
        tile.river_edges = [false; 6];
    }
    let mut first = game.nbrs(center).to_vec();
    first.sort_unstable();
    let mut second = game
        .wdisk(center, 2)
        .into_iter()
        .filter(|position| game.wdist(center, *position) == 2)
        .collect::<Vec<_>>();
    second.sort_unstable();
    (game, center, first, second)
}

fn shape_forecast_tile(
    game: &mut Game,
    position: Pos,
    terrain: &str,
    hills: bool,
    resource: Option<&str>,
) {
    let tile = game.map.tiles.get_mut(&position).unwrap();
    tile.terrain = Name::new(terrain);
    tile.hills = hills;
    tile.resource = resource.map(Name::new);
}

#[test]
fn victory_specialization_starts_at_the_game_halfway_point() {
    let mut game = Game::new(2, 24, 16, 76_004, 300, 0);
    assert!(!AdvancedAi::victory_specialization_active(&game));
    game.turn = 149;
    assert!(
        !AdvancedAi::victory_specialization_active(&game),
        "turn 149 of a 300-turn game is still development"
    );
    game.turn = 150;
    assert!(
        AdvancedAi::victory_specialization_active(&game),
        "the victory lane takes over at halfway"
    );

    game.max_turns = 0;
    game.world_era = 3;
    assert!(!AdvancedAi::victory_specialization_active(&game));
    game.world_era = 4;
    assert!(AdvancedAi::victory_specialization_active(&game));
}

#[test]
fn culture_buildup_keeps_the_city_target_while_starting_the_culture_plan() {
    let mut game = Game::new_full(2, 44, 28, 76_008, 250, 0, false);
    let settler = game
        .player_unit_ids(0)
        .into_iter()
        .find(|unit| game.units[unit].kind == "settler")
        .unwrap();
    game.apply(0, &Action::FoundCity { unit: settler }).unwrap();
    let all: Vec<_> = game.map.tiles.keys().copied().collect();
    game.players[0].explored.extend(all);
    game.game_speed = crate::setup::GameSpeed::Online;
    let mut ai = AdvancedAi::targeting(VictoryTarget::Culture);
    ai.city_target_floor = 4;
    game.turn = 83;
    assert_eq!(ai.assess(&game, 0).strategy, GrandStrategy::Expansion);
    game.turn = 84;
    let plan = ai.assess(&game, 0);
    assert_eq!(plan.strategy, GrandStrategy::Culture);
    assert!(
        plan.desired_cities >= 4,
        "buildup must keep asking for a larger empire"
    );
}

