#[test]
fn live_gold_purchase_falls_back_to_a_defender_when_walls_are_not_buyable() {
    // Civ VI lets this bleeding city queue Ancient Walls, but its live Gold
    // menu contains military units and not Walls.  The previous emergency
    // path selected the queue answer, found no matching BuyBuilding action,
    // and spent nothing while the city fell.  An immediate local defender is
    // the only purchasable rescue in that position.
    let (mut game, city, home) = empire_with_a_capital(71_120);
    let city_pos = game.cities[&city].pos;
    game.players[0].techs.insert(crate::name!("masonry"));
    game.cities.get_mut(&city).expect("capital exists").hp = 29;
    let attackers: Vec<Pos> = game
        .wdisk(home, 2)
        .into_iter()
        .filter(|position| {
            game.map
                .get(*position)
                .is_some_and(|tile| game.rules.is_passable(tile) && !game.rules.is_water(tile))
                && game.unit_ids_at(*position).is_empty()
        })
        .take(2)
        .collect();
    assert_eq!(attackers.len(), 2, "fixture needs two visible besiegers");
    for position in attackers {
        game.spawn_test_unit("warrior", 1, position);
    }
    let plan = StrategicPlan {
        strategy: GrandStrategy::Science,
        target_player: None,
        target_city: None,
        threatened_city: Some(city),
        desired_cities: 1,
        assessed_turn: game.turn,
        rush: false,
    };
    let mut live = AdvancedAi::new();
    live.enable_garrison_under_fire();
    game.players[0].gold = 1_000.0;

    let preferred = live
        .base
        .besieged_city_item(&game, 0, city)
        .expect("the bleeding unwalled city should queue Walls");
    assert_eq!(
        preferred,
        Item::Building {
            building: crate::name!("walls")
        }
    );
    assert!(
        !live.legal_purchase_actions(&game, 0).iter().any(|action| {
            matches!(action,
                Action::BuyBuilding { city: action_city, building, currency }
                    if *action_city == city && building == &crate::name!("walls")
                        && currency == "gold")
        }),
        "Ancient Walls are buildable here but not an immediate Gold purchase"
    );

    let before_units = game.player_unit_ids(0).len();
    assert!(
        live.emergency_city_defense_purchase(&mut game, 0, &plan),
        "an unbuyable wall must fall through to a purchasable local defender"
    );
    let bought = game.player_unit_ids(0);
    assert_eq!(bought.len(), before_units + 1);
    let defender = &game.units[&bought[bought.len() - 1]];
    let spec = &game.rules.units[defender.kind];
    assert_eq!(
        defender.pos, city_pos,
        "the rescuer must appear in the city"
    );
    assert!(
        spec.class == "military" && spec.is_melee_capable() && !spec.siege,
        "the fallback must be a local land defender"
    );
}

#[test]
fn live_gold_purchase_spends_through_the_reserve_to_save_a_besieged_city() {
    // At t136 of the live Rome siege, the capital had 29 of 200 city HP
    // left, a Pike and Shot nine turns from completion, and enough Gold
    // for a defender. The generic purchase scorer instead bought a
    // Builder. Make the normal Science reserve larger than the defender's
    // entire cost: only the live emergency may spend this treasury.
    let (mut game, city, home) = empire_with_a_capital(71_121);
    let city_pos = game.cities[&city].pos;
    let state = game.cities.get_mut(&city).expect("capital exists");
    state.buildings.push(crate::name!("walls"));
    state.wall_hp = 100;
    state.hp = 29;
    let attackers: Vec<Pos> = game
        .wdisk(home, 2)
        .into_iter()
        .filter(|position| {
            game.map
                .get(*position)
                .is_some_and(|tile| game.rules.is_passable(tile) && !game.rules.is_water(tile))
                && game.unit_ids_at(*position).is_empty()
        })
        .take(2)
        .collect();
    assert_eq!(attackers.len(), 2, "fixture needs two visible besiegers");
    for position in attackers {
        game.spawn_test_unit("warrior", 1, position);
    }
    let plan = StrategicPlan {
        strategy: GrandStrategy::Science,
        target_player: None,
        target_city: None,
        threatened_city: Some(city),
        desired_cities: 1,
        assessed_turn: game.turn,
        rush: false,
    };
    let mut live = AdvancedAi::new();
    live.enable_garrison_under_fire();
    game.players[0].gold = 1_000.0;
    let defence = live
        .base
        .besieged_city_item(&game, 0, city)
        .expect("the bleeding walled city needs a local defender");
    let Item::Unit { unit: wanted } = defence else {
        panic!("walls already stand, so the live doctrine must ask for a defender");
    };
    let action = live
        .legal_purchase_actions(&game, 0)
        .into_iter()
        .find(|action| match action {
            Action::Buy {
                city: action_city,
                unit,
                formation,
                currency,
            } => *action_city == city && unit == &wanted && *formation == 0 && currency == "gold",
            _ => false,
        })
        .expect("the local defender has a Gold purchase action");
    let mut quote = game.clone();
    let before_quote = quote.players[0].gold;
    quote.apply(0, &action).expect("the defender quote applies");
    let cost = before_quote - quote.players[0].gold;
    assert!(
        cost > 0.0 && cost < 300.0,
        "fixture must sit below reserve: {cost}"
    );
    game.players[0].gold = cost;

    let stock = AdvancedAi::new();
    let mut stock_game = game.clone();
    assert!(
        !stock.emergency_city_defense_purchase(&mut stock_game, 0, &plan),
        "the frozen/default controller must leave the live emergency gate off"
    );
    assert_eq!(stock_game.players[0].gold, cost);

    assert!(live.advanced_gold_spending(&mut game, 0, &plan));
    let purchased = game.player_unit_ids(0);
    assert_eq!(
        purchased.len(),
        1,
        "the emergency spends one action, not a Builder"
    );
    let unit = &game.units[&purchased[0]];
    let spec = &game.rules.units[unit.kind];
    assert_eq!(unit.kind, wanted);
    assert_eq!(
        unit.pos, city_pos,
        "the defender appears in the city it saves"
    );
    assert!(
        spec.class == "military" && spec.is_melee_capable() && !spec.siege,
        "the emergency must buy a local land defender, not civilian infrastructure"
    );
    assert_eq!(
        game.players[0].gold, 0.0,
        "saving the city outranks the reserve"
    );
}

/// ⚠ THE POINT OF THIS TEST IS THAT THE ARM IS NOT A NO-OP.
///
/// `limitanei` was slotted 0 times in 83 recorded live runs, and the reason
/// is that `strategic_policies` chooses from hardcoded per-strategy lists
/// that do not name it. An arm that adds it to those lists is worth
/// measuring only if the card actually reaches a slot — otherwise the A/B
/// compares control against control and reports a null for the wrong
/// reason.
///
/// So this asserts both directions: on with the flag, absent without it.
/// DIAGNOSTIC, not a guard: how often is a city actually GARRISONED, and
/// how often is its loyalty low enough for +2 to matter? `garrison_loyalty`
/// pays only inside a city holding a military unit, so a slotted card in an
/// ungarrisoned empire is worth exactly zero — a second way for the arm to
/// be a no-op that the slotting test does not cover.
#[test]
#[ignore]
fn diagnostic_how_often_is_a_city_garrisoned_and_under_loyalty_pressure() {
    let mut garrisoned = 0usize;
    let mut total = 0usize;
    let mut under_pressure = 0usize;
    let mut garrisoned_and_pressured = 0usize;
    for seed in 0..8u64 {
        let mut g = Game::new(4, 24, 16, 4000 + seed, 250, 0);
        let mut ais = AdvancedAi::fleet(&g);
        let mut last = g.turn;
        while g.turn < 200 && g.winner.is_none() {
            let pid = g.current;
            ais[pid].take_turn(&mut g, pid);
            if g.winner.is_none() && g.current == pid {
                let _ = g.apply(pid, &crate::game::Action::EndTurn);
            }
            if g.turn == last {
                continue;
            }
            last = g.turn;
            for cid in g.cities.keys().copied().collect::<Vec<_>>() {
                let city = &g.cities[&cid];
                let owner = city.owner;
                if g.players[owner].is_minor || g.players[owner].is_free_city {
                    continue;
                }
                let pos = city.pos;
                let held = g.unit_ids_at(pos).iter().any(|uid| {
                    g.units[uid].owner == owner
                        && g.rules.units[g.units[uid].kind].class == "military"
                });
                let low = g.cities[&cid].loyalty < 80.0;
                total += 1;
                if held {
                    garrisoned += 1;
                }
                if low {
                    under_pressure += 1;
                }
                if held && low {
                    garrisoned_and_pressured += 1;
                }
            }
        }
    }
    let pct = |n: usize| 100.0 * n as f64 / total.max(1) as f64;
    println!(
            "city-turns {total}  garrisoned {garrisoned} ({:.1}%)  loyalty<80 {under_pressure} ({:.1}%)  BOTH {garrisoned_and_pressured} ({:.1}%)",
            pct(garrisoned),
            pct(under_pressure),
            pct(garrisoned_and_pressured)
        );
}

#[test]
fn the_garrison_loyalty_arm_actually_slots_limitanei() {
    let build = |flag: bool| {
        let mut g = Game::new(2, 24, 16, 91, 200, 0);
        g.players[0].government = Some("chiefdom".to_string());
        g.players[0].civics.insert(crate::name!("early_empire"));
        let mut ai = AdvancedAi::new();
        ai.garrison_loyalty_policy = flag;
        ai.strategic_policies(&mut g, 0, GrandStrategy::Expansion);
        g.players[0].policies.contains(&crate::name!("limitanei"))
    };

    assert!(
        build(true),
        "the arm exists to price `limitanei`; if the flag does not put the card \
             in a slot the A/B measures control against control"
    );
    assert!(
        !build(false),
        "control must keep today's behaviour — `limitanei` is slotted 0 times \
             in 83 live runs and the arm must be the only thing that changes that"
    );
}

#[test]
fn live_loyalty_alarm_prioritizes_praetorium_for_a_falling_governed_city() {
    // Arretium in civvis-20260831T093436Z was governed by Victor at t168,
    // stood at 80.75 Loyalty, and was losing 4.73438 per turn. That is an
    // imminent policy problem even though the old level-only alarm still
    // considered the city healthy.
    let (mut game, source, _) = island_colony_game();
    let city = game.city_at(source).expect("the fixture capital exists");
    game.turn = 10;
    game.players[0].government = Some("classical_republic".to_string());
    game.players[0].civics.extend([
        crate::name!("political_philosophy"),
        crate::name!("recorded_history"),
    ]);
    game.players[0].governors = vec![city];
    game.players[0].governor_roster.insert(
        "victor".to_string(),
        GovernorState {
            city: Some(city),
            assigned_turn: 0,
            disabled_until: 0,
            promotions: BTreeSet::new(),
        },
    );
    game.cities.get_mut(&city).unwrap().loyalty = 80.75;
    std::sync::Arc::make_mut(&mut game.observed_city_loyalty_per_turn).insert(city, -4.73438);

    let frozen = AdvancedAi::new();
    assert!(!frozen.loyalty_policy_needed(&game, 0));
    frozen.strategic_policies(&mut game, 0, GrandStrategy::Science);
    assert!(!game.players[0]
        .policies
        .contains(&crate::name!("praetorium")));

    let mut live_game = game.clone();
    let mut live = AdvancedAi::new();
    live.base.loyalty_rate_alarm = true;
    assert!(live.loyalty_policy_needed(&live_game, 0));
    live.strategic_policies(&mut live_game, 0, GrandStrategy::Science);
    assert!(live_game.players[0]
        .policies
        .contains(&crate::name!("praetorium")));
}

#[test]
fn live_wartime_bankruptcy_slots_the_available_maintenance_discount() {
    let build = |live_war_economy: bool, treasury: f64, successor_unlocked: bool| {
        let mut game = Game::new(2, 24, 16, 79_098, 200, 0);
        game.players[0].government = Some("chiefdom".to_string());
        game.players[0]
            .civics
            .insert(crate::name!("state_workforce"));
        if successor_unlocked {
            game.players[0].civics.insert(crate::name!("mobilization"));
        }
        game.players[0]
            .policies
            .extend([crate::name!("discipline"), crate::name!("urban_planning")]);
        game.players[0].gold = treasury;
        game.players[0].gold_per_turn = -6.0;
        game.at_war.insert((0, 1));
        game.at_war.insert((1, 0));

        let mut ai = AdvancedAi::new();
        if live_war_economy {
            ai.enable_war_economy();
        }
        ai.strategic_policies(&mut game, 0, GrandStrategy::Recovery);
        game.players[0].policies.clone()
    };

    // The frozen/ordinary controller and an empire with a full recovery
    // runway retain their existing military portfolio.
    assert!(!build(false, 0.0, false).contains(&crate::name!("conscription")));
    assert!(!build(true, 100.0, false).contains(&crate::name!("conscription")));

    let conscription = build(true, 0.0, false);
    assert!(conscription.contains(&crate::name!("conscription")));
    assert!(
        !conscription.contains(&crate::name!("discipline")),
        "the maintenance discount must take the one military slot"
    );

    // When the successor is unlocked it retires Conscription. The same
    // intervention therefore takes the stronger two-Gold relief rather
    // than silently doing nothing in the later eras.
    let levee = build(true, 0.0, true);
    assert!(levee.contains(&crate::name!("levee_en_masse")));
    assert!(!levee.contains(&crate::name!("conscription")));
}

#[test]
fn live_staged_conquest_preserves_maintenance_runway_before_declaration() {
    let build = |live_war_economy: bool, target_player: Option<usize>| {
        let mut game = Game::new(2, 24, 16, 79_101, 200, 0);
        let settler = game
            .player_unit_ids(0)
            .into_iter()
            .find(|unit| game.units[unit].kind == "settler")
            .expect("starting settler");
        game.apply(0, &Action::FoundCity { unit: settler })
            .expect("found city");
        game.players[0].government = Some("chiefdom".to_string());
        game.players[0].civics.extend([
            crate::name!("state_workforce"),
            crate::name!("mobilization"),
            crate::name!("scorched_earth"),
        ]);
        game.players[0]
            .policies
            .extend([crate::name!("discipline"), crate::name!("urban_planning")]);
        // The live counter-leader board reached 85 Gold at -59/turn before
        // it declared. This is below the one-city 125-Gold recovery
        // runway, but not yet a zero treasury.
        game.players[0].gold = 85.0;
        game.players[0].gold_per_turn = -59.0;
        assert!(
            !game.is_at_war(0, 1),
            "the regression must exercise staging, not the existing wartime path"
        );

        let mut ai = AdvancedAi::new();
        if live_war_economy {
            ai.enable_war_economy();
        }
        ai.plan = Some(StrategicPlan {
            strategy: GrandStrategy::Conquest,
            target_player,
            target_city: None,
            threatened_city: None,
            desired_cities: 1,
            assessed_turn: game.turn,
            rush: false,
        });
        ai.strategic_policies(&mut game, 0, GrandStrategy::Conquest);
        game.players[0].policies.clone()
    };

    let frozen = build(false, Some(1));
    let untargeted = build(true, None);
    let staged = build(true, Some(1));
    for (label, policies) in [("frozen", &frozen), ("untargeted", &untargeted)] {
        assert!(
            policies.contains(&crate::name!("total_war")),
            "{label} controller must retain the earlier Conquest military card: {policies:?}"
        );
        assert!(
            !policies.contains(&crate::name!("levee_en_masse")),
            "{label} controller must not preemptively take the maintenance card: {policies:?}"
        );
    }
    assert!(
            staged.contains(&crate::name!("levee_en_masse")),
            "a named counter-leader campaign must preserve its recovery runway before it declares: {staged:?}"
        );
    assert!(
        !staged.contains(&crate::name!("total_war")),
        "the maintenance intervention must actually take the contested military slot: {staged:?}"
    );
}

#[test]
fn science_bankruptcy_banks_a_spy_queue_and_preserves_victory_and_defence() {
    let (mut g, city, home) = empire_with_a_capital(79_103);
    g.at_war.clear();
    found_nearby_test_city(&mut g, 0, home);
    g.players[0].civics.insert(crate::name!("foreign_trade"));
    g.players[0].gold = 0.0;
    g.players[0].gold_per_turn = -18.0;
    let spy = Item::Unit {
        unit: crate::name!("spy"),
    };
    g.cities.get_mut(&city).unwrap().queue = vec![spy];
    g.cities.get_mut(&city).unwrap().production = 12.0;
    let mut ai = AdvancedAi::targeting(VictoryTarget::Science);
    ai.enable_war_economy();
    let plan = StrategicPlan {
        strategy: GrandStrategy::Science,
        target_player: None,
        target_city: None,
        threatened_city: None,
        desired_cities: 2,
        assessed_turn: g.turn,
        rush: false,
    };
    ai.advanced_production(&mut g, 0, &plan, false);
    assert_eq!(
        g.cities[&city].queue.first(),
        Some(&Item::Unit {
            unit: crate::name!("trader")
        })
    );
    assert_eq!(
        g.cities[&city].production_progress.get("unit:spy"),
        Some(&12.0)
    );
    g.at_war.insert((0, 1));
    let counts = ai.counts(&g, 0);
    assert!(!ai.live_war_economy_requires_recovery(&g, 0, &counts));
    assert_eq!(
        ai.production_value(
            &g,
            0,
            city,
            &Item::Unit {
                unit: crate::name!("spy")
            },
            &plan,
            &counts
        ),
        -10_000.0
    );
    for item in [
        Item::Unit {
            unit: crate::name!("archer"),
        },
        Item::Building {
            building: crate::name!("market"),
        },
        Item::Project {
            project: crate::name!("launch_earth_satellite"),
        },
    ] {
        assert!(
            !ai.science_recovery_preempts(&g, &item),
            "preserve {item:?}"
        );
    }
}

/// See `colonization_earns_its_slot_2`: a queued Builder no longer holds the
/// one early economic slot for Ilkum when Urban Planning out-produces it.
#[test]
fn colonization_earns_its_slot_2_weighs_the_builder_cards_too() {
    let setup = |version: u8| {
        let (mut game, city, _) = empire_with_a_capital(79_101);
        game.cities.get_mut(&city).unwrap().pop = 3;
        game.players[0].government = Some("chiefdom".to_string());
        game.players[0].civics.extend([
            crate::name!("code_of_laws"),
            crate::name!("early_empire"),
            crate::name!("craftsmanship"),
        ]);
        game.players[0]
            .policies
            .extend([crate::name!("discipline"), crate::name!("urban_planning")]);
        game.apply(
            0,
            &Action::Produce {
                city,
                item: Item::Unit {
                    unit: crate::name!("builder"),
                },
            },
        )
        .expect("the capital can build a Builder");
        // A second city, not building a Builder: Urban Planning's +1 in
        // each of two cities outweighs Ilkum's +30% on one capital.
        let center = game.cities[&city].pos;
        let site = game
            .map
            .tiles
            .iter()
            .find(|(pos, tile)| {
                game.wdist(center, **pos) == 4
                    && !game.rules.terrains[&tile.terrain].water
                    && tile.terrain != "mountain"
                    && tile.owner_city.is_none()
            })
            .map(|(pos, _)| *pos)
            .expect("the fixture has room for a second city");
        game.found_city_for(0, site, None);
        let mut ai = AdvancedAi::targeting(VictoryTarget::Science);
        ai.enable_wide_map_capacity();
        if version == 1 {
            ai.enable_colonization_earns_its_slot();
        } else {
            ai.enable_colonization_earns_its_slot_2();
        }
        ai.plan = Some(StrategicPlan {
            strategy: GrandStrategy::Science,
            target_player: None,
            target_city: None,
            threatened_city: None,
            desired_cities: 1,
            assessed_turn: game.turn,
            rush: false,
        });
        ai.strategic_policies(&mut game, 0, GrandStrategy::Science);
        game
    };
    let first = setup(1);
    assert!(
        first.players[0].policies.contains(&crate::name!("ilkum")),
        "version 1 commits the slot to Ilkum for the queued Builder"
    );
    let second = setup(2);
    assert!(
        second.players[0]
            .policies
            .contains(&crate::name!("urban_planning")),
        "version 2 keeps Urban Planning over Ilkum on one Builder in two cities"
    );
    assert!(!second.players[0].policies.contains(&crate::name!("ilkum")));
}

/// See `colonization_earns_its_slot`: with no Settler in production, the
/// one early economic slot stays with Urban Planning even while the city
/// plan is short; a queued Settler still takes it for Colonization.
#[test]
fn colonization_earns_its_slot_only_while_a_settler_is_building() {
    let setup = |settler: bool| {
        let (mut game, city, _) = empire_with_a_capital(79_099);
        game.cities.get_mut(&city).unwrap().pop = 3;
        game.players[0].government = Some("chiefdom".to_string());
        game.players[0]
            .civics
            .extend([crate::name!("code_of_laws"), crate::name!("early_empire")]);
        game.players[0]
            .policies
            .extend([crate::name!("discipline"), crate::name!("urban_planning")]);
        let unit = if settler { "settler" } else { "warrior" };
        game.apply(
            0,
            &Action::Produce {
                city,
                item: Item::Unit {
                    unit: Name::new(unit),
                },
            },
        )
        .expect("the capital can build the unit");
        let mut ai = AdvancedAi::targeting(VictoryTarget::Science);
        ai.enable_wide_map_capacity();
        ai.enable_colonization_earns_its_slot();
        ai.plan = Some(StrategicPlan {
            strategy: GrandStrategy::Science,
            target_player: None,
            target_city: None,
            threatened_city: None,
            desired_cities: PRODUCTION_CITY_TARGET_FLOOR,
            assessed_turn: game.turn,
            rush: false,
        });
        ai.strategic_policies(&mut game, 0, GrandStrategy::Science);
        game
    };
    let idle = setup(false);
    assert!(
        idle.players[0]
            .policies
            .contains(&crate::name!("urban_planning")),
        "no Settler in production leaves the slot to Urban Planning"
    );
    assert!(!idle.players[0]
        .policies
        .contains(&crate::name!("colonization")));
    let building = setup(true);
    assert!(
        building.players[0]
            .policies
            .contains(&crate::name!("colonization")),
        "a Settler in production still takes the slot"
    );
}

