#[test]
fn explicit_targets_replace_early_cards_with_victory_policies() {
    let mut culture = Game::new(2, 24, 16, 78, 200, 0);
    culture.players[0].government = Some("chiefdom".to_string());
    culture.players[0]
        .civics
        .insert(crate::name!("cultural_heritage"));
    culture.players[0]
        .policies
        .extend([crate::name!("discipline"), crate::name!("urban_planning")]);
    AdvancedAi::targeting(VictoryTarget::Culture).strategic_policies(
        &mut culture,
        0,
        GrandStrategy::Expansion,
    );
    assert!(culture.players[0]
        .policies
        .contains(&crate::name!("heritage_tourism")));
    assert!(culture.players[0]
        .policies
        .contains(&crate::name!("discipline")));
    assert!(!culture.players[0]
        .policies
        .contains(&crate::name!("urban_planning")));

    let mut science = Game::new(2, 24, 16, 79, 200, 0);
    science.players[0].government = Some("chiefdom".to_string());
    science.players[0].civics.insert(crate::name!("space_race"));
    science.players[0]
        .policies
        .extend([crate::name!("discipline"), crate::name!("urban_planning")]);
    AdvancedAi::targeting(VictoryTarget::Science).strategic_policies(
        &mut science,
        0,
        GrandStrategy::Expansion,
    );
    assert!(science.players[0]
        .policies
        .contains(&crate::name!("integrated_space_cell")));
    assert!(science.players[0]
        .policies
        .contains(&crate::name!("urban_planning")));
    assert!(!science.players[0]
        .policies
        .contains(&crate::name!("discipline")));

    let mut reactive = culture.clone();
    reactive.players[0].policies.clear();
    reactive.players[0]
        .policies
        .extend([crate::name!("discipline"), crate::name!("urban_planning")]);
    AdvancedAi::new().strategic_policies(&mut reactive, 0, GrandStrategy::Culture);
    assert!(reactive.players[0]
        .policies
        .contains(&crate::name!("heritage_tourism")));
}

#[test]
fn future_policy_reassessment_replaces_ancient_fillers() {
    let mut game = Game::new(2, 24, 16, 79_100, 250, 0);
    let civics: Vec<Name> = game.rules.civics.keys().cloned().collect();
    game.players[0].civics.extend(civics);
    game.players[0].government = Some("synthetic_technocracy".to_string());
    let ancient = [
        "discipline",
        "agoge",
        "bastions",
        "retainers",
        "urban_planning",
        "god_king",
        "ilkum",
        "colonization",
        "insulae",
        "charismatic_leader",
    ];
    game.players[0]
        .policies
        .extend(ancient.iter().map(|card| Name::new(card)));

    AdvancedAi::targeting(VictoryTarget::Science).strategic_policies(
        &mut game,
        0,
        GrandStrategy::Science,
    );

    assert!(game.players[0]
        .policies
        .contains(&crate::name!("integrated_space_cell")));
    assert!(game.players[0]
        .policies
        .contains(&crate::name!("future_victory_science")));
    assert!(game.players[0]
        .policies
        .contains(&crate::name!("five_year_plan")));
    assert!(game.players[0]
        .policies
        .contains(&crate::name!("rationalism")));
    assert!(ancient
        .iter()
        .all(|card| !game.players[0].policies.contains(&Name::new(card))));
}

#[test]
fn policy_reassessment_only_executes_swaps_that_can_fit() {
    let install = |game: &mut Game, government: &str, policies: &[&str]| {
        let settler = game
            .player_unit_ids(0)
            .into_iter()
            .find(|unit| game.units[unit].kind == "settler")
            .unwrap();
        game.apply(0, &Action::FoundCity { unit: settler }).unwrap();
        game.players[0].government = Some(government.to_string());
        game.players[0].policies = policies.iter().map(|card| Name::new(card)).collect();
    };

    // Fascism plus Big Ben seats six Military cards by spending both
    // wildcard slots, two Economic cards, and one Diplomatic card. The
    // remaining Conquest card is Diplomatic, so removing Rationalism
    // cannot make Gunboat Diplomacy fit: the free Economic slot does not
    // relieve either Military overflow slot. Probing that impossible swap
    // used to emit an Unslot/Slot pair which restored the exact same state.
    let mut blocked = Game::new(2, 24, 16, 79_102, 250, 0);
    install(
        &mut blocked,
        "fascism",
        &[
            "lightning_warfare",
            "total_war",
            "propaganda",
            "levee_en_masse",
            "force_modernization",
            "logistics",
            "five_year_plan",
            "rationalism",
            "cryptography",
        ],
    );
    let city = blocked.player_city_ids(0)[0];
    let position = blocked.cities[&city].pos;
    blocked
        .cities
        .get_mut(&city)
        .unwrap()
        .wonders
        .insert(crate::name!("big_ben"), position);
    blocked.players[0]
        .civics
        .extend([crate::name!("ideology"), crate::name!("the_enlightenment")]);
    let policies_before = blocked.players[0].policies.clone();
    let log_before = blocked.log.len();

    AdvancedAi::new().strategic_policies(&mut blocked, 0, GrandStrategy::Conquest);

    assert_eq!(blocked.players[0].policies, policies_before);
    assert_eq!(
        blocked
            .log
            .since(log_before)
            .filter(|(_, action)| matches!(
                action,
                Action::SlotPolicy { .. } | Action::UnslotPolicy { .. }
            ))
            .count(),
        0,
        "an impossible replacement must not be executed and undone"
    );

    // A different typed card can still be the right replacement. Here an
    // extra Economic card occupies Autocracy's wildcard slot. Removing it
    // frees that wildcard for Logistics, so the exact set-fit check must
    // allow the cross-type Rationalism -> Logistics swap.
    let mut valid = Game::new(2, 24, 16, 79_103, 250, 0);
    install(
        &mut valid,
        "autocracy",
        &[
            "lightning_warfare",
            "five_year_plan",
            "rationalism",
            "cryptography",
        ],
    );
    valid.players[0].civics.extend([
        crate::name!("ideology"),
        crate::name!("mercantilism"),
        crate::name!("the_enlightenment"),
    ]);
    let log_before = valid.log.len();

    AdvancedAi::new().strategic_policies(&mut valid, 0, GrandStrategy::Conquest);

    assert!(valid.players[0]
        .policies
        .contains(&crate::name!("logistics")));
    assert!(!valid.players[0]
        .policies
        .contains(&crate::name!("rationalism")));
    assert_eq!(
        valid
            .log
            .since(log_before)
            .filter(|(_, action)| matches!(
                action,
                Action::SlotPolicy { .. } | Action::UnslotPolicy { .. }
            ))
            .count(),
        2,
        "one valid replacement is one Unslot followed by one Slot"
    );
}

#[test]
fn dark_age_policies_follow_strategy_without_retired_cards() {
    let mut game = Game::new(2, 24, 16, 79_101, 250, 0);
    let settler = game
        .player_unit_ids(0)
        .into_iter()
        .find(|unit| game.units[unit].kind == "settler")
        .unwrap();
    game.apply(0, &Action::FoundCity { unit: settler }).unwrap();
    let city = game.player_city_ids(0)[0];
    install_ai_test_district(&mut game, city, "holy_site");
    game.world_era = 2;
    game.players[0].age = "dark".to_string();
    game.players[0].government = Some("classical_republic".to_string());

    AdvancedAi::targeting(VictoryTarget::Science).strategic_policies(
        &mut game,
        0,
        GrandStrategy::Science,
    );
    assert!(game.players[0]
        .policies
        .contains(&crate::name!("monasticism")));

    game.players[0].policies.clear();
    game.players[0]
        .policies
        .insert(crate::name!("isolationism"));
    game.spawn_test_unit("settler", 0, game.cities[&city].pos);
    AdvancedAi::new().strategic_policies(&mut game, 0, GrandStrategy::Expansion);
    assert!(!game.players[0]
        .policies
        .contains(&crate::name!("isolationism")));

    game.players[0].policies.clear();
    game.at_war.insert((0, 1));
    AdvancedAi::new().strategic_policies(&mut game, 0, GrandStrategy::Conquest);
    assert!(
        !game.rules.policies.contains_key("twilight_valor"),
        "Gathering Storm retires Twilight Valor"
    );
    assert!(!game.players[0]
        .policies
        .contains(&crate::name!("twilight_valor")));

    game.world_era = 8;
    AdvancedAi::new().strategic_policies(&mut game, 0, GrandStrategy::Conquest);
    assert!(!game.players[0]
        .policies
        .contains(&crate::name!("twilight_valor")));
}

#[test]
fn culture_trade_routes_connect_unpressured_rivals_before_duplicating_links() {
    let mut game = Game::new_full(3, 18, 10, 79_001, 200, 0, false);
    for pid in 0..3 {
        let settler = game
            .player_unit_ids(pid)
            .into_iter()
            .find(|unit| game.units[unit].kind == "settler")
            .unwrap();
        game.current = pid;
        game.apply(pid, &Action::FoundCity { unit: settler })
            .unwrap();
    }
    game.current = 0;
    let origin = game.player_city_ids(0)[0];
    let connected = game.player_city_ids(1)[0];
    let unconnected = game.player_city_ids(2)[0];
    game.routes.push(crate::game::TradeRoute {
        origin,
        dest: connected,
        owner: 0,
        ends: 30,
    });

    let ai = AdvancedAi::targeting(VictoryTarget::Culture);
    let connected_value = ai.trade_route_destination_value(
        &game,
        0,
        &game.cities[&connected],
        GrandStrategy::Expansion,
    );
    let unconnected_value = ai.trade_route_destination_value(
        &game,
        0,
        &game.cities[&unconnected],
        GrandStrategy::Expansion,
    );
    assert!(unconnected_value > connected_value);

    let science_ai = AdvancedAi::targeting(VictoryTarget::Science);
    let science_connected = science_ai.trade_route_destination_value(
        &game,
        0,
        &game.cities[&connected],
        GrandStrategy::Expansion,
    );
    let science_unconnected = science_ai.trade_route_destination_value(
        &game,
        0,
        &game.cities[&unconnected],
        GrandStrategy::Expansion,
    );
    assert!(
        unconnected_value - science_unconnected > connected_value - science_connected,
        "only the Culture objective should add the missing-rival pressure bonus"
    );
}

#[test]
fn advanced_trade_routes_value_named_great_person_destination_gold() {
    let mut game = Game::new_full(2, 20, 12, 79_004, 200, 0, false);
    for pid in 0..2 {
        let settler = game
            .player_unit_ids(pid)
            .into_iter()
            .find(|unit| game.units[unit].kind == "settler")
            .unwrap();
        game.current = pid;
        game.apply(pid, &Action::FoundCity { unit: settler })
            .unwrap();
    }
    let destination = game.player_city_ids(1)[0];
    let ai = AdvancedAi::targeting(VictoryTarget::Science);
    let value = |game: &Game| {
        ai.trade_route_destination_value(
            game,
            0,
            &game.cities[&destination],
            GrandStrategy::Expansion,
        )
    };
    let baseline = value(&game);

    game.cities
        .get_mut(&destination)
        .unwrap()
        .great_person_foreign_route_gold = 2.0;
    let city_bonus = value(&game);
    assert!(city_bonus > baseline);

    let resource_tile = game.cities[&destination]
        .owned_tiles
        .iter()
        .copied()
        .find(|position| *position != game.cities[&destination].pos)
        .unwrap();
    let tile = game.map.tiles.get_mut(&resource_tile).unwrap();
    tile.resource = Some(crate::name!("iron"));
    tile.improvement = Some(crate::name!("mine"));
    tile.pillaged = false;
    game.players[0].counters.insert(
        "great_person:strategic_destination_trade_gold".to_string(),
        2,
    );
    assert!(value(&game) > city_bonus);
}

#[test]
fn advanced_trader_uses_an_unreserved_destination_empire_wide() {
    let mut game = Game::new_full(1, 30, 18, 79_003, 200, 0, false);
    let settler = game
        .player_unit_ids(0)
        .into_iter()
        .find(|unit| game.units[unit].kind == "settler")
        .unwrap();
    game.apply(0, &Action::FoundCity { unit: settler }).unwrap();
    let first = game.player_city_ids(0)[0];
    let first_pos = game.cities[&first].pos;
    let second = found_nearby_test_city(&mut game, 0, first_pos);
    let third = found_nearby_test_city(&mut game, 0, first_pos);
    game.players[0].civics.insert(crate::name!("foreign_trade"));
    game.players[0]
        .counters
        .insert("great_person_trade_capacity".to_string(), 1);
    game.routes.push(crate::game::TradeRoute {
        origin: second,
        dest: first,
        owner: 0,
        ends: game.turn + 30,
    });
    let trader = game.spawn_test_unit("trader", 0, game.cities[&third].pos);

    assert!(AdvancedAi::new().advanced_trader_step(&mut game, 0, trader, GrandStrategy::Expansion,));
    assert!(!game.units.contains_key(&trader));
    assert!(game
        .routes
        .iter()
        .any(|route| route.origin == third && route.dest == second));
}

#[test]
fn advanced_trader_relocates_to_a_city_with_a_legal_route() {
    let mut game = Game::new_full(1, 30, 18, 79_003, 200, 0, false);
    let settler = game
        .player_unit_ids(0)
        .into_iter()
        .find(|unit| game.units[unit].kind == "settler")
        .unwrap();
    game.apply(0, &Action::FoundCity { unit: settler }).unwrap();
    let destination = game.player_city_ids(0)[0];
    let destination_pos = game.cities[&destination].pos;
    let current_city = found_nearby_test_city(&mut game, 0, destination_pos);
    game.players[0].civics.insert(crate::name!("foreign_trade"));
    game.players[0]
        .counters
        .insert("great_person_trade_capacity".to_string(), 1);
    game.routes.push(crate::game::TradeRoute {
        origin: current_city,
        dest: destination,
        owner: 0,
        ends: game.turn + 30,
    });
    let start = game.cities[&current_city].pos;
    let target = game.cities[&destination].pos;
    let trader = game.spawn_test_unit("trader", 0, start);
    let before = game.wdist(start, target);

    assert!(AdvancedAi::new().advanced_trader_step(&mut game, 0, trader, GrandStrategy::Expansion,));
    assert!(game.units.contains_key(&trader));
    assert_ne!(game.units[&trader].pos, start);
    for _ in 0..20 {
        if game.units[&trader].pos == target {
            break;
        }
        game.units.get_mut(&trader).unwrap().moves_left = 4.0;
        assert!(AdvancedAi::new().advanced_trader_step(
            &mut game,
            0,
            trader,
            GrandStrategy::Expansion,
        ));
    }
    assert_eq!(game.units[&trader].pos, target);
    assert!(game.wdist(game.units[&trader].pos, target) < before);
}

fn remote_barbarian_trade_board() -> (Game, u32, u32) {
    let mut game = Game::new_full(2, 74, 46, 79_005, 200, 0, true);
    game.current = 0;
    let settler = game
        .player_unit_ids(0)
        .into_iter()
        .find(|unit| game.units[unit].kind == "settler")
        .expect("a starting Settler");
    game.apply(0, &Action::FoundCity { unit: settler }).unwrap();
    let safe = game.player_city_ids(0)[0];
    let safe_pos = game.cities[&safe].pos;
    let remote_pos = game
        .map
        .tiles
        .iter()
        .filter(|(_, tile)| {
            tile.owner_city.is_none() && game.rules.is_passable(tile) && !game.rules.is_water(tile)
        })
        .map(|(position, _)| *position)
        .find(|position| {
            (10..=13).contains(&game.wdist(safe_pos, *position))
                && game
                    .cities
                    .values()
                    .all(|city| game.wdist(city.pos, *position) >= 4)
        })
        .expect("room for a remote second city inside trade range");
    let remote = game.found_city_for(0, remote_pos, None);
    game.players[0].civics.insert(crate::name!("foreign_trade"));

    let barb = game.barb_pid.expect("a barbarian-seated test game");
    for unit in game.player_unit_ids(barb) {
        game.remove_unit(unit);
    }
    game.barb_camps.clear();
    let camp =
        game.nbrs(remote_pos)
            .into_iter()
            .find(|position| {
                game.wdist(safe_pos, *position) > crate::ai::BARBARIAN_TRADE_RISK_RADIUS
                    && game.map.get(*position).is_some_and(|tile| {
                        game.rules.is_passable(tile) && !game.rules.is_water(tile)
                    })
            })
            .expect("a camp tile beside only the remote city");
    game.barb_camps.insert(camp, game.turn + 1_000);
    game.map.tiles.get_mut(&camp).unwrap().improvement = Some(crate::name!("barbarian_camp"));
    (game, safe, remote)
}

/// An isolated coastal hex two tiles from an inland city: a land Archer can
/// fire into it, but a melee ship cannot cross the intervening land to hit the
/// city or the shooter. That is the exact "farm it, do not mobilise for it"
/// shape the treatment owns.
fn harmless_naval_raider_board() -> (Game, u32, Pos, u32) {
    let mut game = Game::new_full(2, 30, 18, 79_006, 200, 0, true);
    game.current = 0;
    let settler = game
        .player_unit_ids(0)
        .into_iter()
        .find(|unit| game.units[unit].kind == "settler")
        .expect("a starting Settler");
    game.apply(0, &Action::FoundCity { unit: settler }).unwrap();
    let city = game.player_city_ids(0)[0];
    let center = game.cities[&city].pos;
    for unit in game.player_unit_ids(0) {
        game.remove_unit(unit);
    }
    let barb = game.barb_pid.expect("a barbarian seat");
    for unit in game.player_unit_ids(barb) {
        game.remove_unit(unit);
    }
    game.barb_camps.clear();

    for position in game.wdisk(center, 3) {
        let tile = game.map.tiles.get_mut(&position).unwrap();
        tile.terrain = crate::name!("plains");
        tile.feature = None;
        tile.hills = false;
    }
    let sea = game
        .wdisk(center, 2)
        .into_iter()
        .find(|position| game.wdist(center, *position) == 2)
        .expect("a second-ring firing target");
    game.map.tiles.get_mut(&sea).unwrap().terrain = crate::name!("coast");
    let raider = game.spawn_test_unit("galley", barb, sea);
    (game, city, sea, raider)
}

#[test]
fn naval_threat_triage_ignores_an_incapable_ship_but_keeps_the_xp_shot() {
    let (mut game, city, sea, raider) = harmless_naval_raider_board();
    let control = AdvancedAi::new();
    assert_eq!(BasicAi::barbarian_threat_pressure(&game, 0, city), 1);
    assert!(BasicAi::barbarian_local_alarm(&game, 0, city));
    assert_eq!(control.base.barbarian_defense_gap(&game, 0, city), 1);

    let mut treated = AdvancedAi::new();
    treated.enable_naval_threat_triage();
    assert_eq!(
        treated
            .base
            .barbarian_threat_pressure_for_controller(&game, 0, city),
        0,
        "a ship with no damaging next-turn target does not preempt production"
    );
    assert!(!treated
        .base
        .barbarian_local_alarm_for_controller(&game, 0, city));
    assert_eq!(treated.base.barbarian_defense_gap(&game, 0, city), 0);
    assert!(!treated.base.barbarian_presence_at_home_for_controller(
        &game,
        0,
        crate::ai::HOME_CAMP_RADIUS,
    ));
    let center = game.cities[&city].pos;
    let barracks = game
        .wdisk(center, 3)
        .into_iter()
        .find(|position| game.wdist(center, *position) == 3)
        .expect("a land barracks outside the city");
    let foot = game.spawn_test_unit("warrior", 0, barracks);
    let barb = game.barb_pid.unwrap();
    assert!(
        control
            .base
            .garrison_assignments(&game, 0, &[barb])
            .iter()
            .any(|(unit, _)| *unit == foot),
        "the untreated alarm recruits a land unit to garrison against the offshore hull"
    );
    assert!(
        treated
            .base
            .garrison_assignments(&game, 0, &[barb])
            .is_empty(),
        "triage creates no land recall for a ship that cannot hurt the city"
    );
    game.remove_unit(foot);

    let archer = game.spawn_test_unit("archer", 0, game.cities[&city].pos);
    assert!(treated.base.has_harmless_naval_xp_shot(&game, 0, archer));
    assert_eq!(
        treated
            .base
            .harmless_naval_xp_bonus(&game, 0, archer, sea, true),
        10.0
    );
    let before_hp = game.units[&raider].hp;
    let before_xp = game.units[&archer].xp;
    let plan = StrategicPlan {
        strategy: GrandStrategy::Science,
        target_player: None,
        target_city: None,
        threatened_city: None,
        desired_cities: 1,
        assessed_turn: game.turn,
        rush: false,
    };
    assert!(treated.advanced_military_step(&mut game, 0, archer, &plan));
    assert!(
        game.units
            .get(&raider)
            .is_none_or(|unit| unit.hp < before_hp),
        "the harmless hull remains a real combat target"
    );
    assert!(
        game.units[&archer].xp > before_xp,
        "the ranged unit earns experience from the safe shot"
    );

    assert!(!AdvancedAi::new().base.naval_threat_triage);
    assert!(!AdvancedAi::legacy().base.naval_threat_triage);
    let gene = crate::ai::gene("naval-threat-triage").expect("registered gene");
    assert!(gene.opt_in() && gene.screenable() && !gene.live());
}

#[test]
fn explicit_targets_choose_synergistic_secret_societies() {
    for (index, (target, expected)) in [
        (VictoryTarget::Science, "hermetic_order"),
        (VictoryTarget::Culture, "voidsingers"),
        (VictoryTarget::Religion, "voidsingers"),
        (VictoryTarget::Diplomacy, "owls_of_minerva"),
        (VictoryTarget::Domination, "owls_of_minerva"),
    ]
    .into_iter()
    .enumerate()
    {
        let mut game = Game::new(2, 24, 16, 110 + index as u64, 80, 0);
        // Secret Societies is a New Frontier mode a lobby has to switch on.
        game.game_modes.insert("secret_societies".to_string());
        game.players[0].civics.insert(crate::name!("code_of_laws"));
        let ai = AdvancedAi::targeting(target);
        ai.advanced_secret_society(&mut game, 0, target.strategy());
        assert_eq!(game.players[0].secret_society.as_deref(), Some(expected));
    }
}

#[test]
fn culture_strategy_treats_tourism_as_a_builder_yield() {
    let mut g = Game::new(2, 24, 16, 73, 80, 0);
    let pos = *g.map.tiles.keys().next().unwrap();
    for neighbor in g.nbrs(pos) {
        let tile = g.map.tiles.get_mut(&neighbor).unwrap();
        tile.terrain = crate::name!("coast");
        tile.feature = None;
        tile.district = None;
        tile.wonder = None;
        tile.improvement = None;
        tile.pillaged = false;
    }
    assert!(g.tile_appeal(pos) >= 4);
    let ai = AdvancedAi::targeting(VictoryTarget::Culture);

    let resort = ai.improvement_value(&g, pos, "seaside_resort", GrandStrategy::Culture);
    let farm = ai.improvement_value(&g, pos, "farm", GrandStrategy::Culture);

    assert!(resort > farm + 100.0, "resort={resort}, farm={farm}");
}

#[test]
fn command_phase_spends_promotions_and_links_support() {
    let mut g = Game::new_full(2, 24, 16, 79, 80, 0, false);
    let veteran = g
        .player_unit_ids(0)
        .into_iter()
        .find(|uid| !g.available_promotions(*uid).is_empty())
        .or_else(|| {
            let uid = g
                .player_unit_ids(0)
                .into_iter()
                .find(|uid| !g.rules.units[g.units[uid].kind].promotion_class.is_empty())?;
            g.units.get_mut(&uid).unwrap().xp = 15;
            Some(uid)
        })
        .expect("major starts with a promotable military class");
    g.units.get_mut(&veteran).unwrap().xp = 15;
    g.units.get_mut(&veteran).unwrap().hp = 45;
    AdvancedAi::new().advanced_promotions(&mut g, 0, GrandStrategy::Conquest);
    assert_eq!(g.units[&veteran].promotions.len(), 1);
    assert_eq!(g.units[&veteran].hp, 95);
    assert_eq!(g.units[&veteran].moves_left, 0.0);

    let pos = g
        .map
        .tiles
        .iter()
        .find(|(pos, tile)| {
            g.rules.is_passable(tile) && !g.rules.is_water(tile) && g.unit_ids_at(**pos).is_empty()
        })
        .map(|(pos, _)| *pos)
        .unwrap();
    let escort = g.spawn_test_unit("warrior", 0, pos);
    let support = g.spawn_test_unit("battering_ram", 0, pos);
    AdvancedAi::new().advanced_formations(&mut g, 0);
    assert_eq!(g.units[&escort].linked_to, Some(support));
    assert_eq!(g.units[&support].linked_to, Some(escort));
}

/// Shared fixture for the stacked-escort tests: one founded city on a
/// plains disk, a settler with a committed target 4-8 tiles out, and a
/// clean unit slate. Returns (game, source, target).
fn stacked_escort_fixture() -> (Game, Pos, Pos) {
    // Two majors at war: since the cycle-three repair, the escort machinery
    // engages only under a visible threat, so each test spawns the raider
    // its scenario needs.
    let mut game = Game::new_full(2, 24, 16, 8_119, 120, 0, false);
    game.record_contact(0, 1);
    game.at_war.insert((0, 1));
    for unit in game.player_unit_ids(1) {
        game.remove_unit(unit);
    }
    let founding_settler = game
        .player_unit_ids(0)
        .into_iter()
        .find(|uid| game.units[uid].kind == "settler")
        .unwrap();
    let source = game.units[&founding_settler].pos;
    game.apply(
        0,
        &Action::FoundCity {
            unit: founding_settler,
        },
    )
    .unwrap();
    for unit in game.player_unit_ids(0) {
        game.remove_unit(unit);
    }
    for position in game.wdisk(source, SETTLER_ESCORT_SEARCH_RADIUS) {
        let tile = game.map.tiles.get_mut(&position).unwrap();
        tile.terrain = crate::name!("plains");
        tile.feature = None;
        tile.hills = false;
        tile.district = None;
        tile.district_foundation = None;
        tile.wonder = None;
        game.players[0].explored.insert(position);
    }
    let target =
        game.map
            .tiles
            .keys()
            .copied()
            .find(|position| {
                game.wdist(source, *position) >= SETTLER_ESCORT_DISTANCE
                    && game.wdist(source, *position) <= SETTLER_ESCORT_SEARCH_RADIUS
                    && game.map.get(*position).is_some_and(|tile| {
                        game.rules.is_passable(tile) && !game.rules.is_water(tile)
                    })
            })
            .expect("fixture has a reachable expansion target");
    (game, source, target)
}

fn stacked_escort_plan(game: &Game) -> StrategicPlan {
    StrategicPlan {
        strategy: GrandStrategy::Science,
        target_player: None,
        target_city: None,
        threatened_city: None,
        desired_cities: 3,
        assessed_turn: game.turn,
        rush: false,
    }
}

/// An embarked land escort cannot protect a Settler from a naval unit hidden
/// in the fog. The live water floor holds the committed expedition before its
/// next water-to-water step until a naval guard is bound; native behavior is
/// unchanged when the HostOnly capture lessons are off.
#[test]
fn a_live_embarked_settler_holds_without_a_naval_guard() {
    let (mut game, source, target) = island_colony_game();
    game.players[0]
        .techs
        .extend([crate::name!("sailing"), crate::name!("shipbuilding")]);
    for uid in game.player_unit_ids(0) {
        game.remove_unit(uid);
    }
    let probe = game.spawn_test_unit("settler", 0, source);
    let first_water = game
        .route_step(probe, target, 0)
        .expect("the overseas route has a first water tile");
    assert!(game.rules.is_water(&game.map.tiles[&first_water]));
    game.remove_unit(probe);

    let settler = game.spawn_test_unit("settler", 0, first_water);
    let land_guard = game.spawn_test_unit("warrior", 0, first_water);
    let next_water = game
        .route_step(settler, target, 0)
        .expect("the overseas route has a second water tile");
    assert!(game.rules.is_water(&game.map.tiles[&next_water]));
    let mut live = AdvancedAi::new();
    live.enable_live_formationless_settler_shadow();
    live.enable_live_settler_capture_lessons();
    live.settler_targets.insert(settler, target);
    live.settler_escort_journeys.insert(
        settler,
        SettlerEscortJourney {
            home: source,
            target,
        },
    );
    live.settler_guards.insert(settler, land_guard);

    assert!(
        !live.settler_step_out_of_reach(&mut game, 0, settler, target),
        "the live bridge must hold the water leg without naval cover"
    );
    assert_eq!(game.units[&settler].pos, first_water);
    assert_eq!(game.units[&land_guard].pos, first_water);

    let mut native_game = game.clone();
    let mut native = AdvancedAi::new();
    native.settler_targets.insert(settler, target);
    native.settler_escort_journeys.insert(
        settler,
        SettlerEscortJourney {
            home: source,
            target,
        },
    );
    assert!(
        native.settler_step_out_of_reach(&mut native_game, 0, settler, target),
        "the HostOnly floor must not alter native water movement"
    );
    assert_ne!(native_game.units[&settler].pos, first_water);
}

/// See `naval_escort_patience`: an embarked Settler holds for its naval
/// escort two turns, then crosses alone on a quiet sea, and keeps holding
/// while a hostile ship is in reach.
#[test]
fn an_embarked_settler_crosses_alone_after_waiting_on_a_quiet_sea() {
    let (mut game, source, target) = island_colony_game();
    game.players[0]
        .techs
        .extend([crate::name!("sailing"), crate::name!("shipbuilding")]);
    for uid in game.player_unit_ids(0) {
        game.remove_unit(uid);
    }
    let probe = game.spawn_test_unit("settler", 0, source);
    let first_water = game
        .route_step(probe, target, 0)
        .expect("the overseas route has a first water tile");
    game.remove_unit(probe);
    let settler = game.spawn_test_unit("settler", 0, first_water);
    let land_guard = game.spawn_test_unit("warrior", 0, first_water);
    let journey = |ai: &mut AdvancedAi| {
        ai.enable_live_formationless_settler_shadow();
        ai.enable_live_settler_capture_lessons();
        ai.settler_targets.insert(settler, target);
        ai.settler_escort_journeys.insert(
            settler,
            SettlerEscortJourney {
                home: source,
                target,
            },
        );
        ai.settler_guards.insert(settler, land_guard);
    };
    let mut live = AdvancedAi::new();
    journey(&mut live);
    live.enable_naval_escort_patience();
    let mut threatened = game.clone();
    let mut wary = AdvancedAi::new();
    journey(&mut wary);
    wary.enable_naval_escort_patience();
    let barbarian = threatened
        .players
        .iter()
        .position(|p| p.is_barbarian)
        .expect("a barbarian seat");
    let raider_tile = threatened
        .wdisk(first_water, 3)
        .into_iter()
        .find(|pos| {
            *pos != first_water
                && threatened
                    .map
                    .get(*pos)
                    .is_some_and(|tile| threatened.rules.is_water(tile))
                && threatened.unit_ids_at(*pos).is_empty()
        })
        .expect("open water near the crossing");
    threatened.spawn_test_unit("galley", barbarian, raider_tile);
    assert!(AdvancedAi::hostile_ship_near(
        &threatened,
        0,
        first_water,
        6
    ));
    assert!(!AdvancedAi::hostile_ship_near(&game, 0, first_water, 6));

    for turn in 0..2 {
        assert!(
            !live.settler_step_out_of_reach(&mut game, 0, settler, target),
            "held on turn {turn} of its patience"
        );
        assert_eq!(game.units[&settler].pos, first_water);
        game.turn += 1;
    }
    for _ in 0..3 {
        assert!(!wary.settler_step_out_of_reach(&mut threatened, 0, settler, target));
        threatened.turn += 1;
    }
    assert_eq!(
        threatened.units[&settler].pos, first_water,
        "a hostile ship in reach keeps the hold"
    );
    assert!(
        live.settler_step_out_of_reach(&mut game, 0, settler, target),
        "the third turn crosses alone on a quiet sea"
    );
    assert_ne!(game.units[&settler].pos, first_water);
}

/// Once a naval unit occupies the water layer and can mirror the next step,
/// the live floor permits the embarked expedition to advance.
#[test]
fn a_live_embarked_settler_advances_with_a_naval_guard() {
    let (mut game, source, target) = island_colony_game();
    game.players[0]
        .techs
        .extend([crate::name!("sailing"), crate::name!("shipbuilding")]);
    for uid in game.player_unit_ids(0) {
        game.remove_unit(uid);
    }
    let probe = game.spawn_test_unit("settler", 0, source);
    let first_water = game
        .route_step(probe, target, 0)
        .expect("the overseas route has a first water tile");
    game.remove_unit(probe);
    let settler = game.spawn_test_unit("settler", 0, first_water);
    let land_guard = game.spawn_test_unit("warrior", 0, first_water);
    let next_water = game
        .route_step(settler, target, 0)
        .expect("the overseas route has a second water tile");
    assert!(game.rules.is_water(&game.map.tiles[&next_water]));
    let sea_guard = game.spawn_test_unit("galley", 0, first_water);
    let mut live = AdvancedAi::new();
    live.enable_live_formationless_settler_shadow();
    live.enable_live_settler_capture_lessons();
    live.settler_targets.insert(settler, target);
    live.settler_escort_journeys.insert(
        settler,
        SettlerEscortJourney {
            home: source,
            target,
        },
    );
    live.settler_guards.insert(settler, land_guard);
    live.settler_sea_guards.insert(settler, sea_guard);
    let before = game.units[&settler].pos;

    assert!(live.settler_step_out_of_reach(&mut game, 0, settler, target));
    assert_ne!(game.units[&settler].pos, before);
    assert_eq!(
        game.units[&settler].pos, game.units[&sea_guard].pos,
        "the naval layer mirrors the water movement"
    );
}

/// A Crossbowman attacks with its 40 Ranged strength, not its 30 Combat
/// strength.  The latter is just below the 1.5x break threshold for a full
/// Warrior, so the guard-survival test must use the actual ranged attack or
/// the Settler will be priced as protected before the hostile turn.
#[test]
fn a_ranged_hostile_breaks_a_stacked_guard_with_ranged_strength() {
    let (mut game, source, _target) = stacked_escort_fixture();
    let guard = game.spawn_test_unit("warrior", 0, source);
    let raider_at =
        game.wdisk(source, 2)
            .into_iter()
            .find(|position| {
                game.wdist(source, *position) == 2
                    && game.unit_ids_at(*position).is_empty()
                    && game.map.get(*position).is_some_and(|tile| {
                        game.rules.is_passable(tile) && !game.rules.is_water(tile)
                    })
            })
            .expect("a visible Crossbowman post in attack reach of the stack");
    let raider = game.spawn_test_unit("crossbowman", 1, raider_at);
    game.players[0].explored.insert(raider_at);

    let mut ai = AdvancedAi::new();
    ai.enable_live_bridge();
    ai.enable_settler_guard_holds();
    let visible = ai.battlefront_visibility(&game, 0);
    assert!(game.unit_visible_to(raider, 0) && game.sees(&visible, raider_at));
    assert!(
        ai.guard_outmatched_at(&game, 0, &game.units[&guard], source, &visible),
        "the guard must be rejected because the Crossbowman fires at 40 Ranged strength"
    );
}

/// The emergency civilian pass must apply the same survival test before it
/// summons a guard.  Otherwise it preferentially calls a nearer Trebuchet,
/// then records the Settler as stacked even though the visible Line Infantry
/// will break that guard on the hostile turn.
#[test]
fn a_default_live_emergency_guard_rejects_an_outmatched_guard() {
    let (mut game, source, _target) = stacked_escort_fixture();
    let field = game
        .nbrs(source)
        .into_iter()
        .find(|position| {
            game.map
                .get(*position)
                .is_some_and(|tile| game.rules.is_passable(tile) && !game.rules.is_water(tile))
        })
        .expect("a passable field beside the city");
    let unsafe_post =
        game.nbrs(field)
            .into_iter()
            .find(|position| {
                *position != source
                    && game.map.get(*position).is_some_and(|tile| {
                        game.rules.is_passable(tile) && !game.rules.is_water(tile)
                    })
            })
            .expect("a nearer Trebuchet post");
    let replacement_post =
        game.wdisk(field, 2)
            .into_iter()
            .find(|position| {
                game.wdist(field, *position) == 2
                    && *position != unsafe_post
                    && game.map.get(*position).is_some_and(|tile| {
                        game.rules.is_passable(tile) && !game.rules.is_water(tile)
                    })
            })
            .expect("a two-step Knight post");
    let raider_at =
        game.wdisk(field, 2)
            .into_iter()
            .find(|position| {
                game.wdist(field, *position) == 2
                    && *position != replacement_post
                    && *position != unsafe_post
                    && game.map.get(*position).is_some_and(|tile| {
                        game.rules.is_passable(tile) && !game.rules.is_water(tile)
                    })
            })
            .expect("a Line Infantry post in reach of the field");
    let settler = game.spawn_test_unit("settler", 0, field);
    let unsafe_guard = game.spawn_test_unit("trebuchet", 0, unsafe_post);
    let replacement = game.spawn_test_unit("knight", 0, replacement_post);
    let raider = game.spawn_test_unit("line_infantry", 1, raider_at);
    game.players[0].explored.insert(raider_at);
    for unit in [unsafe_guard, replacement] {
        let moves = game.unit_max_moves(unit);
        let unit = game.units.get_mut(&unit).unwrap();
        unit.moves_left = moves;
        unit.acted = false;
        unit.fortified = false;
    }
    assert!(
        game.reachable(unsafe_guard).contains(&field),
        "the nearer Trebuchet can reach the Settler this turn"
    );
    assert!(
        game.reachable(replacement).contains(&field),
        "the Knight can reach the Settler this turn"
    );

    let mut ai = AdvancedAi::new();
    ai.enable_live_bridge();
    ai.enable_settler_guard_holds();
    let visible = ai.battlefront_visibility(&game, 0);
    assert!(game.unit_visible_to(raider, 0) && game.sees(&visible, raider_at));
    let unsafe_outmatched =
        ai.guard_outmatched_at(&game, 0, &game.units[&unsafe_guard], field, &visible);
    let replacement_outmatched =
        ai.guard_outmatched_at(&game, 0, &game.units[&replacement], field, &visible);
    assert!(unsafe_outmatched);
    assert!(!replacement_outmatched);

    assert!(
        ai.summon_guard_to(&mut game, 0, settler, field),
        "the viable guard reaches the Settler"
    );
    assert_eq!(ai.settler_guards.get(&settler), Some(&replacement));
    assert_eq!(game.units[&replacement].pos, field);
}

/// ★★★★★ Both settlers of civvis-20260819T025840Z were taken one tile outside
/// Rome, each from a tile a warrior had just been standing on: the step was
/// priced with any own military unit on the destination as protection (×0.15),
/// the unbound warrior then took its own turn — wounded, hostiles adjacent — and
/// healed away, and the civilian stood alone in a horse archer's reach. See
/// `settler_guard_holds`: only the settler's bound guard counts as on-tile
/// protection, and only while it could hold; an unbound unit, or a guard the
/// first reachable hostile would break, is no discount at all.
#[test]
fn a_civilian_is_priced_protected_only_by_a_guard_that_can_hold() {
    let mut game = Game::new_full(2, 24, 16, 8_119, 120, 0, false);
    let founding_settler = game
        .player_unit_ids(0)
        .into_iter()
        .find(|uid| game.units[uid].kind == "settler")
        .unwrap();
    let source = game.units[&founding_settler].pos;
    game.apply(
        0,
        &Action::FoundCity {
            unit: founding_settler,
        },
    )
    .unwrap();
    for unit in game.player_unit_ids(0) {
        game.remove_unit(unit);
    }
    for position in game.wdisk(source, SETTLER_ESCORT_SEARCH_RADIUS) {
        let tile = game.map.tiles.get_mut(&position).unwrap();
        tile.terrain = crate::name!("plains");
        tile.feature = None;
        tile.hills = false;
        tile.district = None;
        tile.district_foundation = None;
        tile.wonder = None;
        game.players[0].explored.insert(position);
    }
    // The step under test: from the city onto an adjacent tile where an own
    // warrior stands, with a hostile two tiles from that tile.
    let step = game
        .nbrs(source)
        .into_iter()
        .find(|position| {
            game.map
                .get(*position)
                .is_some_and(|tile| game.rules.is_passable(tile) && !game.rules.is_water(tile))
        })
        .expect("a passable neighbour of the city");
    let raider_tile =
        game.map
            .tiles
            .keys()
            .copied()
            .find(|position| {
                game.wdist(step, *position) == 2
                    && game.wdist(source, *position) >= 2
                    && game.map.get(*position).is_some_and(|tile| {
                        game.rules.is_passable(tile) && !game.rules.is_water(tile)
                    })
            })
            .expect("a tile two steps from the destination");
    let settler = game.spawn_test_unit("settler", 0, source);
    let bystander = game.spawn_test_unit("warrior", 0, step);
    // A peer-strength hostile: a warrior does not break a warrior.
    let raider = game.spawn_test_unit("warrior", 1, raider_tile);
    game.at_war.insert((0, 1));
    game.players[0].explored.insert(raider_tile);
    let visible = {
        let ai = AdvancedAi::new();
        ai.battlefront_visibility(&game, 0)
    };
    assert!(game.sees(&visible, raider_tile), "the raider is in sight");

    let mut live = AdvancedAi::new();
    live.enable_live_bridge_universe();
    assert!(live.settler_guard_holds);
    let mut withheld = AdvancedAi::new();
    withheld.enable_live_bridge_universe();
    withheld.disable_settler_guard_holds();
    // The live capture-lessons bridge now owns the same survival predicate
    // when the screenable guard gene is withheld.  Turn the bridge arm off as
    // well so this fixture remains the true pre-repair comparison.
    withheld.disable_live_settler_capture_lessons();

    // An UNBOUND warrior on the destination: the old pricing discounts the
    // capture risk to nothing; the repaired one prices the raider in full.
    let old = withheld.settlement_tile_risk(&game, 0, Some(settler), step, &visible);
    let new = live.settlement_tile_risk(&game, 0, Some(settler), step, &visible);
    assert!(
        old <= SETTLER_STEP_RISK_LIMIT,
        "precondition: the withheld pricing let the step through ({old})"
    );
    assert!(
        new > SETTLER_STEP_RISK_LIMIT,
        "an unbound unit on the tile is no protection: {new} must exceed the step limit"
    );

    // BOUND, healthy, and not outmatched: protection again — the guard
    // mirrors the step from the settler's own tile.
    game.units.get_mut(&bystander).unwrap().pos = source;
    live.settler_guards.insert(settler, bystander);
    let bound = live.settlement_tile_risk(&game, 0, Some(settler), step, &visible);
    assert!(
        bound <= SETTLER_STEP_RISK_LIMIT,
        "a bound guard that can hold still protects the step: {bound}"
    );

    // BOUND but outmatched: a knight in reach breaks a warrior — the exact
    // shape of the Saka horsemen against Rome's warriors — so no discount.
    game.remove_unit(raider);
    let _knight = game.spawn_test_unit("knight", 1, raider_tile);
    let broken = live.settlement_tile_risk(&game, 0, Some(settler), step, &visible);
    assert!(
        broken > SETTLER_STEP_RISK_LIMIT,
        "a guard the first hostile in reach would break is no protection: {broken}"
    );

    // Frozen and stock controllers never carry it.
    assert!(!AdvancedAi::new().settler_guard_holds);
    assert!(!AdvancedAi::legacy().settler_guard_holds);
}

/// The other half of `settler_guard_holds`: the bound guard's own turn ran
/// `healing_step` before its escort duty, so a wounded guard sharing its
/// settler's tile healed away and left the civilian in the open. Under the
/// flag it holds there first.
#[test]
fn a_wounded_bound_guard_on_its_settlers_tile_holds_instead_of_healing_away() {
    let mut game = Game::new_full(2, 24, 16, 8_120, 120, 0, false);
    let founding_settler = game
        .player_unit_ids(0)
        .into_iter()
        .find(|uid| game.units[uid].kind == "settler")
        .unwrap();
    let source = game.units[&founding_settler].pos;
    game.apply(
        0,
        &Action::FoundCity {
            unit: founding_settler,
        },
    )
    .unwrap();
    for unit in game.player_unit_ids(0) {
        game.remove_unit(unit);
    }
    for position in game.wdisk(source, SETTLER_ESCORT_SEARCH_RADIUS) {
        let tile = game.map.tiles.get_mut(&position).unwrap();
        tile.terrain = crate::name!("plains");
        tile.feature = None;
        tile.hills = false;
        tile.district = None;
        tile.district_foundation = None;
        tile.wonder = None;
        game.players[0].explored.insert(position);
    }
    // The pair stands one tile outside the city; a hostile warrior is adjacent.
    let field = game
        .nbrs(source)
        .into_iter()
        .find(|position| {
            game.map
                .get(*position)
                .is_some_and(|tile| game.rules.is_passable(tile) && !game.rules.is_water(tile))
        })
        .expect("a passable neighbour of the city");
    let hostile_tile =
        game.nbrs(field)
            .into_iter()
            .find(|position| {
                *position != source
                    && game.wdist(source, *position) >= 2
                    && game.map.get(*position).is_some_and(|tile| {
                        game.rules.is_passable(tile) && !game.rules.is_water(tile)
                    })
            })
            .expect("a tile beside the pair, away from the city");
    let settler = game.spawn_test_unit("settler", 0, field);
    let guard = game.spawn_test_unit("warrior", 0, field);
    game.units.get_mut(&guard).unwrap().hp = 45;
    let _hostile = game.spawn_test_unit("warrior", 1, hostile_tile);
    game.at_war.insert((0, 1));
    game.players[0].explored.insert(hostile_tile);
    let plan = stacked_escort_plan(&game);

    let run = |ai: &mut AdvancedAi, game: &mut Game| {
        ai.settler_guards.insert(settler, guard);
        for unit in [settler, guard] {
            if let Some(unit) = game.units.get_mut(&unit) {
                unit.moves_left = 2.0;
                unit.acted = false;
                unit.fortified = false;
            }
        }
        ai.advanced_military_step_with_decline(game, 0, guard, &plan, false);
        game.units[&guard].pos
    };
    let mut withheld = AdvancedAi::new();
    withheld.enable_live_bridge_universe();
    withheld.disable_settler_guard_holds();
    withheld.disable_live_settler_capture_lessons();
    let mut game_without = game.clone();
    let left_to = run(&mut withheld, &mut game_without);
    let mut live = AdvancedAi::new();
    live.enable_live_bridge_universe();
    let held_at = run(&mut live, &mut game);
    assert_eq!(
        held_at, field,
        "the bound guard on its settler's tile holds there under the flag"
    );
    // The point of the test is the ORDER: withheld, the guard is free to heal
    // away (and does, in this fixture, or at least is not pinned by the
    // escort). Either way the flag's answer is the tile.
    assert!(
        left_to != field || withheld.settler_guards.get(&settler) == Some(&guard),
        "fixture note: withheld arm moved to {left_to:?}"
    );
}

/// A kill the planning board predicts is not a kill the host made. With
/// `turn_start_hostiles` recorded before a hostile is removed from the
/// board, a settler still prices the tile it stood on as capture ground;
/// once the record is stale (another turn) or the discipline is off, the
/// board is believed.
#[test]
fn a_settler_keeps_pricing_a_hostile_the_board_killed_this_turn() {
    let mut game = Game::new_full(2, 30, 20, 8_121, 120, 0, false);
    for pid in 0..2 {
        let settler = game
            .player_unit_ids(pid)
            .into_iter()
            .find(|unit| game.units[unit].kind == "settler")
            .unwrap();
        let pos = game.units[&settler].pos;
        game.remove_unit(settler);
        game.found_city_for(pid, pos, None);
    }
    for unit in game
        .player_unit_ids(0)
        .into_iter()
        .chain(game.player_unit_ids(1))
    {
        game.remove_unit(unit);
    }
    let home = game.cities[&game.player_city_ids(0)[0]].pos;
    let positions: Vec<Pos> = game.map.tiles.keys().copied().collect();
    for position in positions {
        let tile = game.map.tiles.get_mut(&position).unwrap();
        tile.terrain = crate::name!("plains");
        tile.feature = None;
        tile.hills = false;
        tile.district = None;
        tile.district_foundation = None;
        tile.wonder = None;
        game.players[0].explored.insert(position);
    }
    game.current = 0;
    game.turn = 40;
    game.record_contact(0, 1);
    game.at_war.insert((0, 1));
    let mut ring: Vec<Pos> = game
        .wdisk(home, 4)
        .into_iter()
        .filter(|p| game.wdist(*p, home) == 4)
        .collect();
    ring.sort_unstable();
    let source = ring[0];
    let mut two_out: Vec<Pos> = game
        .map
        .tiles
        .keys()
        .copied()
        .filter(|p| game.wdist(*p, source) == 2 && game.wdist(*p, home) == 6)
        .collect();
    two_out.sort_unstable();
    let raider_pos = two_out[0];
    let settler = game.spawn_test_unit("settler", 0, source);
    let raider = game.spawn_test_unit("warrior", 1, raider_pos);
    let step = game
        .nbrs(source)
        .into_iter()
        .filter(|p| game.wdist(*p, raider_pos) == 1)
        .min()
        .expect("a tile beside both");

    let mut ai = AdvancedAi::new();
    ai.enable_live_formationless_settler_shadow();
    ai.observe_turn_start_hostiles(&game, 0);
    let visible = ai.battlefront_visibility(&game, 0);
    let alive = ai.settlement_tile_risk(&game, 0, Some(settler), step, &visible);
    assert!(
        alive > SETTLER_STEP_RISK_LIMIT,
        "a raider beside the tile: {alive:.1}"
    );
    // The board kills the raider before the settler moves.
    game.remove_unit(raider);
    let remembered = ai.settlement_tile_risk(&game, 0, Some(settler), step, &visible);
    assert!(
        remembered > SETTLER_STEP_RISK_LIMIT,
        "the record keeps the price up after the board's kill: {remembered:.1}"
    );
    // Next turn the record is stale and the empty tile is quiet.
    game.turn += 1;
    let quiet = ai.settlement_tile_risk(&game, 0, Some(settler), step, &visible);
    assert_eq!(quiet, 0.0, "a stale record is not consulted");
    // And with the discipline off nothing is recorded at all.
    let mut lax = AdvancedAi::new();
    game.turn -= 1;
    let raider = game.spawn_test_unit("warrior", 1, raider_pos);
    lax.observe_turn_start_hostiles(&game, 0);
    game.remove_unit(raider);
    assert_eq!(
        lax.settlement_tile_risk(&game, 0, Some(settler), step, &visible),
        0.0
    );
}

/// The target can remain a fine city site while a visible raider makes only
/// its first route step unsafe. Waiting for the three-stall retirement loses
/// turns and lets another settler choose the same corridor. The opt-in sends
/// the first settler to the best safe alternate, holds the corridor out of all
/// settlers' picks briefly, and then lets the original target back in once the
/// threat is gone. Run it against both a barbarian and a wartime major: this
/// is a route-safety policy, not a barbarian-only special case.
/// The route-detour board: a Settler at `home` with a cached, otherwise valid
/// `target` whose first route `step` a visible `threat` (barbarian or the
/// rival at war) makes unsafe, and a genuinely strong alternate on another
/// branch. Shared by the threat-detour tests.
struct ThreatDetourBoard {
    game: Game,
    settler: u32,
    home: Pos,
    target: Pos,
    step: Pos,
    threat_position: Pos,
    threat: u32,
}

fn threat_detour_board(barbarian: bool, live: bool) -> ThreatDetourBoard {
    let (mut game, home) = camp_bounty_board(92_042);
    game.record_contact(0, 1);
    game.at_war.insert((0, 1));
    // The route fixture intentionally makes all nearby sites dry. Keep
    // that geometry eligible under the opening settlement policy so this
    // remains a route-detour test rather than a water-site test.
    game.players[0].techs.insert(crate::name!("pottery"));
    game.players[0].gold = 1_000.0;
    // Make the nearby alternative sites comparable open ground. The
    // chosen target is cached deliberately: this test isolates a route
    // blocker that appears AFTER an otherwise valid target was selected.
    for position in game.wdisk(home, 10) {
        if game.city_at(position).is_none() {
            let tile = game.map.tiles.get_mut(&position).unwrap();
            tile.terrain = crate::name!("plains");
            tile.feature = None;
            tile.hills = false;
            tile.district = None;
            tile.district_foundation = None;
            tile.wonder = None;
        }
    }
    let settler = game.spawn_test_unit("settler", 0, home);
    let open = |g: &Game, position: Pos| {
        g.map.get(position).is_some_and(|tile| {
            g.rules.is_passable(tile)
                && !g.rules.is_water(tile)
                && tile
                    .owner_city
                    .is_none_or(|city| g.cities[&city].owner == 0)
        }) && g.city_at(position).is_none()
            && g.unit_ids_at(position).is_empty()
    };
    // Start from the controller's real first choice. The test then places
    // the blocker after that decision, which is the live failure shape:
    // an attractive target becomes route-dangerous rather than never
    // qualifying as a settlement site at all.
    let mut picker = AdvancedAi::new();
    if live {
        picker.enable_live_bridge();
        picker.remember_early_settler_home(&game, 0, settler);
    }
    let target = picker
        .best_settler_target(&game, 0, settler, 8, None)
        .map(|(position, _)| position)
        .expect("the open board has a normal settlement target");
    let step = game
        .route_step(settler, target, 0)
        .expect("the normal target has a first route step");
    // Give a different branch a genuinely strong city site. It is the
    // intended runner-up after the manually cached first choice becomes
    // dangerous, and its first step must not share that branch.
    let alternate = game
        .wdisk(home, 5)
        .into_iter()
        .filter(|position| {
            game.wdist(home, *position) == 4
                && game.wdist(*position, target) > 4
                && open(&game, *position)
        })
        .find(|position| game.route_step(settler, *position, 0) != Some(step))
        .expect("the city has an alternate settlement branch");
    for position in game.wdisk(alternate, 2) {
        if game.city_at(position).is_none() {
            let tile = game.map.tiles.get_mut(&position).unwrap();
            tile.terrain = crate::name!("grassland");
            tile.feature = None;
            tile.hills = true;
            tile.district = None;
            tile.district_foundation = None;
            tile.wonder = None;
        }
    }
    let owner = if barbarian {
        game.barb_pid.expect("the fixture has a barbarian seat")
    } else {
        1
    };
    // Not every raider position leaves a safe way around it. Select the
    // real shape the gene promises to solve: the preferred route is in a
    // capture envelope and the ranking has a different first-step-safe
    // site after the preferred one is deferred.
    let mut threat_position = None;
    for candidate in game.nbrs(step) {
        if candidate == target
            || !open(&game, candidate)
            || game.wdist(candidate, home) > 2
            || game.wdist(candidate, target) <= 1
        {
            continue;
        }
        let temporary = game.spawn_test_unit("warrior", owner, candidate);
        let mut probe = AdvancedAi::new();
        probe.enable_settler_threat_detour();
        let visible = probe.battlefront_visibility(&game, 0);
        let safe_runner_up = if game.sees(&visible, candidate)
            && probe.settler_target_has_visible_route_threat(&game, 0, settler, target)
        {
            probe.settler_threat_deferrals.insert(
                target,
                game.turn + game.standard_duration(SETTLER_THREAT_DETOUR_TURNS),
            );
            probe
                .best_settler_target(&game, 0, settler, 8, None)
                .map(|(position, _)| position)
                .is_some_and(|fallback| {
                    !probe.settler_target_has_visible_route_threat(&game, 0, settler, fallback)
                })
        } else {
            false
        };
        game.remove_unit(temporary);
        if safe_runner_up {
            threat_position = Some(candidate);
            break;
        }
    }
    let threat_position =
        threat_position.expect("the first step has a visible threat post with a safe runner-up");
    let threat = game.spawn_test_unit("warrior", owner, threat_position);
    ThreatDetourBoard {
        game,
        settler,
        home,
        target,
        step,
        threat_position,
        threat,
    }
}

/// `one_shot_recovery` lives on `BasicAi`, which is where `healing_step`
/// reads it, so the registry row has to reach through the controller's base.
/// The behaviour itself is tested in `src/ai.rs`; this is the wiring.
#[test]
fn one_shot_recovery_is_an_off_by_default_native_gene() {
    assert!(!AdvancedAi::new().base.one_shot_recovery);
    assert!(!AdvancedAi::legacy().base.one_shot_recovery);
    let enable = GENES
        .iter()
        .find(|gene| gene.tag == "one-shot-recovery")
        .expect("the gene is published for gene_screen and evaluator arms")
        .enable;
    let mut ai = AdvancedAi::new();
    enable(&mut ai);
    assert!(ai.base.one_shot_recovery);
    ai.disable_one_shot_recovery();
    assert!(!ai.base.one_shot_recovery);
}

#[test]
fn command_phase_forms_corps_without_hollowing_out_the_army() {
    let mut g = Game::new_full(2, 24, 16, 80, 80, 0, false);
    g.players[0].civics.insert(crate::name!("nationalism"));
    let pos = g
        .map
        .tiles
        .iter()
        .find(|(_, tile)| g.rules.is_passable(tile) && !g.rules.is_water(tile))
        .map(|(pos, _)| *pos)
        .unwrap();
    for _ in 0..6 {
        g.spawn_test_unit("warrior", 0, pos);
    }
    let before = g
        .player_unit_ids(0)
        .into_iter()
        .filter(|uid| g.rules.units[g.units[uid].kind].class == "military")
        .count();
    AdvancedAi::new().advanced_formations(&mut g, 0);
    let military: Vec<u32> = g
        .player_unit_ids(0)
        .into_iter()
        .filter(|uid| g.rules.units[g.units[uid].kind].class == "military")
        .collect();
    assert!(military.len() < before);
    assert!(military.len() >= 5);
    assert!(military.iter().any(|uid| g.units[uid].formation == 1));
}

/// A staged battle only tests the code under test if the organic map is
/// not also fighting one nearby: units and cities the generator placed
/// give the planner closer targets and quietly rewrite the expected order.
/// Arenas are therefore ranked by how far they sit from everything the
/// generator put down, so the quietest corner of any map wins.
fn organic_clearance(g: &Game, pos: Pos) -> i32 {
    g.units
        .values()
        .map(|unit| g.wdist(unit.pos, pos))
        .chain(g.cities.values().map(|city| g.wdist(city.pos, pos)))
        .min()
        .unwrap_or(i32::MAX)
}

fn quietest_first(g: &Game, mut candidates: Vec<Pos>) -> Vec<Pos> {
    candidates.sort_by_key(|pos| (std::cmp::Reverse(organic_clearance(g, *pos)), *pos));
    candidates
}

#[test]
fn an_active_major_war_stays_ahead_of_its_suzerained_city_state() {
    let mut game = Game::new_full(2, 24, 16, 97, 80, 1, false);
    game.current = 1;
    let settler = game
        .player_unit_ids(1)
        .into_iter()
        .find(|unit| game.units[unit].kind == "settler")
        .unwrap();
    game.apply(1, &Action::FoundCity { unit: settler }).unwrap();
    game.current = 0;
    let minor = game
        .players
        .iter()
        .find(|player| player.is_minor && !player.is_barbarian)
        .map(|player| player.id)
        .unwrap();
    game.at_war.insert((0, 1));
    game.at_war.insert((0, minor));
    game.record_contact(0, 1);
    game.record_contact(0, minor);

    let ai = AdvancedAi::new();
    let plan = ai.assess(&game, 0);

    assert_eq!(plan.target_player, Some(1));
    assert_eq!(plan.target_city, game.player_city_ids(1).first().copied());
}

#[test]
fn friendly_volley_reprices_a_two_unit_kill_after_the_finisher() {
    let mut base = Game::new_full(2, 24, 16, 81_700, 80, 0, false);
    for unit in base.units.keys().copied().collect::<Vec<_>>() {
        base.remove_unit(unit);
    }
    for tile in base.map.tiles.values_mut() {
        tile.terrain = crate::name!("plains");
        tile.feature = None;
        tile.hills = false;
    }
    base.current = 0;
    base.at_war.insert((0, 1));
    let target = base
        .map
        .tiles
        .keys()
        .copied()
        .find(|position| base.nbrs(*position).len() == 6)
        .expect("fixture needs an interior tile");
    let firing_lines: Vec<Pos> = base
        .wdisk(target, 2)
        .into_iter()
        .filter(|position| base.wdist(*position, target) == 2)
        .take(2)
        .collect();
    assert_eq!(
        firing_lines.len(),
        2,
        "interior tile needs two firing lines"
    );
    let opener = base.spawn_test_unit("archer", 0, firing_lines[0]);
    let finisher = base.spawn_test_unit("archer", 0, firing_lines[1]);
    let defender = base.spawn_test_unit("warrior", 1, target);
    let opening = Action::Ranged {
        unit: opener,
        target,
    };
    let finish = Action::Ranged {
        unit: finisher,
        target,
    };

    // Discover an exact seeded-damage window rather than hard-coding a
    // combat-roll amount: the first shot must leave the defender alive
    // and the next friendly shot must remove it.
    let game = (2..=100)
        .find_map(|hp| {
            let mut candidate = base.clone();
            candidate.units.get_mut(&defender).unwrap().hp = hp;
            let mut after_first = candidate.clone();
            (after_first.apply(0, &opening).is_ok() && after_first.units.contains_key(&defender))
                .then_some(after_first)
                .and_then(|mut after_first| {
                    (after_first.apply(0, &finish).is_ok()
                        && !after_first.units.contains_key(&defender))
                    .then_some(candidate)
                })
        })
        .expect("two archers must admit a nonlethal-then-lethal damage window");
    let plan = StrategicPlan {
        strategy: GrandStrategy::Conquest,
        target_player: Some(1),
        target_city: None,
        threatened_city: None,
        desired_cities: 4,
        assessed_turn: game.turn,
        rush: false,
    };
    let group = ForceGroup {
        id: opener,
        domain: ForceDomain::Land,
        units: vec![opener, finisher],
        anchor: game.units[&opener].pos,
        objective: target,
        focus_target: Some(target),
        posture: ForcePosture::Engage,
        readiness: 1.0,
        local_strength_ratio: 1.0,
    };
    // Opt into the friendly-volley extension under test.
    let mut ai = AdvancedAi::new();
    ai.coordinated_finish = true;
    let first_reply = ai.forcing_reply_penalty(&game, 0, opener, &opening);
    let (bonus, paired_reply) = ai
        .friendly_volley_extension(&game, 0, opener, &opening, &group, &plan)
        .expect("the engaged force has an immediate friendly finisher");
    assert_eq!(
        bonus,
        ai.base.w.kill_bonus * TACTICAL_VOLLEY_KILL_BONUS_SCALE
    );
    assert!(
            first_reply > paired_reply,
            "the defender cannot reply after its friendly-volley kill: first={first_reply}, paired={paired_reply}"
        );
    assert!(
        AdvancedAi::legacy()
            .friendly_volley_extension(&game, 0, opener, &opening, &group, &plan)
            .is_none(),
        "the frozen control keeps the production-only tactical extension off"
    );

    // Give the first shot a reply price high enough that it would decline
    // in isolation, while the real two-unit line remains worthwhile.  The
    // live unit step must then use the extension rather than merely expose
    // it as a helper.
    let attack_value = ai.tactical_attack_value(&game, 0, opener, &opening, &plan);
    let threshold = ai.base.attack_threshold(&game, opener, target);
    let static_score = attack_value - threshold
        + ai.base.w.focus_fire * 10.0
        + if game
            .unit_ids_at(target)
            .iter()
            .any(|unit| game.units[unit].hp <= 35)
        {
            16.0
        } else {
            0.0
        };
    let trade_caution = (1..=128)
        .map(|value| value as f64)
        .find(|trade| {
            static_score - *trade * first_reply <= 0.0
                && static_score + bonus - *trade * paired_reply > 0.0
        })
        .expect("the friendly kill must be distinguishable from its interrupted reply");
    let mut live = AdvancedAi::new();
    live.coordinated_finish = true;
    live.base.w.trade_caution = trade_caution;
    live.force_groups = vec![group.clone()];
    let mut played = game.clone();
    assert!(live.advanced_military_step(&mut played, 0, opener, &plan));
    assert!(
        played.units.contains_key(&defender),
        "the opening shot is deliberately nonlethal"
    );
    assert!(matches!(
        played.log.last(),
        Some((0, Action::Ranged { unit, target: hit })) if *unit == opener && *hit == target
    ));

    let mut parallel = ai.clone();
    parallel.work_pool = Some(Arc::new(WorkPool::new(4)));
    assert_eq!(
        Some((bonus, paired_reply)),
        parallel.friendly_volley_extension(&game, 0, opener, &opening, &group, &plan)
    );
}

#[test]
fn friendly_volley_chains_two_finishers_onto_a_three_blow_kill() {
    let mut base = Game::new_full(2, 24, 16, 81_700, 80, 0, false);
    for unit in base.units.keys().copied().collect::<Vec<_>>() {
        base.remove_unit(unit);
    }
    for tile in base.map.tiles.values_mut() {
        tile.terrain = crate::name!("plains");
        tile.feature = None;
        tile.hills = false;
    }
    base.current = 0;
    base.at_war.insert((0, 1));
    let target = base
        .map
        .tiles
        .keys()
        .copied()
        .find(|position| base.nbrs(*position).len() == 6)
        .expect("fixture needs an interior tile");
    let firing_lines: Vec<Pos> = base
        .wdisk(target, 2)
        .into_iter()
        .filter(|position| base.wdist(*position, target) == 2)
        .take(3)
        .collect();
    assert_eq!(
        firing_lines.len(),
        3,
        "interior tile needs three firing lines"
    );
    let opener = base.spawn_test_unit("archer", 0, firing_lines[0]);
    let second = base.spawn_test_unit("archer", 0, firing_lines[1]);
    let third = base.spawn_test_unit("archer", 0, firing_lines[2]);
    let defender = base.spawn_test_unit("warrior", 1, target);
    let opening = Action::Ranged {
        unit: opener,
        target,
    };

    // Discover an exact seeded-damage window rather than hard-coding a
    // combat-roll amount: after the opening shot no lone teammate may
    // remove the defender, while either ordering of the remaining two
    // shots must — so the single-finisher search comes up empty and only
    // the chain can see the kill.
    let survives = |position: &Game, shots: &[u32]| -> Option<bool> {
        let mut speculative = position.clone();
        for shooter in shots {
            let action = Action::Ranged {
                unit: *shooter,
                target,
            };
            if speculative.apply(0, &action).is_err() {
                return None;
            }
        }
        Some(speculative.units.contains_key(&defender))
    };
    let game = (2..=100)
        .find_map(|hp| {
            let mut candidate = base.clone();
            candidate.units.get_mut(&defender).unwrap().hp = hp;
            let alive_after = |shots: &[u32]| survives(&candidate, shots);
            (alive_after(&[opener, second])?
                && alive_after(&[opener, third])?
                && !alive_after(&[opener, second, third])?
                && !alive_after(&[opener, third, second])?)
            .then_some(candidate)
        })
        .expect("three archers must admit a three-blow damage window");
    let plan = StrategicPlan {
        strategy: GrandStrategy::Conquest,
        target_player: Some(1),
        target_city: None,
        threatened_city: None,
        desired_cities: 4,
        assessed_turn: game.turn,
        rush: false,
    };
    let group = ForceGroup {
        id: opener,
        domain: ForceDomain::Land,
        units: vec![opener, second, third],
        anchor: game.units[&opener].pos,
        objective: target,
        focus_target: Some(target),
        posture: ForcePosture::Engage,
        readiness: 1.0,
        local_strength_ratio: 1.0,
    };
    // `coordinated_finish` must open the volley layer on its own — the
    // war-half bundle that used to carry it stays closed.
    let mut ai = AdvancedAi::new();
    ai.coordinated_finish = true;
    let (bonus, reply) = ai
        .friendly_volley_extension(&game, 0, opener, &opening, &group, &plan)
        .expect("two teammates together finish what neither can alone");
    assert_eq!(
        bonus,
        ai.base.w.kill_bonus * TACTICAL_VOLLEY_KILL_BONUS_SCALE
    );
    assert!(reply.is_finite());
    let mut withheld = AdvancedAi::new();
    withheld.coordinated_finish = true;
    withheld.volley_chain = false;
    assert!(
        withheld
            .friendly_volley_extension(&game, 0, opener, &opening, &group, &plan)
            .is_none(),
        "with the chain withheld no lone finisher exists at this window"
    );
    assert!(
        AdvancedAi::new()
            .friendly_volley_extension(&game, 0, opener, &opening, &group, &plan)
            .is_none(),
        "stock production keeps the volley layer dormant until it is priced"
    );
    assert!(
        AdvancedAi::legacy()
            .friendly_volley_extension(&game, 0, opener, &opening, &group, &plan)
            .is_none(),
        "the frozen control keeps the production-only tactical extension off"
    );
}

#[test]
fn forcing_reply_search_avoids_a_poisoned_capture() {
    let mut g = Game::new_full(2, 24, 16, 8_117, 80, 0, false);
    g.at_war.insert((0, 1));
    g.current = 0;
    let (anchor, risky, safe, reply_squares) = g
        .map
        .tiles
        .iter()
        .filter(|(position, tile)| {
            g.rules.is_passable(tile)
                && !g.rules.is_water(tile)
                && g.unit_ids_at(**position).is_empty()
                && g.city_at(**position).is_none()
                && g.cities
                    .values()
                    .all(|city| g.wdist(**position, city.pos) > 5)
                && g.units
                    .values()
                    .filter(|unit| unit.owner != 0)
                    .all(|unit| g.wdist(**position, unit.pos) > 5)
        })
        .find_map(|(anchor, _)| {
            let targets: Vec<Pos> =
                g.nbrs(*anchor)
                    .into_iter()
                    .filter(|position| {
                        g.map.get(*position).is_some_and(|tile| {
                            g.rules.is_passable(tile) && !g.rules.is_water(tile)
                        }) && g.unit_ids_at(*position).is_empty()
                            && g.city_at(*position).is_none()
                    })
                    .collect();
            for risky in &targets {
                for safe in &targets {
                    if risky == safe || g.wdist(*risky, *safe) < 2 {
                        continue;
                    }
                    let replies: Vec<Pos> = g
                        .wdisk(*risky, 2)
                        .into_iter()
                        .filter(|reply| {
                            g.wdist(*risky, *reply) == 2
                                    // A ranged unit may move one tile before
                                    // firing. Keep the safe capture outside
                                    // both its current and move-then-fire reach
                                    // so this fixture is independent of the
                                    // generated terrain's movement costs.
                                    && g.wdist(*safe, *reply) > 3
                                    && *reply != *anchor
                                    && g.map.get(*reply).is_some_and(|tile| {
                                        g.rules.is_passable(tile) && !g.rules.is_water(tile)
                                    })
                                    && g.unit_ids_at(*reply).is_empty()
                                    && g.city_at(*reply).is_none()
                        })
                        .collect();
                    if replies.len() >= 2 {
                        return Some((*anchor, *risky, *safe, replies));
                    }
                }
            }
            None
        })
        .expect("test map has an isolated poisoned-capture geometry");

    for position in g.wdisk(risky, 2) {
        let tile = g.map.tiles.get_mut(&position).unwrap();
        tile.terrain = crate::name!("plains");
        tile.feature = None;
        tile.hills = false;
    }
    // The reply search extends one approach step, so an archer three or
    // four tiles from the safe square could still move and shoot it.
    // Moat the approach ring — water stops land approaches without
    // blocking the archers' sight lines — so the safe capture stays
    // unpunishable by construction, not by map luck.
    for position in g.wdisk(safe, 2) {
        if position == safe
            || position == anchor
            || position == risky
            || !g.unit_ids_at(position).is_empty()
            || g.city_at(position).is_some()
        {
            continue;
        }
        let tile = g.map.tiles.get_mut(&position).unwrap();
        tile.terrain = crate::name!("coast");
        tile.feature = None;
        tile.resource = None;
        tile.improvement = None;
        tile.hills = false;
    }
    let attacker = g.spawn_test_unit("swordsman", 0, anchor);
    let risky_defender = g.spawn_test_unit("warrior", 1, risky);
    let safe_defender = g.spawn_test_unit("warrior", 1, safe);
    g.units.get_mut(&risky_defender).unwrap().hp = 1;
    g.units.get_mut(&safe_defender).unwrap().hp = 1;
    g.spawn_test_unit("archer", 1, reply_squares[0]);

    let risky_action = Action::Attack {
        unit: attacker,
        target: risky,
    };
    let safe_action = Action::Attack {
        unit: attacker,
        target: safe,
    };
    let mut ai = AdvancedAi::legacy();
    let single_reply = ai.forcing_reply_penalty(&g, 0, attacker, &risky_action);
    g.spawn_test_unit("archer", 1, reply_squares[1]);
    let risky_reply = ai.forcing_reply_penalty(&g, 0, attacker, &risky_action);
    let safe_reply = ai.forcing_reply_penalty(&g, 0, attacker, &safe_action);
    assert!(
            risky_reply > single_reply + 5.0,
            "the reply extension must price coordinated focus fire: single={single_reply}, risky={risky_reply}, safe={safe_reply}"
        );
    assert!(
            risky_reply > safe_reply + 5.0,
            "the ranged recapture must make the exposed kill materially worse: single={single_reply}, risky={risky_reply}, safe={safe_reply}"
        );
    let mut parallel_ai = ai.clone();
    parallel_ai.work_pool = Some(Arc::new(WorkPool::new(4)));
    assert_eq!(
        risky_reply,
        parallel_ai.forcing_reply_penalty(&g, 0, attacker, &risky_action)
    );
    assert_eq!(
        safe_reply,
        parallel_ai.forcing_reply_penalty(&g, 0, attacker, &safe_action)
    );

    let plan = StrategicPlan {
        strategy: GrandStrategy::Conquest,
        target_player: Some(1),
        target_city: None,
        threatened_city: None,
        desired_cities: 4,
        assessed_turn: g.turn,
        rush: false,
    };
    let mut parallel_game = g.clone();
    assert!(ai.advanced_military_step(&mut g, 0, attacker, &plan));
    assert!(parallel_ai.advanced_military_step(&mut parallel_game, 0, attacker, &plan));
    assert_eq!(
        serde_json::to_value(&g).unwrap(),
        serde_json::to_value(&parallel_game).unwrap()
    );
    assert!(!g.units.contains_key(&safe_defender));
    assert!(g.units.contains_key(&risky_defender));
    assert_eq!(g.units[&attacker].pos, safe);
}

#[test]
fn forcing_reply_search_prices_a_move_then_attack_counter() {
    let mut game = Game::new_full(2, 24, 16, 8_118, 80, 0, false);
    game.at_war.insert((0, 1));
    game.current = 0;
    let (anchor, prize, counter) = game
        .map
        .tiles
        .iter()
        .filter(|(position, tile)| {
            game.rules.is_passable(tile)
                && !game.rules.is_water(tile)
                && game.unit_ids_at(**position).is_empty()
                && game.city_at(**position).is_none()
                && game
                    .cities
                    .values()
                    .all(|city| game.wdist(**position, city.pos) > 5)
                && game
                    .units
                    .values()
                    .all(|unit| game.wdist(**position, unit.pos) > 5)
        })
        .find_map(|(anchor, _)| {
            game.nbrs(*anchor).into_iter().find_map(|prize| {
                let prize_tile = game.map.get(prize)?;
                if !game.rules.is_passable(prize_tile)
                    || game.rules.is_water(prize_tile)
                    || !game.unit_ids_at(prize).is_empty()
                    || game.city_at(prize).is_some()
                {
                    return None;
                }
                game.wdisk(prize, 3).into_iter().find_map(|counter| {
                    let tile = game.map.get(counter)?;
                    (game.wdist(prize, counter) == 3
                        && game.rules.is_passable(tile)
                        && !game.rules.is_water(tile)
                        && game.unit_ids_at(counter).is_empty()
                        && game.city_at(counter).is_none()
                        && game.nbrs(counter).into_iter().any(|step| {
                            game.wdist(step, prize) == 2
                                && game.map.get(step).is_some_and(|tile| {
                                    game.rules.is_passable(tile) && !game.rules.is_water(tile)
                                })
                                && game.unit_ids_at(step).is_empty()
                                && game.city_at(step).is_none()
                        }))
                    .then_some((*anchor, prize, counter))
                })
            })
        })
        .expect("test map has a one-step ranged-counter geometry");

    for position in game.wdisk(prize, 3) {
        let tile = game.map.tiles.get_mut(&position).unwrap();
        tile.terrain = crate::name!("plains");
        tile.feature = None;
        tile.hills = false;
    }
    let attacker = game.spawn_test_unit("swordsman", 0, anchor);
    let defender = game.spawn_test_unit("warrior", 1, prize);
    game.units.get_mut(&defender).unwrap().hp = 1;
    let capture = Action::Attack {
        unit: attacker,
        target: prize,
    };
    let ai = AdvancedAi::new();
    let quiet = ai.forcing_reply_penalty(&game, 0, attacker, &capture);
    game.spawn_test_unit("archer", 1, counter);
    let mobile_counter = ai.forcing_reply_penalty(&game, 0, attacker, &capture);
    assert!(
            mobile_counter > quiet + 5.0,
            "a ranged unit one step outside range must still count as a forcing reply: {mobile_counter} <= {quiet}"
        );
}

#[test]
fn forcing_reply_prefilter_keeps_one_step_attackers_and_skips_remote_wars() {
    let mut game = Game::new_full(3, 24, 16, 81_181, 80, 0, false);
    for unit in game.units.keys().copied().collect::<Vec<_>>() {
        game.remove_unit(unit);
    }
    for tile in game.map.tiles.values_mut() {
        tile.terrain = crate::name!("plains");
        tile.feature = None;
        tile.hills = false;
    }
    let target = game
        .map
        .tiles
        .keys()
        .copied()
        .find(|target| {
            game.wdisk(*target, 3)
                .iter()
                .any(|pos| game.wdist(*target, *pos) == 3)
                && game
                    .wdisk(*target, 6)
                    .iter()
                    .any(|pos| game.wdist(*target, *pos) == 6)
                && game
                    .cities
                    .values()
                    .filter(|city| city.owner == 2)
                    .all(|city| game.wdist(*target, city.pos) > 2)
        })
        .expect("fixture needs one-step and remote reply rings");
    let one_step = game
        .wdisk(target, 3)
        .into_iter()
        .find(|pos| game.wdist(target, *pos) == 3)
        .expect("fixture has a one-step ranged-counter position");
    let remote = game
        .wdisk(target, 6)
        .into_iter()
        .find(|pos| game.wdist(target, *pos) == 6)
        .expect("fixture has a remote position");
    let exposed = game.spawn_test_unit("warrior", 0, target);
    game.spawn_test_unit("archer", 1, one_step);
    game.spawn_test_unit("archer", 2, remote);

    assert!(
        AdvancedAi::enemy_can_force_a_reply_against_any(&game, 1, &[exposed]),
        "a ranged unit one step outside direct range remains a forcing branch"
    );
    assert!(
        !AdvancedAi::enemy_can_force_a_reply_against_any(&game, 2, &[exposed]),
        "a warring army outside the search geometry needs no whole-game clone"
    );
}

#[test]
fn explicit_victory_command_phase_fires_city_center_strikes() {
    let mut game = Game::new_full(2, 20, 14, 8_119, 80, 0, false);
    let settler = game
        .player_unit_ids(0)
        .into_iter()
        .find(|unit| game.units[unit].kind == "settler")
        .unwrap();
    game.apply(0, &Action::FoundCity { unit: settler }).unwrap();
    let city = game.player_city_ids(0)[0];
    let center = game.cities[&city].pos;
    for position in game.wdisk(center, 2) {
        let tile = game.map.tiles.get_mut(&position).unwrap();
        tile.terrain = crate::name!("plains");
        tile.feature = None;
        tile.hills = false;
    }
    let target = game
        .nbrs(center)
        .into_iter()
        .find(|position| {
            game.unit_ids_at(*position).is_empty()
                && game.city_at(*position).is_none()
                && game.encampment_at(*position).is_none()
        })
        .unwrap();
    game.at_war.insert((0, 1));
    game.cities.get_mut(&city).unwrap().wall_hp = 100;
    let enemy = game.spawn_test_unit("warrior", 1, target);
    let before = game.units[&enemy].hp;

    AdvancedAi::targeting(VictoryTarget::Domination).advanced_city_strikes(&mut game, 0);

    assert!(game.cities[&city].struck);
    assert!(
        game.units
            .get(&enemy)
            .is_none_or(|defender| defender.hp < before),
        "the explicit victory command phase must spend an available wall strike"
    );
}

#[test]
fn encampment_strikes_choose_the_exact_kill_over_static_unit_strength() {
    let mut game = Game::new_full(2, 20, 14, 8_120, 80, 0, false);
    let settler = game
        .player_unit_ids(0)
        .into_iter()
        .find(|unit| game.units[unit].kind == "settler")
        .unwrap();
    game.apply(0, &Action::FoundCity { unit: settler }).unwrap();
    let city = game.player_city_ids(0)[0];
    let center = game.cities[&city].pos;
    let encampment = game.cities[&city]
        .owned_tiles
        .iter()
        .copied()
        .find(|position| *position != center)
        .unwrap();
    for position in game.wdisk(encampment, 2) {
        let tile = game.map.tiles.get_mut(&position).unwrap();
        tile.terrain = crate::name!("plains");
        tile.feature = None;
        tile.hills = false;
    }
    game.map.tiles.get_mut(&encampment).unwrap().district = Some(crate::name!("encampment"));
    game.cities
        .get_mut(&city)
        .unwrap()
        .districts
        .insert(crate::name!("encampment"), encampment);
    {
        let city = game.cities.get_mut(&city).unwrap();
        city.encampment_hp = 100;
        city.encampment_wall_hp = 100;
    }
    game.at_war.insert((0, 1));
    let targets: Vec<Pos> = game
        .nbrs(encampment)
        .into_iter()
        .filter(|position| {
            *position != encampment
                && game.city_at(*position).is_none()
                && game.encampment_at(*position).is_none()
                && game.unit_ids_at(*position).is_empty()
        })
        .take(2)
        .collect();
    assert_eq!(targets.len(), 2);
    let armor = game.spawn_test_unit("modern_armor", 1, targets[0]);
    let weak = game.spawn_test_unit("warrior", 1, targets[1]);
    game.units.get_mut(&weak).unwrap().hp = 1;
    let armor_static = game.unit_strength(&game.units[&armor], true);
    let weak_static = game.unit_strength(&game.units[&weak], true) + 99.0 * 0.6;
    assert!(
        armor_static > weak_static,
        "the legacy heuristic chose the armor"
    );

    AdvancedAi::targeting(VictoryTarget::Domination).advanced_encampment_strikes(&mut game, 0);

    assert!(game.cities[&city].encampment_struck);
    assert!(game.units.contains_key(&armor));
    assert!(!game.units.contains_key(&weak));
}

