#[test]
#[ignore = "quality census; run explicitly with --nocapture"]
fn parallel_planner_quality_census() {
    let mut candidate_wins = 0usize;
    let mut control_wins = 0usize;
    let mut candidate_score_share = 0.0;
    let pairs = 8usize;
    for pair in 0..pairs {
        for swap in 0..2 {
            let mut game = Game::new_full(4, 24, 16, 93_000 + pair as u64, 180, 0, false);
            let candidate = |pid: usize| (pid + swap).is_multiple_of(2);
            let mut ais = AdvancedAi::fleet_parallel(&game, 4);
            for (pid, ai) in ais.iter_mut().enumerate() {
                if !candidate(pid) {
                    *ai = AdvancedAi::new();
                }
            }
            run_game(&mut game, &mut ais);
            match game.winner {
                Some(winner) if candidate(winner) => candidate_wins += 1,
                Some(_) => control_wins += 1,
                None => {}
            }
            let scores = (0..4)
                .map(|pid| game.score(pid).max(0) as f64)
                .collect::<Vec<_>>();
            let total = scores.iter().sum::<f64>().max(1.0);
            candidate_score_share += (0..4)
                .filter(|pid| candidate(*pid))
                .map(|pid| scores[pid])
                .sum::<f64>()
                / total;
        }
    }
    let games = 2 * pairs;
    let share = candidate_score_share / games as f64;
    println!(
            "parallel planner: {candidate_wins} wins; serial control: {control_wins}; terminal score share {share:.3}"
        );
    assert!(
        share >= 0.45,
        "parallel planning lost a material share of terminal position: {share:.3}"
    );
}

#[test]
fn colliding_unit_intents_revalidate_and_finish_from_live_state() {
    let mut game = Game::new(2, 20, 14, 73, 20, 0);
    let existing = game.units.keys().copied().collect::<Vec<_>>();
    for unit in existing {
        game.remove_unit(unit);
    }
    let (target, origins) = game
        .map
        .tiles
        .keys()
        .copied()
        .find_map(|target| {
            if game
                .map
                .get(target)
                .is_none_or(|tile| !game.rules.is_passable(tile) || game.rules.is_water(tile))
            {
                return None;
            }
            let origins = game
                .nbrs(target)
                .into_iter()
                .filter(|position| {
                    game.map.get(*position).is_some_and(|tile| {
                        game.rules.is_passable(tile) && !game.rules.is_water(tile)
                    })
                })
                .take(2)
                .collect::<Vec<_>>();
            (origins.len() == 2).then_some((target, origins))
        })
        .expect("test map has two approaches to one land tile");
    let first = game.spawn_test_unit("warrior", 0, origins[0]);
    let second = game.spawn_test_unit("warrior", 0, origins[1]);
    game.current = 0;

    let mut ai = AdvancedAi::new();
    let plan = ai.assess(&game, 0);
    let intents = [first, second]
        .into_iter()
        .map(|unit| UnitIntent {
            actions: vec![Action::Move { unit, to: target }],
            took_a_turn: true,
            base_state: ai.base.unit_plan_state(unit),
            step: last_orders::OrderStep::Other,
        })
        .collect();
    ai.apply_unit_intents(
        &mut game,
        0,
        &[first, second],
        intents,
        &plan,
        UnitTurnFlags {
            religious_offensive: false,
            decline_settlers: true,
        },
    );

    assert_eq!(game.units[&first].pos, target);
    assert_ne!(game.units[&second].pos, target);
    assert_eq!(game.unit_ids_at(target), vec![first]);
}

#[test]
fn disposition_search_liberates_for_diplomacy_but_keeps_a_developed_conquest_prize() {
    let captured_city_state = |seed| {
        let mut game = Game::new_full(3, 26, 16, seed, 80, 1, false);
        let minor = game
            .players
            .iter()
            .find(|player| player.is_minor && !player.is_barbarian)
            .unwrap()
            .id;
        let city = game.player_city_ids(minor)[0];
        let captured = game.cities.get_mut(&city).unwrap();
        captured.owner = 0;
        captured.captured_from = Some(1);
        captured.loyalty = 50.0;
        (game, minor, city)
    };

    let (mut diplomatic, minor, city) = captured_city_state(106);
    let mut ai = AdvancedAi::targeting(VictoryTarget::Diplomacy);
    ai.resolve_city_dispositions(&mut diplomatic, 0, GrandStrategy::Diplomacy);
    assert_eq!(diplomatic.cities[&city].owner, minor);
    assert_eq!(diplomatic.players[0].diplomatic_favor, 100.0);

    let (mut conquest, _, city) = captured_city_state(107);
    conquest.cities.get_mut(&city).unwrap().pop = 10;
    let mut ai = AdvancedAi::targeting(VictoryTarget::Domination);
    ai.resolve_city_dispositions(&mut conquest, 0, GrandStrategy::Conquest);
    assert_eq!(conquest.cities[&city].owner, 0);
    assert_eq!(conquest.cities[&city].captured_from, None);
}

/// A developed conquest under heavy pressure is razed too: it revolts in
/// the same three or four turns as a small one and returns to the enemy
/// developed (live Antium, kept at turn 158 and lost at 161).
/// A captured six-population Antium under heavy Loyalty pressure, six tiles
/// from our nearest city. Returns the board and the captured city.
fn heavy_pressure_capture() -> (Game, u32) {
    let mut game = Game::new_full(2, 30, 18, 107_002, 120, 0, false);
    for pid in 0..2 {
        game.current = pid;
        let settler = game
            .player_unit_ids(pid)
            .into_iter()
            .find(|unit| game.units[unit].kind == "settler")
            .unwrap();
        game.apply(pid, &Action::FoundCity { unit: settler })
            .unwrap();
    }
    let home = game.player_city_ids(0)[0];
    let rival_capital = game.player_city_ids(1)[0];
    let rival_pos = game.cities[&rival_capital].pos;
    let outpost_pos = game
        .wdisk(rival_pos, 4)
        .into_iter()
        .find(|position| {
            game.wdist(*position, rival_pos) == 4
                && game.wdist(*position, game.cities[&home].pos) > 9
                && game.city_at(*position).is_none()
                && game.map.tiles[position].owner_city.is_none()
        })
        .expect("test map has an isolated rival outpost site");
    {
        let tile = game.map.tiles.get_mut(&outpost_pos).unwrap();
        tile.terrain = crate::name!("grassland");
        tile.feature = None;
        tile.hills = false;
    }
    game.cities.get_mut(&rival_capital).unwrap().pop = 40;
    game.cities.get_mut(&home).unwrap().pop = 3;
    let outpost = game.found_city_for(1, outpost_pos, Some("Antium".to_string()));
    {
        let captured = game.cities.get_mut(&outpost).unwrap();
        captured.owner = 0;
        captured.pop = 6;
        captured.loyalty = 50.0;
        captured.captured_from = Some(1);
        captured.occupied_from = Some(1);
    }
    game.current = 0;
    // A core city six tiles away: the isolated-outpost rule does not apply.
    let near_home_pos = game
        .wdisk(outpost_pos, 6)
        .into_iter()
        .find(|position| {
            game.wdist(*position, outpost_pos) == 6
                && game.city_at(*position).is_none()
                && game.map.tiles[position].owner_city.is_none()
                && game.rules.is_passable(&game.map.tiles[position])
                && !game.rules.is_water(&game.map.tiles[position])
        })
        .expect("test map has a core site six tiles from the captured outpost");
    game.cities.get_mut(&home).unwrap().pos = near_home_pos;
    let delta = AdvancedAi::population_loyalty_delta(&game, 0, outpost);
    assert!(
        delta <= HEAVY_LOYALTY_PRESSURE && 50.0 / -delta <= 4.0,
        "fixture: heavy pressure, a revolt within four turns ({delta})"
    );
    let city = &game.cities[&outpost];
    let development = city.pop.max(1) as f64 * 6.0
        + city.districts.len() as f64 * 12.0
        + city.wonders.len() as f64 * 35.0;
    assert!(
        development >= 35.0,
        "fixture: a developed city ({development})"
    );
    (game, outpost)
}

