#[test]
fn occupation_reserves_a_reachable_garrison_during_war() {
    let mut game = Game::new_full(3, 26, 16, 108, 80, 1, false);
    let city = game
        .players
        .iter()
        .find(|player| player.is_minor && !player.is_barbarian)
        .and_then(|minor| game.player_city_ids(minor.id).first().copied())
        .unwrap();
    {
        let occupied = game.cities.get_mut(&city).unwrap();
        occupied.owner = 0;
        occupied.captured_from = None;
        occupied.occupied_from = Some(1);
        occupied.loyalty = 35.0;
    }
    for unit in game.player_unit_ids(0) {
        game.remove_unit(unit);
    }
    let city_pos = game.cities[&city].pos;
    for unit in game.units_at(city_pos) {
        game.remove_unit(unit);
    }
    let start = game
        .nbrs(city_pos)
        .into_iter()
        .find(|position| {
            game.map
                .get(*position)
                .is_some_and(|tile| game.rules.is_passable(tile) && !game.rules.is_water(tile))
                && game.unit_ids_at(*position).is_empty()
        })
        .unwrap();
    let warrior = game.spawn_test_unit("warrior", 0, start);
    game.at_war.insert((0, 1));
    let plan = StrategicPlan {
        strategy: GrandStrategy::Conquest,
        target_player: Some(1),
        target_city: game.player_city_ids(1).first().copied(),
        threatened_city: None,
        desired_cities: 4,
        assessed_turn: game.turn,
        rush: false,
    };
    let mut ai = AdvancedAi::new();

    assert_eq!(
        ai.occupation_garrison_target(&game, 0, warrior),
        Some(city_pos)
    );
    assert!(ai.advanced_military_step(&mut game, 0, warrior, &plan));
    assert_eq!(game.units[&warrior].pos, city_pos);
}

/// `occupation_garrison_target` ranks the candidates and routes only until one
/// answers. Pin it to the direct reading it replaced -- route every unit, then
/// take the nearest, weakest, lowest id -- over several occupied cities that
/// compete for the same units.
#[test]
fn occupation_garrison_matches_routing_every_candidate() {
    let mut game = Game::new_full(3, 26, 16, 108, 80, 1, false);
    let anchor = game
        .cities
        .values()
        .find(|city| city.owner != 0)
        .map(|city| city.pos)
        .unwrap();
    while game.cities.values().filter(|city| city.owner != 0).count() < 3 {
        let site = game
            .wdisk(anchor, 8)
            .into_iter()
            .find(|pos| {
                game.map.get(*pos).is_some_and(|tile| {
                    tile.owner_city.is_none()
                        && game.rules.is_passable(tile)
                        && !game.rules.is_water(tile)
                }) && game
                    .cities
                    .values()
                    .all(|city| game.wdist(city.pos, *pos) >= 4)
            })
            .expect("fixture has room near the city-state");
        game.found_city_for(1, site, None);
    }
    let cities: Vec<u32> = game
        .cities
        .values()
        .filter(|city| city.owner != 0)
        .map(|city| city.id)
        .collect();
    for unit in game.player_unit_ids(0) {
        game.remove_unit(unit);
    }
    for (index, city) in cities.iter().enumerate() {
        let occupied = game.cities.get_mut(city).unwrap();
        occupied.owner = 0;
        occupied.captured_from = None;
        occupied.occupied_from = Some(1);
        occupied.loyalty = 30.0 + 10.0 * index as f64;
        let city_pos = occupied.pos;
        for unit in game.units_at(city_pos) {
            game.remove_unit(unit);
        }
        let posts: Vec<Pos> = game
            .wdisk(city_pos, 3)
            .into_iter()
            .filter(|position| {
                *position != city_pos
                    && game.map.get(*position).is_some_and(|tile| {
                        game.rules.is_passable(tile) && !game.rules.is_water(tile)
                    })
                    && game.unit_ids_at(*position).is_empty()
            })
            .step_by(4)
            .take(3)
            .collect();
        for (post, kind) in posts.into_iter().zip(["warrior", "spearman", "warrior"]) {
            game.spawn_test_unit(kind, 0, post);
        }
    }
    game.at_war.insert((0, 1));
    let ai = AdvancedAi::new();
    let routed_every_candidate = |g: &Game, uid: u32| -> Option<Pos> {
        let mut demand: Vec<_> = g
            .cities
            .values()
            .filter(|city| city.owner == 0 && city.occupied_from.is_some())
            .filter(|city| {
                !g.unit_ids_at(city.pos).iter().any(|unit| {
                    g.units[unit].owner == 0
                        && g.rules.units[g.units[unit].kind].class == "military"
                })
            })
            .collect();
        demand.sort_by(|left, right| {
            ai.conversion_garrison_priority(g, left)
                .total_cmp(&ai.conversion_garrison_priority(g, right))
                .then_with(|| left.id.cmp(&right.id))
        });
        let mut available: BTreeSet<u32> = g
            .player_unit_ids(0)
            .into_iter()
            .filter(|unit| g.rules.units[g.units[unit].kind].class == "military")
            .collect();
        for city in demand {
            let selected = available
                .iter()
                .filter(|unit| {
                    g.units[unit].pos == city.pos || g.route_step(**unit, city.pos, 0).is_some()
                })
                .min_by_key(|unit| {
                    (
                        g.wdist(g.units[unit].pos, city.pos),
                        g.unit_strength(&g.units[unit], true) as i32,
                        **unit,
                    )
                })
                .copied();
            if let Some(selected) = selected {
                available.remove(&selected);
                if selected == uid {
                    return Some(city.pos);
                }
            }
        }
        None
    };
    let units = game.player_unit_ids(0);
    assert!(units.len() >= 4);
    let mut assigned = 0;
    for uid in units {
        let target = ai.occupation_garrison_target(&game, 0, uid);
        assert_eq!(target, routed_every_candidate(&game, uid), "unit {uid}");
        assigned += usize::from(target.is_some());
    }
    assert!(assigned >= 2, "only {assigned} garrisons assigned");
}

/// Fires-check for `city_strategy`. The control must stamp nothing at all,
/// and the treatment must stamp exactly one directive per owned city
/// carrying the lane in force. A treatment that changes no state cannot
/// change a decision, so this is the screen that has to pass before any
/// eval is worth its compute.
#[test]
fn city_strategy_stamps_one_directive_per_city_and_the_control_stamps_none() {
    let mut game = Game::new_full(2, 24, 16, 411_001, 120, 1, false);
    found_test_city(&mut game, 0);
    found_test_city(&mut game, 0);
    let cities = game.player_city_ids(0);
    assert!(cities.len() >= 2, "need a multi-city seat to type roles");

    let mut control = AdvancedAi::new();
    control.take_turn(&mut game.clone(), 0);
    assert!(
        game.players[0].city_directives.is_empty(),
        "the shipped agent must not express a directive"
    );

    let mut treated = AdvancedAi::new();
    treated.city_strategy = true;
    treated.take_turn(&mut game, 0);

    let stamped = &game.players[0].city_directives;
    assert_eq!(
        stamped.len(),
        game.player_city_ids(0).len(),
        "every owned city gets exactly one directive"
    );
    for cid in game.player_city_ids(0) {
        assert!(stamped.contains_key(&cid), "city {cid} was left unstamped");
    }
}

/// The whole point of the channel: the same city works different tiles
/// under different empire objectives. If a Science lane and a Culture lane
/// produce identical governor weights the directive is decorative.
#[test]
fn the_lane_reaches_the_tile_the_citizen_works() {
    let science = AdvancedAi::lane_emphasis(GrandStrategy::Science, 0.0);
    let culture = AdvancedAi::lane_emphasis(GrandStrategy::Culture, 0.0);
    let conquest = AdvancedAi::lane_emphasis(GrandStrategy::Conquest, 0.0);
    assert!(science.science > culture.science);
    assert!(culture.culture > science.culture);
    assert!(conquest.production > science.production);

    let mut game = Game::new_full(2, 24, 16, 411_002, 120, 1, false);
    let city = found_test_city(&mut game, 0);
    let shipped = game.citizen_strategy(city);

    game.players[0].city_directives.insert(
        city,
        CityDirective {
            emphasis: science,
            role: CityRole::Balanced,
            pressure: 0.0,
            halt_growth: false,
        },
    );
    let under_science = game.citizen_strategy(city);
    assert!(
        under_science.weights.science > shipped.weights.science,
        "a science empire must want science tiles more than the default does"
    );
    // Additive, not a takeover: everything the local evidence said is
    // still there underneath.
    assert_eq!(under_science.weights.food, shipped.weights.food);
    assert_eq!(under_science.weights.culture, shipped.weights.culture);

    game.players[0].city_directives.insert(
        city,
        CityDirective {
            emphasis: culture,
            role: CityRole::Balanced,
            pressure: 0.0,
            halt_growth: false,
        },
    );
    let under_culture = game.citizen_strategy(city);
    assert!(under_culture.weights.culture > under_science.weights.culture);
    assert!(under_culture.weights.science < under_science.weights.science);
}

/// Military awareness is per city, not per empire. A Bastion wants hammers
/// and refuses to grow into a siege; local pressure raises the hammer
/// appetite on its own axis, so a city being approached reacts before the
/// empire-wide alarm names it.
#[test]
fn a_pressed_city_wants_hammers_and_a_bastion_stops_growing() {
    let mut game = Game::new_full(2, 24, 16, 411_003, 120, 1, false);
    let city = found_test_city(&mut game, 0);
    let calm = game.citizen_strategy(city);

    game.players[0].city_directives.insert(
        city,
        CityDirective {
            emphasis: Yields::default(),
            role: CityRole::Balanced,
            pressure: 0.6,
            halt_growth: false,
        },
    );
    let approached = game.citizen_strategy(city);
    assert!(
        approached.weights.production > calm.weights.production,
        "a city with a hostile force in reach must want production"
    );
    assert_eq!(
        approached.food_target, calm.food_target,
        "pressure alone raises hammers; it does not halt growth"
    );

    game.players[0].city_directives.insert(
        city,
        CityDirective {
            emphasis: Yields::default(),
            role: CityRole::Bastion,
            pressure: 0.6,
            halt_growth: false,
        },
    );
    let besieged = game.citizen_strategy(city);
    assert!(besieged.weights.production > approached.weights.production);
    // ⚠ A Bastion wants hammers and KEEPS GROWING. The opposite -- cutting
    // its food weight and refusing a growth surplus -- reads as obviously
    // correct and is the single mechanism the per-rung bisect convicted:
    // isolated over 120 paired maps it scores 43.8%, Elo -44 at p=0.0107,
    // and costs a fifth of the empire's cities. A besieged city that stops
    // growing does not become safer, only permanently smaller.
    assert_eq!(
        besieged.food_target, calm.food_target,
        "a bastion must not trade away its own growth"
    );
    assert_eq!(besieged.weights.food, calm.weights.food);

    game.players[0].city_directives.insert(
        city,
        CityDirective {
            emphasis: Yields::default(),
            role: CityRole::Bastion,
            pressure: 0.6,
            halt_growth: true,
        },
    );
    let halted = game.citizen_strategy(city);
    assert!(halted.weights.food < calm.weights.food);
    assert_eq!(
        halted.food_target,
        2.0 * game.cities[&city].pop as f64,
        "the frozen control still expresses the measured-worse stance"
    );
    // Nutrition is never traded away, even under the losing stance.
    assert!(halted.food_target >= 2.0 * game.cities[&city].pop as f64);
}

#[test]
fn city_pressure_ignores_a_hidden_hostile_inside_its_radius() {
    let mut game = Game::new_full(2, 30, 18, 411_005, 120, 0, false);
    for unit in game.player_unit_ids(1) {
        game.remove_unit(unit);
    }
    let city = found_test_city(&mut game, 0);
    let city_pos = game.cities[&city].pos;
    game.at_war.insert((0, 1));

    let visible = game.player_visibility(0);
    let candidates =
        game.wdisk(city_pos, 6)
            .into_iter()
            .filter(|position| {
                *position != city_pos
                    && game.city_at(*position).is_none()
                    && game.unit_ids_at(*position).is_empty()
                    && game.map.get(*position).is_some_and(|tile| {
                        game.rules.is_passable(tile) && !game.rules.is_water(tile)
                    })
            })
            .collect::<Vec<_>>();
    let hidden = candidates
        .iter()
        .copied()
        .find(|position| !visible.contains(position))
        .expect("test city has a hidden passable tile within pressure radius");
    let seen = candidates
        .iter()
        .copied()
        .find(|position| visible.contains(position))
        .expect("test city has a visible passable tile within pressure radius");

    let hidden_warrior = game.spawn_test_unit("warrior", 1, hidden);
    assert_eq!(
        AdvancedAi::city_pressure(&game, 0, city),
        0.0,
        "an unseen hostile must not contribute city pressure"
    );
    game.remove_unit(hidden_warrior);

    game.spawn_test_unit("warrior", 1, seen);
    assert!(
        AdvancedAi::city_pressure(&game, 0, city) > 0.0,
        "the same force must count once it is visible"
    );
}

#[test]
fn campaign_city_score_uses_the_last_seen_city_combat_state() {
    let mut game = Game::new_full(2, 30, 18, 411_007, 120, 0, false);
    let settler = game
        .player_unit_ids(1)
        .into_iter()
        .find(|unit| game.units[unit].kind == "settler")
        .expect("second player has a settler");
    game.current = 1;
    game.apply(1, &Action::FoundCity { unit: settler })
        .expect("foreign city can be founded");
    let city = game.player_city_ids(1)[0];
    let city_pos = game.cities[&city].pos;
    for unit in game.units.keys().copied().collect::<Vec<_>>() {
        game.remove_unit(unit);
    }

    let observer = game.spawn_test_unit("scout", 0, city_pos);
    let mut ai = AdvancedAi::new();
    ai.belief.observe(&game, 0);
    assert!(
        ai.remembered_city(city).is_some(),
        "the City Center was seen"
    );
    game.remove_unit(observer);
    assert!(
        !game.player_visibility(0).contains(&city_pos),
        "the City Center returns to fog before its live state changes"
    );

    let before = ai.campaign_city_value(&game, 0, &game.cities[&city], GrandStrategy::Conquest);
    {
        let target = game.cities.get_mut(&city).unwrap();
        target.hp = 1;
        target.wall_hp = 0;
    }
    game.spawn_test_unit("giant_death_robot", 1, city_pos);
    let after = ai.campaign_city_value(&game, 0, &game.cities[&city], GrandStrategy::Conquest);

    assert_eq!(
        before, after,
        "a hidden heal, breach, or garrison cannot rewrite the remembered campaign score"
    );
}

/// ★★★★ A camp that stands for 130 turns (civvis-20260816T200454Z): the
/// home guard's recall budget is half the army with the garrison charged
/// against it — a three-unit peacetime army with one unit in the capital
/// has a cap of zero — and the camp ranks below every raider inside the
/// six-tile ring, which with a camp raising raiders is always. See
/// `BasicAi::camp_party`. In peacetime the whole field army answers: with
/// one unit garrisoned and two in the field, both field units get an
/// objective, and with a raider five tiles out and the camp at the edge of
/// the raider radius, the camp — ranked as a raider three tiles out — is
/// answered first and the raider by the next unit; a raider at the gates
/// still comes first; a scout is never sent; the withheld arm keeps its cap
/// of zero.
///
/// ⚠ The camp sat at seven tiles until 2026-08-21, which only reached the
/// guard because `enable_live_bridge_universe` also set the nine-tile
/// `camp-reach`. That gene left the code with the ranking's bottom ten (it
/// was already withheld at deployment, so this is the radius the shipped
/// seat has been playing all along); the camp moved inside the raider
/// radius so this test measures the party and not the reach. ⚠ Inside that
/// radius a held camp is TWO threat rows — the camp and the raider standing
/// on it — each sized to the same defender, so the party doubles. That
/// double-count is `barbarian_response_objective`'s, not the party's; naming it
/// here rather than tuning a number nobody could explain later.
#[test]
fn in_peacetime_the_whole_field_army_answers_and_the_camp_outranks_the_countryside() {
    let mut game = Game::new_full(2, 30, 20, 90_078, 60, 0, true);
    for player in 0..2 {
        let settler = game
            .player_unit_ids(player)
            .into_iter()
            .find(|uid| game.units[uid].kind == "settler")
            .expect("each player opens with a settler");
        game.current = player;
        game.apply(player, &Action::FoundCity { unit: settler })
            .unwrap();
    }
    for player in 0..2 {
        for uid in game.player_unit_ids(player) {
            game.remove_unit(uid);
        }
    }
    let barb = game.barb_pid.expect("a barbarian-seated game has barb_pid");
    for uid in game.units.keys().copied().collect::<Vec<_>>() {
        if game.units[&uid].owner == barb {
            game.remove_unit(uid);
        }
    }
    game.barb_camps.clear();
    game.current = 0;
    let home = game.cities[&game.player_city_ids(0)[0]].pos;
    let open = |g: &Game, pos: Pos| {
        g.map
            .get(pos)
            .is_some_and(|tile| g.rules.is_passable(tile) && !g.rules.is_water(tile))
            && g.city_at(pos).is_none()
            && g.unit_ids_at(pos).is_empty()
    };
    let ring_at = |g: &Game, distance: i32| -> Vec<Pos> {
        let mut ring: Vec<Pos> = g
            .map
            .tiles
            .keys()
            .copied()
            .filter(|pos| g.wdist(*pos, home) == distance && open(g, *pos))
            .collect();
        ring.sort_unstable();
        ring
    };
    let camp = ring_at(&game, 6)[0];
    game.barb_camps.insert(camp, game.turn);
    game.map.tiles.get_mut(&camp).unwrap().improvement = Some(crate::name!("barbarian_camp"));
    // A spearman holds the camp: the party is sized to it, so one warrior
    // is not enough.
    let _defender = game.spawn_test_unit("spearman", barb, camp);
    // Four warriors — one in the capital, three a tile out — and a scout.
    let mut field: Vec<u32> = vec![game.spawn_test_unit("warrior", 0, home)];
    let field_ring: Vec<Pos> = ring_at(&game, 1);
    field.extend(
        field_ring
            .iter()
            .take(3)
            .map(|pos| game.spawn_test_unit("warrior", 0, *pos)),
    );
    let scout = game.spawn_test_unit("scout", 0, ring_at(&game, 2)[0]);
    let objectives = |ai: &AdvancedAi, g: &Game| -> Vec<Option<Pos>> {
        field
            .iter()
            .map(|uid| ai.base.barbarian_response_objective(g, 0, *uid, &[barb]))
            .collect()
    };

    let mut live = AdvancedAi::new();
    live.enable_live_bridge_universe();
    assert!(live.camp_party(), "the live seat carries the party");
    let sent = objectives(&live, &game);
    assert_eq!(
        sent.iter().filter(|o| **o == Some(camp)).count(),
        4,
        "a spearman-held camp inside the raider radius draws two parties of two — \
         one for the camp, one for the raider standing on it, each sized to the \
         same spearman (25 × 1.25 = 31 > one warrior's 20): {sent:?}"
    );
    assert_eq!(
        live.base
            .barbarian_response_objective(&game, 0, scout, &[barb]),
        None,
        "a scout is not sent to clear a camp"
    );

    // The withheld arm sizes a camp party at zero — exactly one unit —
    // and would send nobody at all had the capital's warrior been counted
    // as garrison (the measured game: floor(3 × 0.5) − 1 = 0).
    let mut withheld = AdvancedAi::new();
    withheld.enable_live_bridge_universe();
    withheld.disable_camp_party();
    let held = objectives(&withheld, &game);
    assert!(
        held.iter().filter(|o| **o == Some(camp)).count() <= 1,
        "the withheld arm sends at most one unit to a camp: {held:?}"
    );

    // A raider five tiles out ranks below the camp; one at the gates above.
    let far_pos = ring_at(&game, 5)
        .into_iter()
        .find(|pos| game.wdist(*pos, camp) >= 3)
        .expect("open ground five out, away from the camp");
    let far = game.spawn_test_unit("warrior", barb, far_pos);
    let sent = objectives(&live, &game);
    assert!(
        sent.contains(&Some(camp)) && sent.contains(&Some(far_pos)),
        "the camp is answered before a raider in the countryside, and the raider by \
             the next unit: {sent:?}"
    );
    game.remove_unit(far);
    let gate_pos = ring_at(&game, 2)
        .into_iter()
        .find(|pos| game.unit_ids_at(*pos).is_empty())
        .expect("open ground at the gates");
    let _gate = game.spawn_test_unit("warrior", barb, gate_pos);
    let sent = objectives(&live, &game);
    assert!(
        sent.contains(&Some(gate_pos)),
        "a raider at the gates is answered first: {sent:?}"
    );

    assert!(!AdvancedAi::new().camp_party());
    assert!(!AdvancedAi::legacy().camp_party());
}

/// Remove construction-time barbarians from a non-barbarian fixture. Production
/// tests that are about culture, science, or wartime ceilings should not have
/// their queue changed by a random camp that happens to spawn near the city;
/// barbarian-specific tests install their own camps and units explicitly.
fn clear_barbarian_fixture(game: &mut Game) {
    if let Some(barb) = game.barb_pid {
        for uid in game
            .units
            .values()
            .filter(|unit| unit.owner == barb)
            .map(|unit| unit.id)
            .collect::<Vec<_>>()
        {
            game.remove_unit(uid);
        }
    }
    game.barb_camps.clear();
    game.barb_naval_camps.clear();
    game.barb_camp_guards.clear();
    game.barb_scout_homes.clear();
    game.barb_scout_targets.clear();
    game.barb_camp_targets.clear();
    game.barb_alerted_until.clear();
}

/// Board for the camp-errand pins: two founded capitals, no stray units,
/// no camps, `current = 0`. Returns the game, player 0's capital, and a
/// placer for open ground at an exact distance from it.
/// ★★★★★ WE DO NOT LOSE THE FIGHTS; WE DO NOT TAKE ENOUGH OF THEM.
///
/// MEASURED over every live run since the melee bridge was repaired (#2223),
/// from `combat` events: our melee attacks **kill 119 of 225 (53 %) and lose
/// the attacker 6 times (2.7 %)**; our ranged attacks kill 34 of 65 and have
/// **never** lost the attacker. Our swings are good. The barbarians simply
/// take **867 attacks against our 290**, which is why the early window trades
/// at 0.71 in their favour.
///
/// `attack_threshold` prices a raider the way it prices Persia. It is not the
/// same fight: no war weariness, no retaliation invited, no peace to lose, the
/// camp respawns whatever we do, and killing the unit is the only exit from
/// the zone-of-control lock that strands our Settlers. `barbarian_bargain` is
/// that difference as one number.
#[test]
fn a_raider_is_cheaper_to_attack_than_a_major_and_only_for_a_soldier() {
    let (mut game, home) = camp_bounty_board(90_079);
    let barb = game.barb_pid.unwrap();
    let ring = open_ground_at(&game, home, 4);
    let beside = *crate::hex::neighbors(ring)
        .iter()
        .find(|pos| {
            game.map
                .get(**pos)
                .is_some_and(|tile| game.rules.is_passable(tile) && !game.rules.is_water(tile))
                && game.unit_ids_at(**pos).is_empty()
                && game.city_at(**pos).is_none()
        })
        .expect("open ground beside the ring tile");
    let soldier = game.spawn_test_unit("warrior", 0, ring);
    let raider = game.spawn_test_unit("warrior", barb, beside);

    let mut plain = AdvancedAi::new();
    plain.base.barbarian_bargain = false;
    let mut priced = AdvancedAi::new();
    priced.base.barbarian_bargain = true;
    let full = plain.base.attack_threshold(&game, soldier, beside);
    let cheap = priced.base.attack_threshold(&game, soldier, beside);
    assert_eq!(
        full - cheap,
        crate::ai::BARBARIAN_BARGAIN_DISCOUNT,
        "attacking a raider must cost exactly the discount less"
    );

    // A rival's unit on the same tile is priced at full: this is about who the
    // enemy is, not about the tile.
    game.remove_unit(raider);
    let rival = game.spawn_test_unit("warrior", 1, beside);
    assert_eq!(
        priced.base.attack_threshold(&game, soldier, beside),
        plain.base.attack_threshold(&game, soldier, beside),
        "a major's unit is the same price with the gene on"
    );

    // ⚠ And it must not turn a Scout into a casualty. The Recon doctrine adds
    // +14; an 8-point discount must leave that term firmly positive.
    // The Recon doctrine term is +14, and the discount must never cancel it or
    // a Scout would be talked into a fight it cannot win.
    game.remove_unit(rival);
    let mut scout_priced = AdvancedAi::new();
    scout_priced.base.barbarian_bargain = true;
    let scout = game.spawn_test_unit("scout", 0, ring);
    let raider_again = game.spawn_test_unit("warrior", barb, beside);
    assert!(
        scout_priced.base.attack_threshold(&game, scout, beside) > 0.0,
        "a Scout must still be priced out of attacking a raider"
    );
    let _ = raider_again;
}

/// ★★★★★ WE ANSWER SLINGERS AND ARCHERS WITH SPEARMEN.
///
/// `barbarian_defense_item` asks for a melee-capable land defender whatever the
/// ring is made of. MEASURED across every live run since the melee bridge was
/// repaired: the barbarians take **45 % of their 867 attacks ranged** while we
/// take **22 % of our 290** that way — and ranged is the safe half of the
/// board. Our 65 ranged attacks killed 34 and lost the attacker **zero** times;
/// our 225 melee attacks killed 119 and lost 6. A Spearman walking at an Archer
/// eats the shot going in and the counter on arrival.
#[test]
fn a_ring_of_shooters_is_answered_by_a_shooter_and_a_melee_ring_is_not() {
    let ranged_answer = |shooters: usize, brawlers: usize, gene: bool| -> Option<String> {
        let (mut game, home) = camp_bounty_board(90_079);
        let barb = game.barb_pid.unwrap();
        let cid = game.player_city_ids(0)[0];
        let mut ring: Vec<Pos> = game
            .map
            .tiles
            .keys()
            .copied()
            .filter(|pos| {
                game.wdist(*pos, home) == 2
                    && game.map.get(*pos).is_some_and(|tile| {
                        game.rules.is_passable(tile) && !game.rules.is_water(tile)
                    })
                    && game.unit_ids_at(*pos).is_empty()
                    && game.city_at(*pos).is_none()
            })
            .collect();
        ring.sort_unstable();
        for (placed, kind) in std::iter::repeat_n("archer", shooters)
            .chain(std::iter::repeat_n("warrior", brawlers))
            .enumerate()
        {
            let pos = ring[placed];
            game.spawn_test_unit(kind, barb, pos);
        }
        let mut ai = AdvancedAi::new();
        ai.base.barbarian_ranged_answer = gene;
        match ai.base.barbarian_defense_item(&game, 0, cid) {
            Some(Item::Unit { unit }) => Some(unit.to_string()),
            _ => None,
        }
    };
    let (probe, _) = camp_bounty_board(90_079);
    let shoots = |name: &str| {
        probe
            .rules
            .units
            .iter()
            .find(|(key, _)| key.as_str() == name)
            .map(|(_, spec)| spec.has_ranged_attack())
            .unwrap_or(false)
    };
    let shooter_ring = ranged_answer(2, 0, true).expect("a ring of archers asks for a defender");
    assert!(
        shoots(&shooter_ring),
        "a ring of shooters must be answered by a shooter, got {shooter_ring}"
    );
    let same_ring_without = ranged_answer(2, 0, false).expect("still asks for a defender");
    assert!(
        !shoots(&same_ring_without),
        "without the gene the historical melee answer stands, got {same_ring_without}"
    );
    // A melee ring keeps the melee answer with the gene ON: this changes WHICH
    // defender, never how many, and only when the ring is genuinely shooters.
    let brawler_ring = ranged_answer(0, 2, true).expect("a melee ring asks for a defender");
    assert!(
        !shoots(&brawler_ring),
        "a melee ring must keep its melee answer, got {brawler_ring}"
    );
}

fn camp_bounty_board(seed: u64) -> (Game, Pos) {
    let mut game = Game::new_full(2, 30, 20, seed, 120, 0, true);
    for player in 0..2 {
        let settler = game
            .player_unit_ids(player)
            .into_iter()
            .find(|uid| game.units[uid].kind == "settler")
            .expect("each player opens with a settler");
        game.current = player;
        game.apply(player, &Action::FoundCity { unit: settler })
            .unwrap();
    }
    for player in 0..2 {
        for uid in game.player_unit_ids(player) {
            game.remove_unit(uid);
        }
    }
    let barb = game.barb_pid.expect("a barbarian-seated game has barb_pid");
    for uid in game.units.keys().copied().collect::<Vec<_>>() {
        if game.units[&uid].owner == barb {
            game.remove_unit(uid);
        }
    }
    game.barb_camps.clear();
    game.current = 0;
    let home = game.cities[&game.player_city_ids(0)[0]].pos;
    (game, home)
}

fn open_ground_at(game: &Game, home: Pos, distance: i32) -> Pos {
    let open = |pos: Pos| {
        game.map
            .get(pos)
            .is_some_and(|tile| game.rules.is_passable(tile) && !game.rules.is_water(tile))
            && game.city_at(pos).is_none()
            && game.unit_ids_at(pos).is_empty()
    };
    let mut ring: Vec<Pos> = game
        .map
        .tiles
        .keys()
        .copied()
        .filter(|pos| game.wdist(*pos, home) == distance && open(*pos))
        .collect();
    ring.sort_unstable();
    ring.into_iter()
        .next()
        .expect("open ground at the distance")
}

/// The errand's own gates, pinned at the function: a major war stands it
/// down, a scout is never a bounty hunter, an outmatched hunter declines,
/// and the claim ledger caps the party at two camps with one hunter each.
#[test]
fn the_camp_errand_stands_down_for_war_recon_and_bad_trades() {
    let (mut game, home) = camp_bounty_board(90_080);
    let barb = game.barb_pid.unwrap();
    let near = open_ground_at(&game, home, 4);
    game.barb_camps.insert(near, game.turn + 1_000);
    game.map.tiles.get_mut(&near).unwrap().improvement = Some(crate::name!("barbarian_camp"));

    let mut ai = AdvancedAi::new();
    ai.enable_camp_bounty();
    let hunter = game.spawn_test_unit("swordsman", 0, home);
    assert_eq!(
        ai.base.camp_bounty_target(&game, 0, hunter),
        Some(near),
        "an empty camp four tiles out is the errand"
    );

    // A scout is never a bounty hunter, even though an empty camp prices
    // above the recon attack threshold.
    let scout = game.spawn_test_unit("scout", 0, home);
    assert_eq!(ai.base.camp_bounty_target(&game, 0, scout), None);

    // An outmatched hunter declines the guarded camp.
    game.spawn_test_unit("musketman", barb, near);
    let mut fresh = AdvancedAi::new();
    fresh.enable_camp_bounty();
    assert_eq!(
        fresh.base.camp_bounty_target(&game, 0, hunter),
        None,
        "a swordsman does not trade into a fortress-era guard"
    );

    // A major war stands the whole errand down.
    let guard = game.unit_ids_at(near)[0];
    game.remove_unit(guard);
    let mut wartime = AdvancedAi::new();
    wartime.enable_camp_bounty();
    game.at_war.insert((0, 1));
    game.at_war.insert((1, 0));
    assert_eq!(wartime.base.camp_bounty_target(&game, 0, hunter), None);
    game.at_war.remove(&(0, 1));
    game.at_war.remove(&(1, 0));

    // Two camps, three hunters: each camp gets one hunter, the third unit
    // keeps its ordinary job.
    let far = open_ground_at(&game, home, 5);
    game.barb_camps.insert(far, game.turn + 1_000);
    game.map.tiles.get_mut(&far).unwrap().improvement = Some(crate::name!("barbarian_camp"));
    let second = game.spawn_test_unit("swordsman", 0, home);
    let third = game.spawn_test_unit("swordsman", 0, home);
    let mut party = AdvancedAi::new();
    party.enable_camp_bounty();
    let first_claim = party.base.camp_bounty_target(&game, 0, hunter);
    let second_claim = party.base.camp_bounty_target(&game, 0, second);
    assert_eq!(first_claim, Some(near));
    assert_eq!(second_claim, Some(far));
    assert_eq!(
        party.base.camp_bounty_target(&game, 0, third),
        None,
        "two claims is the whole party"
    );

    assert!(!AdvancedAi::new().base.camp_bounty);
    assert!(!AdvancedAi::legacy().base.camp_bounty);
}

/// The adjacent camp clear ships default-ON, but this gate keeps the controller
/// treatment outside `AdvancedAi::legacy()` — the frozen anchor whose
/// fingerprint `advanced_v1_plays_the_same_game_it_always_did` pins — exactly
/// like `naval_recon`. A shared world rule may still own a protocol bump; this
/// withhold arm prices the current-controller treatment instead.
#[test]
fn the_adjacent_camp_clear_cannot_reach_the_frozen_anchor() {
    assert!(
        !AdvancedAi::legacy().adjacent_camp_clear(),
        "this controller treatment must stay outside the frozen anchor; an \
         anchor move needs a protocol decision owned by the world rule"
    );
    assert!(AdvancedAi::new().adjacent_camp_clear());
}

/// The dedicated barbarian response before the campaign march, mirroring the
/// Basic step's precedence.
#[test]
fn a_barbarian_raider_at_home_is_answered_without_a_major_war() {
    let mut game = Game::new_full(2, 30, 20, 90_077, 60, 0, true);
    for player in 0..2 {
        let settler = game
            .player_unit_ids(player)
            .into_iter()
            .find(|uid| game.units[uid].kind == "settler")
            .expect("each player opens with a settler");
        game.current = player;
        game.apply(player, &Action::FoundCity { unit: settler })
            .unwrap();
    }
    for player in 0..2 {
        for uid in game.player_unit_ids(player) {
            game.remove_unit(uid);
        }
    }
    let barb = game.barb_pid.expect("a barbarian-seated game has barb_pid");
    // Clear construction-time barbarians so the scenario holds exactly the
    // raider under test.
    for uid in game.units.keys().copied().collect::<Vec<_>>() {
        if game.units[&uid].owner == barb {
            game.remove_unit(uid);
        }
    }
    game.current = 0;
    let home = game.cities[&game.player_city_ids(0)[0]].pos;
    let open = |g: &Game, pos: Pos| {
        g.map
            .get(pos)
            .is_some_and(|tile| g.rules.is_passable(tile) && !g.rules.is_water(tile))
            && g.city_at(pos).is_none()
            && g.unit_ids_at(pos).is_empty()
    };
    // Inside the home ring, outside the garrison alarm: the field
    // response, not the city garrison, is what must answer.
    let raider_at = game
        .wdisk(home, crate::ai::HOME_THREAT_RADIUS - 1)
        .into_iter()
        .filter(|pos| {
            open(&game, *pos) && game.wdist(*pos, home) > crate::ai::GARRISON_ALERT_RADIUS
        })
        .min()
        .expect("the home ring has open land");
    game.spawn_test_unit("warrior", barb, raider_at);
    // Three tiles out: the first step toward the raider is unambiguously
    // safe (still outside a warrior's move-and-attack reach), so a mover
    // that received the objective has no cautious reason to hold.
    let soldier_at = game
        .wdisk(raider_at, 3)
        .into_iter()
        .filter(|pos| open(&game, *pos) && game.wdist(*pos, raider_at) == 3)
        .min()
        .expect("open land three tiles from the raider");
    let soldier = game.spawn_test_unit("warrior", 0, soldier_at);

    assert!(
        BasicAi::barbarian_presence_at_home_with_camp_radius(
            &game,
            0,
            crate::ai::HOME_THREAT_RADIUS
        ),
        "precondition: the raider stands within the home threat radius"
    );
    assert!(
        !game
            .players
            .iter()
            .any(|p| p.id != 0 && !p.is_barbarian && game.is_at_war(0, p.id)),
        "precondition: no major war is running, which is exactly when the \
             old enemy list went empty"
    );

    // The step is exercised directly, the way the relief-column test does:
    // this is a test of the enemy list and the objective ordering, not of
    // battlefront vision, and a spawned raider starts fogged.
    let plan = StrategicPlan {
        strategy: GrandStrategy::Expansion,
        target_player: None,
        target_city: None,
        threatened_city: None,
        desired_cities: 3,
        assessed_turn: game.turn,
        rush: false,
    };
    let mut ai = AdvancedAi::new();
    ai.battlefront_observation = false;
    assert_eq!(
        ai.base
            .barbarian_response_objective(&game, 0, soldier, &[barb]),
        Some(raider_at),
        "the dedicated barbarian response must claim this unit without a major war"
    );
    let acted = ai.advanced_military_step(&mut game, 0, soldier, &plan);
    assert!(
        acted,
        "the soldier must act on the raider rather than fall through to \
             the peacetime path"
    );

    let closed = game
        .units
        .get(&soldier)
        .is_some_and(|unit| game.wdist(unit.pos, raider_at) < 3);
    let answered = game
        .units
        .values()
        .find(|unit| unit.owner == barb)
        .map(|raider| raider.hp < 100)
        .unwrap_or(true);
    assert!(
        closed || answered,
        "a raider pillaging at home must draw the soldier in or take a hit; \
             the soldier stood at {:?} with the raider untouched at {raider_at:?}",
        game.units.get(&soldier).map(|unit| unit.pos)
    );
}

/// A kill that is already legal this turn is not a campaign order.  In
/// particular, a barbarian need not be inside the bounded response list:
/// leaving a one-health raider alive beside an available Warrior is never the
/// staging discipline this controller is trying to preserve.
#[test]
fn immediate_kill_priority_finishes_barbarians_and_wartime_units() {
    let mut game = Game::new_full(2, 30, 20, 90_079, 60, 0, true);
    for pid in 0..2 {
        game.current = pid;
        let settler = game
            .player_unit_ids(pid)
            .into_iter()
            .find(|uid| game.units[uid].kind == "settler")
            .expect("each major starts with a Settler");
        game.apply(pid, &Action::FoundCity { unit: settler })
            .expect("fixture capitals must be founded");
    }
    for uid in game.units.keys().copied().collect::<Vec<_>>() {
        game.remove_unit(uid);
    }
    game.barb_camps.clear();
    game.barb_naval_camps.clear();
    let barb = game.barb_pid.expect("a barbarian-seated game has barb_pid");
    game.current = 0;
    game.at_war.insert((0, 1));

    let mut open: Vec<Pos> = game
        .map
        .tiles
        .iter()
        .filter(|(pos, tile)| {
            game.rules.is_passable(tile)
                && !game.rules.is_water(tile)
                && game.city_at(**pos).is_none()
                && game.unit_ids_at(**pos).is_empty()
        })
        .map(|(pos, _)| *pos)
        .collect();
    open.sort_unstable();
    let (civ_target, civ_attacker_at) = open
        .iter()
        .copied()
        .find_map(|target| {
            game.nbrs(target)
                .into_iter()
                .find(|attacker| open.contains(attacker))
                .map(|attacker| (target, attacker))
        })
        .expect("fixture needs an adjacent open civ duel");
    let (barb_target, barb_attacker_at) = open
        .iter()
        .copied()
        .filter(|target| {
            game.wdist(*target, civ_target) > 4 && game.wdist(*target, civ_attacker_at) > 4
        })
        .find_map(|target| {
            game.nbrs(target)
                .into_iter()
                .find(|attacker| {
                    open.contains(attacker)
                        && game.wdist(*attacker, civ_target) > 4
                        && game.wdist(*attacker, civ_attacker_at) > 4
                })
                .map(|attacker| (target, attacker))
        })
        .expect("fixture needs a separate adjacent barbarian duel");
    let enemy_reserve_at = open
        .iter()
        .copied()
        .find(|position| {
            [civ_target, civ_attacker_at, barb_target, barb_attacker_at]
                .iter()
                .all(|other| game.wdist(*position, *other) > 6)
        })
        .expect("fixture needs a distant enemy survivor");

    let civ_attacker = game.spawn_test_unit("warrior", 0, civ_attacker_at);
    let barb_attacker = game.spawn_test_unit("warrior", 0, barb_attacker_at);
    let wartime_target = game.spawn_test_unit("warrior", 1, civ_target);
    let barbarian_target = game.spawn_test_unit("warrior", barb, barb_target);
    game.spawn_test_unit("warrior", 1, enemy_reserve_at);
    game.units.get_mut(&wartime_target).unwrap().hp = 1;
    game.units.get_mut(&barbarian_target).unwrap().hp = 1;
    assert!(
        game.is_at_war(0, 1),
        "the civilization target is a war enemy"
    );
    assert!(
        game.is_at_war(0, barb),
        "barbarians are hostile without a declaration"
    );

    let plan = StrategicPlan {
        strategy: GrandStrategy::Conquest,
        target_player: Some(1),
        target_city: None,
        threatened_city: None,
        desired_cities: 3,
        assessed_turn: game.turn,
        rush: false,
    };
    let mut ai = AdvancedAi::new();
    let legal = game.legal_actions_within(0, ActionFamilies::UNITS);
    let finished = ai.prioritize_immediate_kills(&mut game, 0, &plan, &BTreeSet::new());
    assert_eq!(
        finished, 2,
        "each available positive exchange must finish its removable target; \
         legal={legal:?}, log={:?}",
        game.log
    );
    assert!(!game.units.contains_key(&wartime_target));
    assert!(!game.units.contains_key(&barbarian_target));
    let finishers = [civ_attacker, barb_attacker];
    assert!(
        game.log
            .iter()
            .filter(|(_, action)| {
                matches!(action, Action::Attack { unit, target }
                if finishers.contains(unit) && [civ_target, barb_target].contains(target))
            })
            .count()
            >= 2,
        "the kills must be combat strikes, not a movement side effect: {:?}",
        game.log
    );
}

/// The full unit-turn pipeline must take the same finish before its normal
/// barbarian campaign filter runs.  A distant raider is deliberately not a
/// barbarian-response objective, but an adjacent one-hit kill is still immediate
/// combat rather than a request to start chasing camps across the map.
#[test]
fn advanced_turn_finishes_a_distant_barbarian_before_campaign_filtering() {
    let mut game = Game::new_full(2, 30, 20, 90_080, 60, 0, true);
    for pid in 0..2 {
        game.current = pid;
        let settler = game
            .player_unit_ids(pid)
            .into_iter()
            .find(|uid| game.units[uid].kind == "settler")
            .expect("each major starts with a Settler");
        game.apply(pid, &Action::FoundCity { unit: settler })
            .expect("fixture capitals must be founded");
    }
    for uid in game.units.keys().copied().collect::<Vec<_>>() {
        game.remove_unit(uid);
    }
    game.barb_camps.clear();
    game.barb_naval_camps.clear();
    game.current = 0;
    let home = game.cities[&game.player_city_ids(0)[0]].pos;
    let barb = game.barb_pid.expect("a barbarian-seated game has barb_pid");
    let target =
        game.map
            .tiles
            .iter()
            .filter(|(position, tile)| {
                game.wdist(**position, home) > crate::ai::HOME_THREAT_RADIUS + 1
                    && game.rules.is_passable(tile)
                    && !game.rules.is_water(tile)
                    && game.city_at(**position).is_none()
                    && game.unit_ids_at(**position).is_empty()
            })
            .map(|(position, _)| *position)
            .find(|target| {
                game.nbrs(*target).into_iter().any(|attacker| {
                    game.map.get(attacker).is_some_and(|tile| {
                        game.rules.is_passable(tile) && !game.rules.is_water(tile)
                    }) && game.city_at(attacker).is_none()
                })
            })
            .expect("fixture needs a distant open barbarian duel");
    let attacker_at = game
        .nbrs(target)
        .into_iter()
        .find(|position| {
            game.map
                .get(*position)
                .is_some_and(|tile| game.rules.is_passable(tile) && !game.rules.is_water(tile))
                && game.city_at(*position).is_none()
        })
        .expect("target needs a passable melee tile");
    let attacker = game.spawn_test_unit("warrior", 0, attacker_at);
    let raider = game.spawn_test_unit("warrior", barb, target);
    game.units.get_mut(&raider).unwrap().hp = 1;
    assert!(
        !BasicAi::barbarian_presence_at_home_with_camp_radius(
            &game,
            0,
            crate::ai::HOME_THREAT_RADIUS
        ),
        "the raider must stay outside the normal bounded barbarian target list"
    );

    let plan = StrategicPlan {
        strategy: GrandStrategy::Expansion,
        target_player: None,
        target_city: None,
        threatened_city: None,
        desired_cities: 3,
        assessed_turn: game.turn,
        rush: false,
    };
    let mut ai = AdvancedAi::new();
    ai.advanced_units(&mut game, 0, &plan);

    assert!(!game.units.contains_key(&raider));
    assert!(
        game.log.iter().any(|(_, action)| {
            matches!(action, Action::Attack { unit, target: struck }
                if *unit == attacker && *struck == target)
        }),
        "the full Advanced turn must issue the distant finishing strike: {:?}",
        game.log
    );
}

/// ★★★★★ A HOME RAIDER MUST NOT FREEZE THE REST OF A PRE-WAR ARMY.
///
/// The live bridge intentionally puts the barbarian seat in `enemies`
/// while a raider threatens a city. That made the controller leave the
/// `enemies.is_empty()` branch, which contains `campaign_staging_step`.
/// Consequently, the bounded barbarian-response assignment did not merely claim
/// its responder: it paused every unclaimed assault unit until the raider
/// disappeared. On live run `civvis-20260815T190904Z`, Rome held off its
/// Netherlands declaration from turns 95 through 104 despite 337--462
/// power against 69--76, while home raiders remained in range.
#[test]
fn a_distant_campaign_unit_stays_staged_while_barbarians_are_at_home() {
    let mut game = Game::new_full(2, 30, 20, 90_078, 120, 0, true);
    for tile in game.map.tiles.values_mut() {
        tile.terrain = crate::name!("grassland");
        tile.feature = None;
        tile.hills = false;
    }
    for uid in game.units.keys().copied().collect::<Vec<_>>() {
        game.remove_unit(uid);
    }

    let mut land: Vec<Pos> = game.map.tiles.keys().copied().collect();
    land.sort();
    let mut sites = None;
    'find_sites: for home in &land {
        for objective in &land {
            if game.wdist(*home, *objective) >= 16
                && game.wdisk(*home, crate::ai::HOME_THREAT_RADIUS).len() >= 24
                && game.wdisk(*objective, 4).len() >= 18
            {
                sites = Some((*home, *objective));
                break 'find_sites;
            }
        }
    }
    let (home, objective_site) = sites.expect("the map has separated interior city sites");
    for (player, site) in [(0, home), (1, objective_site)] {
        game.current = player;
        let settler = game.spawn_test_unit("settler", player, site);
        game.apply(player, &Action::FoundCity { unit: settler })
            .expect("each chosen site can found a city");
    }
    game.current = 0;
    game.record_contact(0, 1);
    let target_city = game.player_city_ids(1)[0];
    let objective = game.cities[&target_city].pos;
    let barb = game.barb_pid.expect("a barbarian-seated game has barb_pid");
    for uid in game.units.keys().copied().collect::<Vec<_>>() {
        if game.units[&uid].owner == barb {
            game.remove_unit(uid);
        }
    }
    let open = |g: &Game, pos: Pos| {
        g.map
            .get(pos)
            .is_some_and(|tile| g.rules.is_passable(tile) && !g.rules.is_water(tile))
            && g.city_at(pos).is_none()
            && g.unit_ids_at(pos).is_empty()
    };
    let raider_at = game
        .wdisk(home, crate::ai::HOME_THREAT_RADIUS - 1)
        .into_iter()
        .filter(|pos| open(&game, *pos))
        .max_by_key(|pos| (game.wdist(*pos, objective), *pos))
        .expect("the home ring has an open land tile");
    game.spawn_test_unit("warrior", barb, raider_at);
    let staging_at = game
        .wdisk(objective, 4)
        .into_iter()
        .filter(|pos| {
            open(&game, *pos)
                && game.wdist(*pos, objective) == 4
                && game.wdist(*pos, raider_at) > 10
                && game.nbrs(*pos).into_iter().any(|next| {
                    game.wdist(next, objective) == 3
                        && game.map.get(next).is_some_and(|tile| {
                            tile.owner_city
                                .and_then(|city| game.cities.get(&city))
                                .is_none_or(|city| city.owner != 1)
                        })
                })
        })
        .max_by_key(|pos| (game.wdist(*pos, raider_at), *pos))
        .expect("a legal staging tile remains outside the home-recall range");
    let assault = game.spawn_test_unit("swordsman", 0, staging_at);
    let plan = StrategicPlan {
        strategy: GrandStrategy::Conquest,
        target_player: Some(1),
        target_city: Some(target_city),
        threatened_city: None,
        desired_cities: 3,
        assessed_turn: game.turn,
        rush: false,
    };
    let mut ai = AdvancedAi::new();
    ai.battlefront_observation = false;

    assert!(
        BasicAi::barbarian_presence_at_home_with_camp_radius(
            &game,
            0,
            crate::ai::HOME_THREAT_RADIUS
        ),
        "precondition: the barbarian is inside Rome's home-threat ring"
    );
    assert!(
        ai.campaign_staging_position(&game, 0, 1, assault, objective, staging_at),
        "precondition: the assault unit already occupies a lawful 3--5 staging tile"
    );
    assert_eq!(
        ai.base
            .barbarian_response_objective(&game, 0, assault, &[barb]),
        None,
        "the assault unit is beyond the bounded recall range and stays unclaimed"
    );

    // This is the old fall-through: it treats the foreign city as a
    // tactical destination even though the only actual enemy is the
    // barbarian, and walks a correctly staged unit one tile closer.
    let mut historic = game.clone();
    let historic_ai = ai.clone();
    assert!(
        historic_ai
            .base
            .tactical_step(&mut historic, 0, assault, objective, &[barb], 1),
        "precondition: the old tactical fallback would abandon the staging ring"
    );
    assert_ne!(
        historic.units[&assault].pos, staging_at,
        "the historical fallback must move the staged unit before this regression is meaningful"
    );

    let _ = ai.advanced_military_step(&mut game, 0, assault, &plan);
    assert_eq!(
            game.units[&assault].pos, staging_at,
            "after bounded defenders get first claim, the unclaimed assault unit must hold its campaign staging tile"
        );
    assert!(
            game.units[&assault].fortified,
            "the campaign staging order must claim and hold the assault unit while the home raider is active"
        );
    assert!(
        !game.is_at_war(0, 1),
        "the pre-war staging treatment must not open the major war itself"
    );
}

/// A passable, empty land tile exactly `distance` from `home`, at least
/// `clear` hexes from every `(tile, clear)` in `away`, with at least `room`
/// such tiles beside it; lowest coordinates first so the pick is
/// deterministic.
fn clear_land_at(game: &Game, home: Pos, distance: i32, away: &[(Pos, i32)], room: usize) -> Pos {
    let open = |pos: Pos| {
        game.map.get(pos).is_some_and(|tile| {
            game.rules.is_passable(tile)
                && !game.rules.is_water(tile)
                && game.city_at(pos).is_none()
                && game.unit_ids_at(pos).is_empty()
        })
    };
    let mut candidates: Vec<Pos> = game
        .map
        .tiles
        .keys()
        .copied()
        .filter(|pos| game.wdist(*pos, home) == distance && open(*pos))
        .filter(|pos| {
            away.iter()
                .all(|(other, clear)| game.wdist(*pos, *other) >= *clear)
        })
        .filter(|pos| {
            game.nbrs(*pos)
                .into_iter()
                .filter(|beside| open(*beside))
                .count()
                >= room
        })
        .collect();
    candidates.sort_unstable();
    *candidates
        .first()
        .unwrap_or_else(|| panic!("no clear land tile {distance} hexes from {home:?}"))
}

/// An empty land neighbour of `of`, lowest coordinates first.
fn clear_land_beside(game: &Game, of: Pos, not: &[Pos]) -> Pos {
    let mut candidates: Vec<Pos> = game
        .nbrs(of)
        .into_iter()
        .filter(|pos| {
            game.map.get(*pos).is_some_and(|tile| {
                game.rules.is_passable(tile)
                    && !game.rules.is_water(tile)
                    && game.city_at(*pos).is_none()
                    && game.unit_ids_at(*pos).is_empty()
            }) && !not.contains(pos)
        })
        .collect();
    candidates.sort_unstable();
    *candidates
        .first()
        .unwrap_or_else(|| panic!("no clear land tile beside {of:?}"))
}

/// ★★★★★ A FOGGED OBJECTIVE IS NOT A DOMINATED ONE.
///
/// `local_strength_ratio` returns `3.0` — its maximum, "we dominate here" —
/// whenever `hostile <= 0.0`, and that condition cannot tell ground we can
/// see and is empty apart from ground we simply cannot see.
/// `blind_objective_strength` repaired the `g.city_at(objective)` term, but
/// an objective that is not a city has nothing left but the *visible*
/// enemy units within six tiles.
///
/// ⚠⚠⚠ Measured on live run `civvis-20260803T200117Z` (finished, t251), by
/// splitting every force-group decision on whether a known enemy city stood
/// on its objective: of **982** decisions, **523 (53.3%)** read the `3.00`
/// sentinel, and **355 of those — 68% — had no city on the objective**, so
/// no repair could reach them. The army read maximum local superiority on
/// more than a third of every decision it made, in a game it lost 343 to
/// 1214 while never once declaring war.
#[test]
fn a_fogged_objective_is_not_a_dominated_one() {
    let mut game = Game::new_full(2, 30, 18, 411_009, 120, 0, false);
    for unit in game.units.keys().copied().collect::<Vec<_>>() {
        game.remove_unit(unit);
    }
    game.players[0].met.insert(1);
    game.players[1].met.insert(0);
    game.apply(0, &Action::DeclareWar { player: 1 })
        .expect("the seats can go to war");

    // Any two land tiles far enough apart that our own force cannot see the
    // objective. The objective is deliberately NOT a city: that is the
    // population the existing repair cannot reach.
    let mut land: Vec<Pos> = game
        .map
        .tiles
        .iter()
        .filter(|(_, tile)| !game.rules.is_water(tile))
        .map(|(pos, _)| *pos)
        .collect();
    land.sort();
    let objective = land[0];
    let staging = *land
        .iter()
        .find(|pos| game.wdist(**pos, objective) == 5)
        .expect("a land tile five hexes from the objective");

    let ours = game.spawn_test_unit("warrior", 0, staging);
    game.spawn_test_unit("warrior", 1, objective);

    // See it once, then lose sight of it. The enemy never moves and never
    // changes: the only thing that changes is whether we are looking.
    let observer = game.spawn_test_unit("scout", 0, objective);
    let mut ai = AdvancedAi::new();
    ai.belief.observe(&game, 0);
    game.remove_unit(observer);
    assert!(
        !game.player_visibility(0).contains(&objective),
        "the objective must be back in fog, or this measures nothing"
    );

    let units = [ours];
    let enemies = [1usize];

    ai.disable_blind_objective_units();
    let blind = ai.local_strength_ratio(&game, 0, &units, &enemies, objective);
    ai.enable_blind_objective_units();
    let believing = ai.local_strength_ratio(&game, 0, &units, &enemies, objective);

    assert_eq!(
        blind, 3.0,
        "without the repair a fogged objective reads as the maximum — this is \
             the defect, and it fired on 53.3% of force decisions in a live game"
    );
    assert!(
        believing < 3.0,
        "an enemy this controller has SEEN standing on the objective must still \
             count against it once it goes back into fog; got {believing}"
    );
}

#[test]
fn belief_pressure_remembers_a_hidden_contact_without_reading_current_state() {
    let mut game = Game::new_full(2, 30, 18, 411_006, 120, 0, false);
    for unit in game.player_unit_ids(1) {
        game.remove_unit(unit);
    }
    let city = found_test_city(&mut game, 0);
    let city_pos = game.cities[&city].pos;
    game.at_war.insert((0, 1));

    let hidden =
        game.wdisk(city_pos, THREAT_RELIEF_RADIUS)
            .into_iter()
            .find(|position| {
                *position != city_pos
                    && game.city_at(*position).is_none()
                    && game.unit_ids_at(*position).is_empty()
                    && !game.player_visibility(0).contains(position)
                    && game.map.get(*position).is_some_and(|tile| {
                        game.rules.is_passable(tile) && !game.rules.is_water(tile)
                    })
            })
            .expect("test city has a hidden passable pressure tile");
    let enemy = game.spawn_test_unit("warrior", 1, hidden);
    let scout_candidates =
        game.wdisk(hidden, 2)
            .into_iter()
            .filter(|position| {
                *position != hidden
                    && game.city_at(*position).is_none()
                    && game.unit_ids_at(*position).is_empty()
                    && game.map.get(*position).is_some_and(|tile| {
                        game.rules.is_passable(tile) && !game.rules.is_water(tile)
                    })
            })
            .collect::<Vec<_>>();
    let scout = scout_candidates
        .into_iter()
        .find_map(|position| {
            let scout = game.spawn_test_unit("scout", 0, position);
            let sees_enemy =
                game.player_visibility(0).contains(&hidden) && game.unit_visible_to(enemy, 0);
            if sees_enemy {
                Some(scout)
            } else {
                game.remove_unit(scout);
                None
            }
        })
        .expect("an adjacent scout can observe the hidden pressure tile");

    let mut ai = AdvancedAi::new();
    ai.belief_pressure = true;
    ai.belief.observe(&game, 0);
    assert!(ai.belief.units.contains_key(&enemy));
    let observed = AdvancedAi::city_pressure(&game, 0, city);
    assert!(observed > 0.0, "the scout makes the contact visible");
    assert_eq!(
        ai.belief_city_pressure(&game, 0, city),
        observed,
        "a refreshed visible sighting must not be counted twice"
    );

    game.remove_unit(scout);
    assert!(
        !game.player_visibility(0).contains(&hidden),
        "the contact returns to fog once the scout leaves"
    );
    ai.belief.observe(&game, 0);
    assert_eq!(AdvancedAi::city_pressure(&game, 0, city), 0.0);
    let remembered = ai.belief_city_pressure(&game, 0, city);
    assert!(remembered > 0.0, "a last-seen hostile affects recovery");

    // Deleting the real hidden unit cannot change the memory term: the
    // controller is allowed to know what it saw, not what happened later.
    game.remove_unit(enemy);
    ai.belief.observe(&game, 0);
    assert_eq!(ai.belief_city_pressure(&game, 0, city), remembered);

    game.turn += BELIEF_PRESSURE_HORIZON;
    ai.belief.observe(&game, 0);
    assert_eq!(
        ai.belief_city_pressure(&game, 0, city),
        0.0,
        "a four-turn-old contact cannot sustain a recovery alarm"
    );
}

/// Factual coverage check for the evaluator arm, not an outcome claim.
/// It asks how often a current major's own observation history adds local
/// pressure, and how often that addition changes the recovery selector.
/// Run with `cargo test --profile ci belief_pressure_census -- --ignored
/// --nocapture` before spending a fresh outcome prefix.
#[test]
#[ignore = "factual mechanism census; run explicitly with --nocapture"]
fn belief_pressure_census() {
    let mut city_turns = 0u64;
    let mut memory_city_turns = 0u64;
    let mut memory_only_city_turns = 0u64;
    let mut recovery_changes = 0u64;

    for map in 0..12u64 {
        let mut game = Game::new_full(4, 44, 28, 871_000 + map, 200, 0, false);
        game.set_fog_memory(false);
        let mut fleet = AdvancedAi::fleet(&game);
        for ai in &mut fleet {
            ai.belief_pressure = true;
        }

        while game.winner.is_none() && game.turn <= game.max_turns {
            let pid = game.current;
            if !game.players[pid].is_minor && !game.players[pid].is_barbarian {
                // `take_turn` refreshes the live controller at exactly this
                // point. Clone it to audit that imminent calculation
                // without mutating the player who will actually act.
                let mut probe = fleet[pid].clone();
                probe.belief.observe(&game, pid);
                let stock = AdvancedAi::new().threatened_city(&game, pid);
                let remembered = probe.threatened_city(&game, pid);
                recovery_changes += u64::from(stock != remembered);
                for city in game.player_city_ids(pid) {
                    city_turns += 1;
                    let observed = AdvancedAi::city_pressure(&game, pid, city);
                    let pressure = probe.belief_city_pressure(&game, pid, city);
                    if pressure > observed {
                        memory_city_turns += 1;
                    }
                    if observed == 0.0 && pressure > 0.0 {
                        memory_only_city_turns += 1;
                    }
                }
            }
            fleet[pid].take_turn(&mut game, pid);
            if game.winner.is_none() && game.current == pid {
                let _ = game.apply(pid, &Action::EndTurn);
            }
        }
    }

    println!(
            "belief-pressure census: {memory_city_turns}/{city_turns} city-turns with memory, \
             {memory_only_city_turns}/{city_turns} memory-only, {recovery_changes} recovery changes"
        );
    assert!(
        memory_city_turns > 0,
        "the evaluator arm never receives a hidden remembered contact"
    );
}

/// Census, not an assertion: how often each rung of the role ladder fires
/// over real games, and what share of Bastion stamps are driven by
/// barbarians alone.
///
/// The roles half of `city_strategy` lost 120 maps at Elo -55 while the
/// emphasis half was a clean null, and the empire it produced was smaller
/// in every column (cities 2.14 against 2.77). Two candidate mechanisms
/// survive that: Bastion halting growth on barbarian contact, or
/// Forge/Specialist pulling citizens off food in empires too small for
/// `ROLE_MARGIN` to type meaningfully. Guessing between them once already
/// cost a wrong hypothesis, so this counts instead.
///
/// Run with `cargo test --release role_ladder_census -- --nocapture`.
#[test]
#[ignore = "census, not an assertion; run explicitly with --nocapture"]
fn role_ladder_census() {
    let mut totals = BTreeMap::<&str, u64>::new();
    let mut lanes = BTreeMap::<&str, u64>::new();
    let mut barbarian_only_bastions = 0u64;
    let mut pressured = 0u64;
    let mut pressure_sum = 0.0f64;
    let mut extra_hammers = 0.0f64;
    // Per-turn means hide minority behaviour, and the settler window is a
    // minority of the game. Band it.
    let mut band_turns = [0u64; 4];
    let mut band_bastions = [0u64; 4];
    let mut city_turns = 0u64;
    let mut halted_pop = 0u64;

    for map in 0..8u64 {
        let mut game = Game::new_full(4, 24, 16, 420_000 + map, 200, 1, false);
        let mut ais: Vec<AdvancedAi> = (0..game.players.len())
            .map(|_| {
                let mut ai = AdvancedAi::new();
                ai.city_strategy = true;
                ai.city_strategy_emphasis = false;
                ai
            })
            .collect();
        game.set_fog_memory(false);
        while game.winner.is_none() && game.turn <= game.max_turns {
            let pid = game.current;
            ais[pid].take_turn(&mut game, pid);
            if game.winner.is_none() && game.current == pid {
                let _ = game.apply(pid, &Action::EndTurn);
            }
            if pid != 0 {
                continue;
            }
            if let Some(plan) = ais[0].plan.as_ref() {
                *lanes.entry(plan.strategy.as_str()).or_default() += 1;
            }
            let directives = game.players[0].city_directives.clone();
            for (cid, directive) in &directives {
                let Some(city) = game.cities.get(cid) else {
                    continue;
                };
                city_turns += 1;
                *totals.entry(directive.role.as_str()).or_default() += 1;
                let band = match game.turn {
                    0..=39 => 0,
                    40..=79 => 1,
                    80..=139 => 2,
                    _ => 3,
                };
                band_turns[band] += 1;
                if directive.role == CityRole::Bastion {
                    band_bastions[band] += 1;
                }
                if directive.pressure > 0.0 {
                    pressured += 1;
                    pressure_sum += directive.pressure;
                    extra_hammers += directive.pressure.min(2.0) * 0.80;
                }
                if directive.role != CityRole::Bastion {
                    continue;
                }
                halted_pop += city.pop.max(0) as u64;
                // Recompute the same ratio with barbarians removed. If it
                // falls under the threshold, the only thing that stamped
                // this city a Bastion was a barbarian.
                let major: f64 = game
                    .units
                    .values()
                    .filter(|unit| {
                        unit.owner != 0
                            && !game.players[unit.owner].is_barbarian
                            && game.is_at_war(0, unit.owner)
                    })
                    .filter(|unit| game.wdist(city.pos, unit.pos) <= 6)
                    .filter(|unit| game.rules.units[unit.kind].class == "military")
                    .map(|unit| {
                        crate::game::effective_strength(game.unit_strength(unit, false), unit.hp)
                    })
                    .sum();
                let friendly = game.city_strength(*cid)
                    + game
                        .units
                        .values()
                        .filter(|unit| unit.owner == 0)
                        .filter(|unit| game.wdist(city.pos, unit.pos) <= 6)
                        .filter(|unit| game.rules.units[unit.kind].class == "military")
                        .map(|unit| {
                            crate::game::effective_strength(game.unit_strength(unit, true), unit.hp)
                        })
                        .sum::<f64>();
                if major / friendly.max(1.0) < BASTION_PRESSURE
                    && ais[0].plan.as_ref().and_then(|p| p.threatened_city) != Some(*cid)
                {
                    barbarian_only_bastions += 1;
                }
            }
        }
    }

    let plan_turns: u64 = lanes.values().sum();
    println!("\n=== grand strategy in force, {plan_turns} seat-turns ===");
    for (lane, count) in &lanes {
        println!(
            "  {lane:<12} {count:>6}  ({:>5.1}%)",
            *count as f64 / plan_turns.max(1) as f64 * 100.0
        );
    }
    println!("\n=== role ladder census: {city_turns} city-turns over 8 maps ===");
    for (role, count) in &totals {
        println!(
            "  {role:<12} {count:>6}  ({:>5.1}%)",
            *count as f64 / city_turns.max(1) as f64 * 100.0
        );
    }
    println!(
            "  pressure > 0 on {pressured} of {city_turns} city-turns ({:.1}%), mean {:.2} when it fires",
            pressured as f64 / city_turns.max(1) as f64 * 100.0,
            pressure_sum / pressured.max(1) as f64
        );
    println!(
            "  mean production weight added by pressure across ALL city-turns: +{:.3} (shipped weight is 1.55)",
            extra_hammers / city_turns.max(1) as f64
        );
    for (band, label) in ["t1-39", "t40-79", "t80-139", "t140+"].iter().enumerate() {
        println!(
            "  {label:<8} bastion on {:>4} of {:>5} city-turns ({:>5.1}%)",
            band_bastions[band],
            band_turns[band],
            band_bastions[band] as f64 / band_turns[band].max(1) as f64 * 100.0
        );
    }
    let bastions = totals.get("bastion").copied().unwrap_or(0);
    println!(
        "  of {bastions} bastion stamps, {barbarian_only_bastions} were BARBARIAN-ONLY ({:.1}%)",
        barbarian_only_bastions as f64 / bastions.max(1) as f64 * 100.0
    );
    println!(
            "  population under a growth halt: {halted_pop} citizen-turns ({:.1}% of all city-turns were halted)\n",
            bastions as f64 / city_turns.max(1) as f64 * 100.0
        );
}

#[test]
fn city_pressure_matrix_matches_serial_unit_order_exactly() {
    let mut game = Game::new_full(2, 30, 18, 91_210, 80, 0, false);
    let first = found_test_city(&mut game, 0);
    let second = found_test_city(&mut game, 0);
    let enemy = found_test_city(&mut game, 1);
    game.at_war.insert((0, 1));
    let positions = [
        game.cities[&first].pos,
        game.cities[&second].pos,
        game.cities[&enemy].pos,
    ];
    for index in 0..64 {
        game.spawn_test_unit(
            "warrior",
            usize::from(index % 3 == 2),
            positions[index % positions.len()],
        );
    }
    let cities = [first, second];
    let expected = cities
        .iter()
        .map(|city| AdvancedAi::city_pressure(&game, 0, *city))
        .collect::<Vec<_>>();
    let mut one = AdvancedAi::new();
    one.work_pool = Some(Arc::new(WorkPool::new(1)));
    let mut four = AdvancedAi::new();
    four.work_pool = Some(Arc::new(WorkPool::new(4)));

    assert_eq!(one.city_pressures(&game, 0, &cities), expected);
    assert_eq!(four.city_pressures(&game, 0, &cities), expected);
}

/// Census, not an assertion: how often a city faces a locally competitive
/// hostile force that `production_value`'s `threatened` flag cannot see.
///
/// `threatened` is true only when the city is *the* empire's single worst
/// (`plan.threatened_city` returns one `Option<u32>`) or when it was hit in
/// the last four turns. `threatened_city` additionally gates on
/// `danger >= 0.90`, or `>= 0.45` with a breach or a recent hit against a
/// damaged city. So a second city under siege, or any city with an army
/// standing next to it that has not struck yet, prioritises no defenses at
/// all -- which is exactly what `early_rush`'s doc comment describes as the
/// timing rule that lane plays against.
///
/// Run with `cargo test --release blind_defense_census -- --ignored --nocapture`.
/// Why do we actually lose cities? Autopsy every loss instead of guessing.
///
/// `come_ashore` cut embarked share 15.3% -> 6.3% over 30 paired maps and
/// moved cities lost only 36 -> 33, with two paired Elo A/Bs at -44 and -29
/// (both INCONCLUSIVE). So the water is real but is not what costs us
/// cities. This records the state of each city on the turn BEFORE it was
/// lost, so the binding constraint is measured rather than assumed.
#[test]
#[ignore = "census, not an assertion; run explicitly with --nocapture"]
fn city_loss_autopsy() {
    let mut lost = 0u64;
    let mut besieged = 0u64; // hp below full: something was shooting it
    let mut full_hp = 0u64; // lost at full hp => not a siege at all
    let mut garrisoned = 0u64; // a combat unit stood on the tile
    let mut help_within_3 = 0u64; // our military within 3 tiles
    let mut help_within_6 = 0u64;
    let mut no_help_at_all = 0u64;
    let mut enemy_adjacent = 0u64;
    let mut our_army_total = 0u64;
    let mut razed = 0u64;
    let mut taken_by_enemy = 0u64;
    let mut taken_by_minor = 0u64;
    let mut flipped_peacefully = 0u64;
    let mut revolted = 0u64;
    let mut enemy_dist_hist = [0u64; 8];
    let mut beyond_alert = 0u64;
    let mut could_strike = 0u64;
    for map in 0..30u64 {
        let mut game = Game::new_full(4, 32, 20, 770_000 + map, 200, 1, false);
        let mut ais: Vec<AdvancedAi> = (0..game.players.len())
            .map(|_| {
                let mut ai = AdvancedAi::new();
                ai.enable_live_bridge();
                ai
            })
            .collect();
        game.set_fog_memory(false);
        let mut owned: std::collections::HashSet<u32> =
            game.player_city_ids(0).into_iter().collect();
        // Snapshot of what each city looked like last time we saw it:
        // (pop, food, starving, production, gold, science, districts).
        type CitySnapshot = (i32, i32, bool, i32, i32, i32, usize);
        let mut snap: std::collections::HashMap<u32, CitySnapshot> =
            std::collections::HashMap::new();
        let mut dist_snap: std::collections::HashMap<u32, (i32, i32)> =
            std::collections::HashMap::new();
        while game.winner.is_none() && game.turn <= game.max_turns {
            let pid = game.current;
            ais[pid].take_turn(&mut game, pid);
            if game.winner.is_none() && game.current == pid {
                let _ = game.apply(pid, &Action::EndTurn);
            }
            if pid != 0 {
                continue;
            }
            let now: std::collections::HashSet<u32> = game.player_city_ids(0).into_iter().collect();
            for gone in owned.difference(&now) {
                // Ground truth the live export cannot give: who holds it now.
                // ⚠ A revolt transfers the city to the FREE CITIES player,
                // which we count as at war — so `is_at_war` alone reads a
                // revolt as a conquest. Check `is_free_city` FIRST.
                match game.cities.get(gone).map(|c| c.owner) {
                    None => razed += 1,
                    Some(other) if game.players.get(other).is_some_and(|p| p.is_free_city) => {
                        revolted += 1
                    }
                    Some(other) if game.is_at_war(0, other) => taken_by_enemy += 1,
                    Some(other) if game.players.get(other).is_some_and(|p| p.is_minor) => {
                        taken_by_minor += 1
                    }
                    Some(_) => flipped_peacefully += 1,
                }
                let Some(&(hp, maxhp, garrison, near3, near6, adj, army)) = snap.get(gone) else {
                    continue;
                };
                lost += 1;
                our_army_total += army as u64;
                if let Some(&(ed, reach)) = dist_snap.get(gone) {
                    enemy_dist_hist[(ed.min(7)) as usize] += 1;
                    if ed > crate::ai::GARRISON_ALERT_RADIUS {
                        beyond_alert += 1;
                    }
                    if reach > 0 {
                        could_strike += 1;
                    }
                }
                if hp < maxhp {
                    besieged += 1;
                } else {
                    full_hp += 1;
                }
                if garrison {
                    garrisoned += 1;
                }
                if near3 > 0 {
                    help_within_3 += 1;
                }
                if near6 > 0 {
                    help_within_6 += 1;
                }
                if near6 == 0 {
                    no_help_at_all += 1;
                }
                if adj > 0 {
                    enemy_adjacent += 1;
                }
            }
            owned = now;
            let army = game
                .player_unit_ids(0)
                .into_iter()
                .filter(|u| game.rules.units[game.units[u].kind].class == "military")
                .count();
            for cid in game.player_city_ids(0) {
                let city = &game.cities[&cid];
                let pos = city.pos;
                let hp = city.hp;
                // Cities cap at 200 hp; `Game` clamps to that in its own scoring.
                let maxhp = 200;
                let garrison = game.unit_ids_at(pos).iter().any(|u| {
                    let unit = &game.units[u];
                    unit.owner == 0 && game.rules.units[unit.kind].class == "military"
                });
                let mut near3 = 0;
                let mut near6 = 0;
                let mut adj = 0;
                let mut enemy_dist = 99i32;
                let mut reach = 0i32;
                for unit in game.units.values() {
                    if game.rules.units[unit.kind].class != "military" {
                        continue;
                    }
                    let d = game.wdist(unit.pos, pos);
                    if unit.owner == 0 {
                        if d <= 3 {
                            near3 += 1;
                        }
                        if d <= 6 {
                            near6 += 1;
                        }
                    } else if game.is_at_war(0, unit.owner) {
                        if d <= 1 {
                            adj += 1;
                        }
                        if d < enemy_dist {
                            enemy_dist = d;
                        }
                        // How far this unit could come and still strike.
                        let mv = game.rules.units[unit.kind].moves.max(1.0) as i32;
                        let rng = game.unit_attack_range(unit.id).max(1);
                        if d <= mv + rng {
                            reach += 1;
                        }
                    }
                }
                snap.insert(cid, (hp, maxhp, garrison, near3, near6, adj, army));
                dist_snap.insert(cid, (enemy_dist, reach));
            }
        }
    }
    let garrison_calls = crate::ai::GARRISON_STEP_CALLS.load(std::sync::atomic::Ordering::Relaxed);
    println!("garrison_step reached {garrison_calls} times across the whole census");
    let pct = |n: u64| 100.0 * n as f64 / lost.max(1) as f64;
    println!(
        "cities lost: {lost}  (mean army alive at the moment of loss: {:.1})",
        our_army_total as f64 / lost.max(1) as f64
    );
    println!(
        "  besieged (hp < max) ....... {besieged:>3}  {:>5.1}%",
        pct(besieged)
    );
    println!(
        "  lost at FULL hp ........... {full_hp:>3}  {:>5.1}%  <- not a siege",
        pct(full_hp)
    );
    println!(
        "  an enemy stood ADJACENT ... {enemy_adjacent:>3}  {:>5.1}%",
        pct(enemy_adjacent)
    );
    println!(
        "  had a GARRISON ............ {garrisoned:>3}  {:>5.1}%",
        pct(garrisoned)
    );
    println!(
        "  our military within 3 ..... {help_within_3:>3}  {:>5.1}%",
        pct(help_within_3)
    );
    println!(
        "  our military within 6 ..... {help_within_6:>3}  {:>5.1}%",
        pct(help_within_6)
    );
    println!(
        "  NO military within 6 ...... {no_help_at_all:>3}  {:>5.1}%",
        pct(no_help_at_all)
    );
    println!("NEAREST ENEMY on the last turn we held it:");
    for (d, n) in enemy_dist_hist.iter().enumerate() {
        if *n > 0 {
            let label = if d >= 7 {
                "7+".to_string()
            } else {
                d.to_string()
            };
            println!(
                "    distance {label:<3} .................. {n:>3}  {:>5.1}%",
                pct(*n)
            );
        }
    }
    println!(
        "  BEYOND GARRISON_ALERT_RADIUS ({}) .. {beyond_alert:>3}  {:>5.1}%",
        crate::ai::GARRISON_ALERT_RADIUS,
        pct(beyond_alert)
    );
    println!(
        "  an enemy could MOVE+STRIKE it that turn {could_strike:>3}  {:>5.1}%",
        pct(could_strike)
    );
    println!("WHO HOLDS IT NOW (ground truth the live export cannot give):");
    println!(
        "  REVOLTED to Free Cities (loyalty 0) ... {revolted:>3}  {:>5.1}%",
        pct(revolted)
    );
    println!(
        "  taken by an enemy we are at war with .. {taken_by_enemy:>3}  {:>5.1}%",
        pct(taken_by_enemy)
    );
    println!(
        "  taken by a city-state/minor ........... {taken_by_minor:>3}  {:>5.1}%",
        pct(taken_by_minor)
    );
    println!(
        "  owner changed with NO war (revolt) .... {flipped_peacefully:>3}  {:>5.1}%",
        pct(flipped_peacefully)
    );
    println!(
        "  razed / gone .......................... {razed:>3}  {:>5.1}%",
        pct(razed)
    );
}

/// Does `come_ashore` actually reduce time spent embarked, and does it do
/// so without making units pace the shoreline?
///
/// The paired A/B came back −44 and −29 Elo (both INCONCLUSIVE) on the
/// first version of the fix, while the engine's own refusal ledger says
/// "cannot attack while embarked" is the single largest cause of a thrown
/// away attack. Those two facts only reconcile if the repair costs
/// something the Elo can see. Oscillation is the obvious candidate: pull a
/// unit ashore, let the objective pull it back to sea next turn, and the
/// army burns its movement on the beach.
///
/// `transitions` counts land→water and water→land crossings per unit-life.
/// A fix that works lowers `embarked_share` AND does not raise
/// `transitions`.
#[test]
#[ignore = "census, not an assertion; run explicitly with --nocapture"]
fn come_ashore_census() {
    for &flag in &[false, true] {
        let mut unit_turns = 0u64;
        let mut embarked = 0u64;
        let mut transitions = 0u64;
        let mut attacks_refused_embarked = 0u64;
        let mut cities_lost = 0u64;
        let mut city_damage_turns = 0u64;
        for map in 0..30u64 {
            let mut game = Game::new_full(4, 32, 20, 770_000 + map, 200, 1, false);
            let mut ais: Vec<AdvancedAi> = (0..game.players.len())
                .map(|_| {
                    let mut ai = AdvancedAi::new();
                    ai.enable_live_bridge();
                    if !flag {
                        ai.disable_come_ashore();
                    }
                    ai
                })
                .collect();
            game.set_fog_memory(false);
            let mut was_wet: std::collections::HashMap<u32, bool> =
                std::collections::HashMap::new();
            let mut owned: std::collections::HashSet<u32> =
                game.player_city_ids(0).into_iter().collect();
            let mut prev_hp: std::collections::HashMap<u32, i32> = std::collections::HashMap::new();
            while game.winner.is_none() && game.turn <= game.max_turns {
                let pid = game.current;
                ais[pid].take_turn(&mut game, pid);
                if game.winner.is_none() && game.current == pid {
                    let _ = game.apply(pid, &Action::EndTurn);
                }
                if pid != 0 {
                    continue;
                }
                let now: std::collections::HashSet<u32> =
                    game.player_city_ids(0).into_iter().collect();
                cities_lost += owned.difference(&now).count() as u64;
                owned = now;
                for cid in game.player_city_ids(0) {
                    let hp = game.cities[&cid].hp;
                    if prev_hp.insert(cid, hp).is_some_and(|was| hp < was) {
                        city_damage_turns += 1;
                    }
                }
                for uid in game.player_unit_ids(0) {
                    let unit = &game.units[&uid];
                    if game.rules.units[unit.kind].class != "military"
                        || game.rules.units[unit.kind].domain.as_deref() == Some("sea")
                    {
                        continue;
                    }
                    let wet = game.is_embarked(unit);
                    unit_turns += 1;
                    if wet {
                        embarked += 1;
                        if game.unit_attack_range(uid) >= 1 {
                            attacks_refused_embarked += 1;
                        }
                    }
                    if was_wet.insert(uid, wet).is_some_and(|prev| prev != wet) {
                        transitions += 1;
                    }
                }
            }
        }
        let share = 100.0 * embarked as f64 / unit_turns.max(1) as f64;
        let churn = 1000.0 * transitions as f64 / unit_turns.max(1) as f64;
        println!(
            "come_ashore={flag:<5} unit_turns={unit_turns:<6} embarked={share:>5.1}%  \
                 transitions/1000 unit-turns={churn:>6.1}  \
                 embarked-with-attack={attacks_refused_embarked}  \
                 CITIES_LOST={cities_lost}  city-damage-turns={city_damage_turns}"
        );
    }
}

#[test]
#[ignore = "census, not an assertion; run explicitly with --nocapture"]
fn blind_defense_census() {
    let mut city_turns = 0u64;
    let mut pressed = 0u64;
    let mut pressed_and_blind = 0u64;
    let mut blind_by_band = [0u64; 4];
    let mut band_pressed = [0u64; 4];

    for map in 0..8u64 {
        let mut game = Game::new_full(4, 24, 16, 430_000 + map, 200, 1, false);
        let mut ais: Vec<AdvancedAi> = (0..game.players.len()).map(|_| AdvancedAi::new()).collect();
        game.set_fog_memory(false);
        while game.winner.is_none() && game.turn <= game.max_turns {
            let pid = game.current;
            ais[pid].take_turn(&mut game, pid);
            if game.winner.is_none() && game.current == pid {
                let _ = game.apply(pid, &Action::EndTurn);
            }
            if pid != 0 {
                continue;
            }
            let Some(plan) = ais[0].plan.clone() else {
                continue;
            };
            let band = match game.turn {
                0..=39 => 0,
                40..=79 => 1,
                80..=139 => 2,
                _ => 3,
            };
            for cid in game.player_city_ids(0) {
                city_turns += 1;
                let pressure = AdvancedAi::city_pressure(&game, 0, cid);
                if pressure < BASTION_PRESSURE {
                    continue;
                }
                pressed += 1;
                band_pressed[band] += 1;
                let city = &game.cities[&cid];
                let threatened = plan.threatened_city == Some(cid)
                    || (city.last_attacked > 0
                        && game.turn.saturating_sub(city.last_attacked) <= 4);
                if !threatened {
                    pressed_and_blind += 1;
                    blind_by_band[band] += 1;
                }
            }
        }
    }

    println!("\n=== blind-defense census: {city_turns} city-turns over 8 maps ===");
    println!(
        "  locally competitive hostile force present on {pressed} city-turns ({:.1}%)",
        pressed as f64 / city_turns.max(1) as f64 * 100.0
    );
    println!(
        "  of those, {pressed_and_blind} were INVISIBLE to `threatened` ({:.1}%)",
        pressed_and_blind as f64 / pressed.max(1) as f64 * 100.0
    );
    for (band, label) in ["t1-39", "t40-79", "t80-139", "t140+"].iter().enumerate() {
        println!(
            "  {label:<8} {:>4} pressed, {:>4} blind ({:>5.1}%)",
            band_pressed[band],
            blind_by_band[band],
            blind_by_band[band] as f64 / band_pressed[band].max(1) as f64 * 100.0
        );
    }
    println!();
}

/// Census, not an assertion: what a city actually decides, turn by turn.
///
/// Five arms of scripted "give the city a strategy" treatment have now
/// measured null across three seeds, so this stops proposing tilts to the
/// city's decisions and asks a different question: are any of them plainly
/// *broken*? That is the question that paid last time -- the growth halt
/// was a real -38 Elo defect and no amount of reasoning about weights
/// found it, a census did.
///
/// Run with `cargo test --release city_decision_census -- --ignored --nocapture`.
#[test]
#[ignore = "census, not an assertion; run explicitly with --nocapture"]
fn city_decision_census() {
    let mut city_turns = 0u64;
    let mut idle = 0u64;
    let mut head_changes = 0u64;
    let mut stranded = 0.0f64;
    let mut kinds = BTreeMap::<&str, u64>::new();
    let mut walls_built = 0u64;
    let mut cities_seen = BTreeSet::<(u64, u32)>::new();
    let mut walled = BTreeSet::<(u64, u32)>::new();
    let mut first_wall_turn = Vec::<u32>::new();
    let mut food_now = 0.0f64;
    let mut food_ceiling = 0.0f64;
    let mut prod_now = 0.0f64;
    let mut prod_ceiling = 0.0f64;
    let mut prev_head = BTreeMap::<u32, String>::new();

    for map in 0..8u64 {
        let mut game = Game::new_full(4, 24, 16, 440_000 + map, 200, 1, false);
        let mut ais: Vec<AdvancedAi> = (0..game.players.len()).map(|_| AdvancedAi::new()).collect();
        game.set_fog_memory(false);
        prev_head.clear();
        while game.winner.is_none() && game.turn <= game.max_turns {
            let pid = game.current;
            ais[pid].take_turn(&mut game, pid);
            if game.winner.is_none() && game.current == pid {
                let _ = game.apply(pid, &Action::EndTurn);
            }
            if pid != 0 {
                continue;
            }
            for cid in game.player_city_ids(0) {
                city_turns += 1;
                cities_seen.insert((map, cid));
                let city = &game.cities[&cid];
                match city.queue.first() {
                    None => idle += 1,
                    Some(item) => {
                        let key = match item {
                            Item::Unit { .. } | Item::Formation { .. } => "unit",
                            Item::Building { .. } => "building",
                            Item::District { .. } => "district",
                            Item::Wonder { .. } => "wonder",
                            Item::Project { .. } => "project",
                            Item::Product { .. } => "product",
                            Item::Repair { .. } => "repair",
                        };
                        *kinds.entry(key).or_default() += 1;
                        let head = format!("{item:?}");
                        if prev_head.get(&cid).is_some_and(|old| *old != head) {
                            head_changes += 1;
                        }
                        prev_head.insert(cid, head);
                    }
                }
                // Production banked against builds the city walked away
                // from. `item_remaining_cost_for_city` is what the AI
                // prices a resumed build with, so progress that is not on
                // the queue head is capital sitting idle.
                stranded += city.production_progress.values().sum::<f64>();
                if city.buildings.iter().any(|b| b.contains("walls")) && walled.insert((map, cid)) {
                    walls_built += 1;
                    first_wall_turn.push(game.turn);
                }
                // How much of the city's own ceiling do the shipped
                // weights actually claim? `city_yields_weighted` is the
                // public substitution instrument `docs/OPENINGS.md` uses to
                // bound the capital's food ceiling; asking it per city-turn
                // turns that one-off into a standing measurement.
                let now = game.city_yields(cid);
                let all_food = Yields {
                    food: 10.0,
                    ..Yields::default()
                };
                let all_prod = Yields {
                    production: 10.0,
                    ..Yields::default()
                };
                food_now += now.food;
                food_ceiling += game.city_yields_weighted(cid, all_food).food;
                prod_now += now.production;
                prod_ceiling += game.city_yields_weighted(cid, all_prod).production;
            }
        }
    }

    let pct = |n: u64| n as f64 / city_turns.max(1) as f64 * 100.0;
    println!("\n=== city decision census: {city_turns} city-turns over 8 maps ===");
    println!("  idle queue          {idle:>6}  ({:>5.1}%)", pct(idle));
    println!(
        "  queue head changed  {head_changes:>6}  ({:>5.1}% of city-turns)",
        pct(head_changes)
    );
    println!(
        "  mean production stranded off the queue head: {:.1} per city-turn",
        stranded / city_turns.max(1) as f64
    );
    println!(
        "  food claimed {:.1}% of the city's own food ceiling ({:.1} of {:.1} per city-turn)",
        food_now / food_ceiling.max(1e-9) * 100.0,
        food_now / city_turns.max(1) as f64,
        food_ceiling / city_turns.max(1) as f64
    );
    println!(
        "  production claimed {:.1}% of its ceiling ({:.1} of {:.1} per city-turn)",
        prod_now / prod_ceiling.max(1e-9) * 100.0,
        prod_now / city_turns.max(1) as f64,
        prod_ceiling / city_turns.max(1) as f64
    );
    println!("  what the queue head is:");
    for (kind, count) in &kinds {
        println!("    {kind:<10} {count:>6}  ({:>5.1}%)", pct(*count));
    }
    println!(
        "  cities that ever built walls: {walls_built} of {} ({:.1}%)",
        cities_seen.len(),
        walls_built as f64 / cities_seen.len().max(1) as f64 * 100.0
    );
    first_wall_turn.sort_unstable();
    if !first_wall_turn.is_empty() {
        println!(
            "  median turn walls appeared: {}",
            first_wall_turn[first_wall_turn.len() / 2]
        );
    }
    println!();
}

/// Census, not an assertion: how good are the sites a settler actually
/// picks, against the best site it could have picked nearby?
///
/// This is the last unmeasured city decision. #532 bounded what a city
/// works (89.3% of its food ceiling, 99.5% of its production ceiling),
/// #534 bounded what it owns (perfect border growth, p=0.7283) and #542
/// bounded where its districts go (p=0.6989). All three are downstream of
/// *where the city stands*, and nothing had measured that.
///
/// It is measured rather than granted deliberately. An oracle that
/// teleports settlers cannot work here: `AdvancedAi` founds only when a
/// settler's cached `settler_targets` entry equals its current position,
/// so a relocated settler walks back to its old target and never founds.
/// The grant would fire forever, suppress the seat's expansion entirely,
/// and report a catastrophic loss that measured the harness rather than
/// the subsystem. The ratio below asks the same question and cannot lie
/// in that direction.
///
/// The comparison set is every legal site within eight tiles of the one
/// chosen — roughly a settler's remaining walk — judged by the agent's own
/// `settle_value`, with the just-founded city excluded from the minimum
/// separation rule so the chosen tile competes on equal terms.
///
/// ## ⚠ RETRACTION: the gap this census originally reported was its own bug
///
/// The first two versions of this census (#548, #550) scored the chosen
/// site **after** the city was founded, and reported that the agent sites
/// cities at 62-70% of the best available -- billed as the one unsaturated
/// city decision. That was an artifact.
///
/// `settle_value` skips any tile another city owns
/// (`if t.owner_city.is_some() && p != pos { continue; }`), and a city
/// claims its centre and all six ring-one tiles the instant it is founded.
/// Ring one carries full weight in that sum; ring two is discounted to
/// 0.45. So founding a city destroys **54.8%** of its own site's measured
/// value -- `settle_value_before_and_after_founding` measures exactly that
/// -- while rival candidates four or more tiles away keep theirs intact.
/// The census was comparing a site stripped of its best tiles against
/// rivals that still had theirs.
///
/// Scored the turn **before** founding, which is the last moment the site
/// is still what the settler was choosing between, the answer inverts:
///
/// ```text
/// against RAW settle_value            3 tiles 99.7%   8 tiles 99.7%
/// against the AGENT'S OWN objective   99.9%
/// against its OWN settle_sites here   98.8%
/// the chosen site WAS the best available on 15 of 17 foundings (88.2%)
/// worst case 95.2%; capitals 99.0%
/// ```
///
/// **Settle siting is saturated like every other city decision.** The agent
/// takes essentially all the value on offer and picks the literal best site
/// seven times in eight.
///
/// Two things corroborate it rather than resting on this one repair.
/// `settle_search_reach_census` shows the site search discards no reachable
/// ground: over 158 settler-turns the generator offered only five
/// candidates above what the search returned and **none of the five was
/// reachable**. And a per-turn re-score of stale targets was built and
/// measured **inert** in #550 -- which is what a saturated decision looks
/// like from the inside.
///
/// The distance-discount baseline stays because it is still the right one:
/// `settle_sites` ranks by `settle_value - 0.9 * distance`, so raw
/// `settle_value` is not the objective the agent pursues.
///
/// Run with `cargo test --release settle_siting_census -- --ignored --nocapture`.
#[test]
#[ignore = "census, not an assertion; run explicitly with --nocapture"]
fn settle_siting_census() {
    let ai = AdvancedAi::new();
    let mut ratios: Vec<f64> = Vec::new();
    let mut near_ratios: Vec<f64> = Vec::new();
    let mut step_away: Vec<i32> = Vec::new();
    let mut discounted_ratios: Vec<f64> = Vec::new();
    let mut offered_ratios: Vec<f64> = Vec::new();
    let mut chosen_was_best = 0u64;
    let mut founded = 0u64;
    let mut capital_ratio: Vec<f64> = Vec::new();

    for map in 0..8u64 {
        let mut game = Game::new_full(4, 24, 16, 470_000 + map, 200, 1, false);
        let mut ais: Vec<AdvancedAi> = (0..game.players.len()).map(|_| AdvancedAi::new()).collect();
        game.set_fog_memory(false);
        let mut known: BTreeSet<u32> = game.player_city_ids(0).into_iter().collect();
        while game.winner.is_none() && game.turn <= game.max_turns {
            let pid = game.current;
            // ⚠ Score every tile a settler stands on BEFORE the turn runs.
            // `settle_value` skips tiles another city owns, and a city
            // claims its centre and all six ring-one tiles the instant it
            // is founded -- ring one being the full-weight ring, against
            // 0.45 for ring two. Measured after the fact, founding a city
            // destroys 54.8% of its own site's score
            // (`settle_value_before_and_after_founding`), while rival
            // candidates four or more tiles away keep theirs intact. The
            // first version of this census did exactly that and reported a
            // siting gap that was mostly its own artifact.
            let mut pre: BTreeMap<Pos, f64> = BTreeMap::new();
            if pid == 0 {
                for uid in game.player_unit_ids(0) {
                    if game.units[&uid].kind == "settler" {
                        let pos = game.units[&uid].pos;
                        pre.insert(pos, ai.settle_value(&game, 0, pos));
                    }
                }
            }
            ais[pid].take_turn(&mut game, pid);
            if game.winner.is_none() && game.current == pid {
                let _ = game.apply(pid, &crate::game::Action::EndTurn);
            }
            if pid != 0 {
                continue;
            }
            for cid in game.player_city_ids(0) {
                if !known.insert(cid) {
                    continue;
                }
                // A city this seat gained by conquest was never sited by
                // its settler, so it says nothing about this decision.
                let city = &game.cities[&cid];
                if city.captured_from.is_some() {
                    continue;
                }
                let chosen_pos = city.pos;
                let Some(chosen) = pre.get(&chosen_pos).copied() else {
                    continue;
                };
                // Only ground this seat had actually EXPLORED counts. A
                // settler cannot choose a site nobody has seen, and
                // scoring it against one would measure the fog rather than
                // the decision.
                let best_at = |radius: i32| {
                    game.wdisk(chosen_pos, radius)
                        .into_iter()
                        .filter(|pos| {
                            let Some(tile) = game.map.get(*pos) else {
                                return false;
                            };
                            if !game.players[0].explored.contains(pos) {
                                return false;
                            }
                            if game.rules.is_water(tile)
                                || !game.rules.is_passable(tile)
                                || game.tile_is_natural_wonder(tile)
                            {
                                return false;
                            }
                            // Every other city still enforces its
                            // separation; the one just founded must not
                            // veto its own site.
                            game.cities
                                .values()
                                .filter(|other| other.id != cid)
                                .all(|other| game.wdist(other.pos, *pos) >= 4)
                        })
                        .map(|pos| ai.settle_value(&game, 0, pos))
                        .fold(chosen, f64::max)
                };
                // How far away is the better site? `settle_value` does
                // not price the walk, so a gap three tiles off is worth
                // much less than the same gap one tile off, and the
                // distance is what makes the number readable.
                let mut best_near_pos = chosen_pos;
                let mut best_near_val = chosen;
                for pos in game.wdisk(chosen_pos, 3) {
                    let Some(tile) = game.map.get(pos) else {
                        continue;
                    };
                    if !game.players[0].explored.contains(&pos)
                        || game.rules.is_water(tile)
                        || !game.rules.is_passable(tile)
                        || game.tile_is_natural_wonder(tile)
                        || !game
                            .cities
                            .values()
                            .filter(|other| other.id != cid)
                            .all(|other| game.wdist(other.pos, pos) >= 4)
                    {
                        continue;
                    }
                    let value = ai.settle_value(&game, 0, pos);
                    if value > best_near_val {
                        best_near_val = value;
                        best_near_pos = pos;
                    }
                }
                if best_near_pos != chosen_pos {
                    step_away.push(game.wdist(chosen_pos, best_near_pos));
                }
                let near = best_at(3);
                let best = best_at(8);
                // ⚠ The comparison above is against RAW `settle_value`,
                // which is not the objective this agent actually pursues.
                // `settle_sites` ranks candidates by
                // `settle_value - 0.9 * distance`, so the agent trades
                // site quality for proximity on purpose. Scoring it
                // against a function that does not charge for the walk
                // measures a preference it never held.
                let discounted = game
                    .wdisk(chosen_pos, 8)
                    .into_iter()
                    .filter(|pos| {
                        let Some(tile) = game.map.get(*pos) else {
                            return false;
                        };
                        game.players[0].explored.contains(pos)
                            && !game.rules.is_water(tile)
                            && game.rules.is_passable(tile)
                            && !game.tile_is_natural_wonder(tile)
                            && game
                                .cities
                                .values()
                                .filter(|other| other.id != cid)
                                .all(|other| game.wdist(other.pos, *pos) >= 4)
                    })
                    .map(|pos| {
                        ai.settle_value(&game, 0, pos)
                            - game.wdist(chosen_pos, pos) as f64 * SETTLE_DISTANCE_PENALTY
                    })
                    .fold(chosen, f64::max);
                discounted_ratios.push(chosen / discounted.max(1e-9));
                // And now the decisive one: what does the agent's OWN
                // candidate generator offer from this very tile? Anything
                // the two comparisons above can see that this cannot is
                // excluded by `settle_sites`' filters -- the value >= 12.0
                // floor, foreign-owned ground, the four-tile separation --
                // rather than missed by the choice.
                let offered = ai
                    .settle_sites(&game, 0, chosen_pos, 8)
                    .into_iter()
                    .map(|(_, value)| value)
                    .fold(chosen, f64::max);
                offered_ratios.push(chosen / offered.max(1e-9));
                founded += 1;
                if best <= chosen + 1e-9 {
                    chosen_was_best += 1;
                }
                near_ratios.push(chosen / near.max(1e-9));
                let ratio = chosen / best.max(1e-9);
                ratios.push(ratio);
                if known.len() == 1 {
                    capital_ratio.push(ratio);
                }
            }
        }
    }

    ratios.sort_by(f64::total_cmp);
    let mean = ratios.iter().sum::<f64>() / ratios.len().max(1) as f64;
    println!("\n=== settle siting census: {founded} cities founded over 8 maps ===");
    let near_mean = near_ratios.iter().sum::<f64>() / near_ratios.len().max(1) as f64;
    let disc_mean = discounted_ratios.iter().sum::<f64>() / discounted_ratios.len().max(1) as f64;
    println!(
        "  against RAW settle_value  -- within 3 tiles: {:.1}%   within 8 tiles: {:.1}%",
        near_mean * 100.0,
        mean * 100.0
    );
    let off_mean = offered_ratios.iter().sum::<f64>() / offered_ratios.len().max(1) as f64;
    println!(
            "  against the AGENT'S OWN objective (settle_value - {SETTLE_DISTANCE_PENALTY}/tile): {:.1}%",
            disc_mean * 100.0
        );
    println!(
        "  against what its OWN `settle_sites` generator offers here: {:.1}%",
        off_mean * 100.0
    );
    if !ratios.is_empty() {
        println!(
            "  percentiles  p10 {:.1}%   median {:.1}%   p90 {:.1}%   worst {:.1}%",
            ratios[ratios.len() / 10] * 100.0,
            ratios[ratios.len() / 2] * 100.0,
            ratios[ratios.len() * 9 / 10] * 100.0,
            ratios[0] * 100.0
        );
    }
    println!(
            "  the chosen site WAS the best available on {chosen_was_best} of {founded} foundings ({:.1}%)",
            chosen_was_best as f64 / founded.max(1) as f64 * 100.0
        );
    step_away.sort_unstable();
    if !step_away.is_empty() {
        println!(
                "  when a better site existed within 3 tiles it was a median {} tile(s) away ({} cases)",
                step_away[step_away.len() / 2],
                step_away.len()
            );
    }
    if !capital_ratio.is_empty() {
        let cap = capital_ratio.iter().sum::<f64>() / capital_ratio.len() as f64;
        println!(
            "  capitals alone: {:.1}% ({} sampled)",
            cap * 100.0,
            capital_ratio.len()
        );
    }
    println!();
}

/// Census, not an assertion: does the settler's site search discard ground
/// it could actually reach?
///
/// `settle_siting_census` establishes that the agent founds at ~65% of what
/// its own `settle_sites` generator offers from the very tile it chose, and
/// that re-scoring a stale target changes nothing. The only machinery
/// between the generator and the choice is
/// `BasicAi::first_reachable_settle_site`, which walks the value-sorted
/// candidate list **in chunks of 40** and skips an entire chunk when
/// `route_step_to_any` reaches none of it. Because the list is sorted by
/// value descending, one failed probe on the first chunk discards the forty
/// best sites at once.
///
/// Two readings, and they call for opposite conclusions:
///
/// - the skipped sites are genuinely unreachable, so the siting census
///   overstates its gap and the axis closes like the other three; or
/// - the chunked scan is throwing away reachable ground, which is a defect.
///
/// This asks each better-than-chosen candidate the route question
/// **individually**, which is the same question the chunk asks collectively,
/// and reports how the two answers differ.
///
/// Run with `cargo test --release settle_search_reach_census -- --ignored --nocapture`.
#[test]
#[ignore = "census, not an assertion; run explicitly with --nocapture"]
fn settle_search_reach_census() {
    let mut settler_turns = 0u64;
    let mut search_returned_nothing = 0u64;
    let mut better_offered = 0u64;
    let mut better_individually_reachable = 0u64;
    let mut turns_with_a_reachable_better_site = 0u64;
    let mut best_gap: Vec<f64> = Vec::new();

    for map in 0..8u64 {
        let mut game = Game::new_full(4, 24, 16, 470_000 + map, 200, 1, false);
        let mut ais: Vec<AdvancedAi> = (0..game.players.len()).map(|_| AdvancedAi::new()).collect();
        game.set_fog_memory(false);
        while game.winner.is_none() && game.turn <= game.max_turns {
            let pid = game.current;
            if pid == 0 {
                let probe = ais[0].clone();
                for uid in game.player_unit_ids(0) {
                    if game.units[&uid].kind != "settler" {
                        continue;
                    }
                    let from = game.units[&uid].pos;
                    let candidates = probe.settle_sites(&game, 0, from, 8);
                    if candidates.is_empty() {
                        continue;
                    }
                    settler_turns += 1;
                    let returned = BasicAi::first_reachable_settle_site(&game, uid, &candidates);
                    let floor = match returned {
                        Some((_, value)) => value,
                        None => {
                            search_returned_nothing += 1;
                            f64::NEG_INFINITY
                        }
                    };
                    let mut found_one = false;
                    for (pos, value) in &candidates {
                        if *value <= floor {
                            continue;
                        }
                        better_offered += 1;
                        // The same question the chunk asked collectively.
                        if *pos == from || game.route_step(uid, *pos, 0).is_some() {
                            better_individually_reachable += 1;
                            if !found_one {
                                found_one = true;
                                best_gap.push(value - floor.max(0.0));
                            }
                        }
                    }
                    if found_one {
                        turns_with_a_reachable_better_site += 1;
                    }
                }
            }
            ais[pid].take_turn(&mut game, pid);
            if game.winner.is_none() && game.current == pid {
                let _ = game.apply(pid, &crate::game::Action::EndTurn);
            }
        }
    }

    best_gap.sort_by(f64::total_cmp);
    println!("\n=== settle search reach census: {settler_turns} settler-turns over 8 maps ===");
    println!("  the search returned NOTHING on {search_returned_nothing} of them");
    println!("  candidates the generator offered above what the search returned: {better_offered}");
    println!(
            "  of those, INDIVIDUALLY reachable by the same route query: {better_individually_reachable} ({:.1}%)",
            better_individually_reachable as f64 / better_offered.max(1) as f64 * 100.0
        );
    println!(
            "  settler-turns where a strictly better REACHABLE site was skipped: {turns_with_a_reachable_better_site} ({:.1}%)",
            turns_with_a_reachable_better_site as f64 / settler_turns.max(1) as f64 * 100.0
        );
    if !best_gap.is_empty() {
        println!(
            "  when skipped, the value left behind was median {:.1} (p90 {:.1}, max {:.1})",
            best_gap[best_gap.len() / 2],
            best_gap[best_gap.len() * 9 / 10],
            best_gap[best_gap.len() - 1]
        );
    }
    println!();
}

/// Census, not an assertion: is `settle_siting_census` measuring the site
/// or measuring the city that was just built on it?
///
/// `settle_value` skips any tile another city owns:
/// `if t.owner_city.is_some() && p != pos { continue; }`. A city claims its
/// centre and all six ring-one tiles the moment it is founded, and ring one
/// carries the full weight in that sum while ring two is discounted to
/// 0.45. So scoring the chosen site *after* founding strips it of its
/// highest-weighted contributions, while rival candidates four or more
/// tiles away keep theirs intact.
///
/// If that is what `settle_siting_census` measured, its gap is an artifact
/// of the measurement rather than a fact about the decision, and the whole
/// "settle siting is the one unsaturated city axis" claim falls.
///
/// Run with `cargo test --release settle_value_before_and_after_founding -- --ignored --nocapture`.
#[test]
#[ignore = "census, not an assertion; run explicitly with --nocapture"]
fn settle_value_before_and_after_founding() {
    let scorer = AdvancedAi::new();
    let mut before_after: Vec<(f64, f64)> = Vec::new();

    for map in 0..8u64 {
        let mut game = Game::new_full(4, 24, 16, 470_000 + map, 200, 1, false);
        let mut ais: Vec<AdvancedAi> = (0..game.players.len()).map(|_| AdvancedAi::new()).collect();
        game.set_fog_memory(false);
        let mut known: BTreeSet<u32> = game.player_city_ids(0).into_iter().collect();
        while game.winner.is_none() && game.turn <= game.max_turns {
            let pid = game.current;
            // Score every tile a settler is standing on BEFORE the turn
            // runs, which is the last moment the site is still unowned.
            let mut pre: BTreeMap<Pos, f64> = BTreeMap::new();
            if pid == 0 {
                for uid in game.player_unit_ids(0) {
                    if game.units[&uid].kind == "settler" {
                        let pos = game.units[&uid].pos;
                        pre.insert(pos, scorer.settle_value(&game, 0, pos));
                    }
                }
            }
            ais[pid].take_turn(&mut game, pid);
            if game.winner.is_none() && game.current == pid {
                let _ = game.apply(pid, &crate::game::Action::EndTurn);
            }
            if pid != 0 {
                continue;
            }
            for cid in game.player_city_ids(0) {
                if !known.insert(cid) {
                    continue;
                }
                let city = &game.cities[&cid];
                if city.captured_from.is_some() {
                    continue;
                }
                if let Some(before) = pre.get(&city.pos) {
                    let after = scorer.settle_value(&game, 0, city.pos);
                    before_after.push((*before, after));
                }
            }
        }
    }

    let n = before_after.len().max(1) as f64;
    let before: f64 = before_after.iter().map(|(b, _)| b).sum::<f64>() / n;
    let after: f64 = before_after.iter().map(|(_, a)| a).sum::<f64>() / n;
    println!(
        "\n=== settle_value before and after founding: {} sites ===",
        before_after.len()
    );
    println!("  mean settle_value the turn BEFORE the city existed: {before:.1}");
    println!("  mean settle_value once the city owns its ring one:  {after:.1}");
    println!(
        "  founding the city destroys {:.1}% of its own site's measured value",
        (1.0 - after / before.max(1e-9)) * 100.0
    );
    println!();
}

/// Census, not an assertion: which conjunct actually blocks the settler?
///
/// #554 measured that handing a seat a free Settler while it is short of
/// its own city target more than doubles its win rate — 23.0% to 52.3% over
/// 300 games at p=0.0000, the only subsystem grant this harness has ever
/// returned HEADROOM for. Seats target six cities and finish with 2.1–2.8.
/// **The agent cannot afford the empire it has already decided it wants.**
///
/// That says the cost binds. It does not say *which* cost. The settler
/// branch of `production_value` is a five-way conjunction, and any one of
/// them turns the item's value into −10,000:
///
/// ```text
/// city_count + counts.settlers < plan.desired_cities   // target not met
///   && counts.settlers < in_flight_allowed             // serialization
///   && city.pop >= 2                                   // size gate
///   && expansion_open                                  // time window
///   && site.is_some()                                  // somewhere to go
/// ```
///
/// This counts, over every city-turn where the empire is short of its
/// target, which conjuncts were false. A conjunct that never fails cannot
/// be the constraint; one that fails almost always is where the settler
/// economy actually stalls. Shares sum past 100% because several can fail
/// at once, so the last block reports the turns where exactly one did —
/// those are the ones a single fix would unblock.
///
/// Run with `cargo test --release expansion_funnel_blocker_census -- --ignored --nocapture`.
#[test]
#[ignore = "census, not an assertion; run explicitly with --nocapture"]
fn expansion_funnel_blocker_census() {
    // ⚠ `ai_eval` defaults to 24x16 at 4 players, which is 96 tiles per
    // player; the recorded large comparison runs 74x46 at 6, which is 567.
    // "No settle site in reach" is exactly the kind of
    // reading that could be pure map scarcity at the small size, so both
    // are measured and reported side by side.
    for (label, players, width, height) in [
        ("eval 4p 24x16", 4usize, 24i32, 16i32),
        ("large 6p 74x46", 6, 74, 46),
    ] {
        expansion_funnel_at(label, players, width, height);
    }
}

fn expansion_funnel_at(label: &str, players: usize, width: i32, height: i32) {
    let mut short_city_turns = 0u64;
    let mut fail_serial = 0u64;
    let mut fail_pop = 0u64;
    let mut fail_window = 0u64;
    let mut fail_site = 0u64;
    let mut all_clear = 0u64;
    let mut sole_serial = 0u64;
    let mut sole_pop = 0u64;
    let mut sole_window = 0u64;
    let mut sole_site = 0u64;
    let mut settler_turns_when_clear: Vec<f64> = Vec::new();

    for map in 0..8u64 {
        let mut game = Game::new_full(players, width, height, 480_000 + map, 200, 1, false);
        let mut ais: Vec<AdvancedAi> = (0..game.players.len()).map(|_| AdvancedAi::new()).collect();
        game.set_fog_memory(false);
        while game.winner.is_none() && game.turn <= game.max_turns {
            let pid = game.current;
            if pid == 0 {
                if let Some(plan) = ais[0].plan.clone() {
                    let cities = game.player_city_ids(0);
                    let settlers = game
                        .player_unit_ids(0)
                        .into_iter()
                        .filter(|uid| game.units[uid].kind == "settler")
                        .count();
                    if cities.len() + settlers < plan.desired_cities {
                        let window = AdvancedAi::expansion_window_open(&game);
                        for cid in cities {
                            short_city_turns += 1;
                            let city = &game.cities[&cid];
                            let pos = city.pos;
                            let pop = city.pop;
                            let site = ais[0].best_settle_site(&game, 0, pos, 11).is_some();
                            // `in_flight_allowed` is 1 for the shipped
                            // agent, so serialization fails exactly when a
                            // settler already exists.
                            let serial_ok = settlers < 1;
                            let bad = [!serial_ok, pop < 2, !window, !site];
                            if bad[0] {
                                fail_serial += 1;
                            }
                            if bad[1] {
                                fail_pop += 1;
                            }
                            if bad[2] {
                                fail_window += 1;
                            }
                            if bad[3] {
                                fail_site += 1;
                            }
                            match bad.iter().filter(|b| **b).count() {
                                0 => {
                                    all_clear += 1;
                                    // Everything permits a settler. How
                                    // long would one take to pay for?
                                    let production = game.city_yields(cid).production.max(1.0);
                                    let cost = game.item_remaining_cost_for_city(
                                        0,
                                        cid,
                                        &Item::Unit {
                                            unit: "settler".into(),
                                        },
                                    );
                                    settler_turns_when_clear.push(cost / production);
                                }
                                1 => {
                                    if bad[0] {
                                        sole_serial += 1;
                                    } else if bad[1] {
                                        sole_pop += 1;
                                    } else if bad[2] {
                                        sole_window += 1;
                                    } else {
                                        sole_site += 1;
                                    }
                                }
                                _ => {}
                            }
                        }
                    }
                }
            }
            ais[pid].take_turn(&mut game, pid);
            if game.winner.is_none() && game.current == pid {
                let _ = game.apply(pid, &crate::game::Action::EndTurn);
            }
        }
    }

    let pct = |n: u64| n as f64 / short_city_turns.max(1) as f64 * 100.0;
    println!(
        "\n=== expansion funnel [{label}]: {short_city_turns} city-turns while SHORT of target ==="
    );
    println!(
        "  a settler already walking (serialization)  {fail_serial:>6}  ({:>5.1}%)",
        pct(fail_serial)
    );
    println!(
        "  city below pop 2                           {fail_pop:>6}  ({:>5.1}%)",
        pct(fail_pop)
    );
    println!(
        "  expansion window shut                      {fail_window:>6}  ({:>5.1}%)",
        pct(fail_window)
    );
    println!(
        "  no settle site in reach                    {fail_site:>6}  ({:>5.1}%)",
        pct(fail_site)
    );
    println!(
        "  NOTHING blocking — the settler was allowed {all_clear:>6}  ({:>5.1}%)",
        pct(all_clear)
    );
    println!("  turns where EXACTLY ONE conjunct failed (a single fix would unblock these):");
    println!("    serialization {sole_serial}   pop<2 {sole_pop}   window {sole_window}   no site {sole_site}");
    if !settler_turns_when_clear.is_empty() {
        let mut t = settler_turns_when_clear.clone();
        t.sort_by(f64::total_cmp);
        println!(
                "  when allowed, a settler costs a median {:.1} turns of this city's production (p90 {:.1})",
                t[t.len() / 2],
                t[t.len() * 9 / 10]
            );
    }
    println!();
}

/// Fires-check for `expansion_pays_back`, at both map scales.
///
/// The treatment exists to unblock the 31.2% of short city-turns where
/// `expansion_funnel_blocker_census` measures the shut window as the sole
/// blocker, so the thing to verify before spending an eval is that it
/// actually opens on those turns — and that it is not simply "always open",
/// which would make it a deletion of the gate rather than a payback test.
///
/// Run with `cargo test --release expansion_payback_fires -- --ignored --nocapture`.
#[test]
#[ignore = "census, not an assertion; run explicitly with --nocapture"]
fn expansion_payback_fires() {
    for (label, players, width, height) in [
        ("eval 4p 24x16", 4usize, 24i32, 16i32),
        ("large 6p 74x46", 6, 74, 46),
    ] {
        let mut agree = 0u64;
        let mut opened = 0u64;
        let mut closed = 0u64;
        for map in 0..6u64 {
            let mut game = Game::new_full(players, width, height, 480_000 + map, 200, 1, false);
            let mut ais: Vec<AdvancedAi> =
                (0..game.players.len()).map(|_| deployed_agent()).collect();
            let treated = {
                let mut ai = AdvancedAi::new();
                ai.expansion_pays_back = true;
                ai
            };
            game.set_fog_memory(false);
            while game.winner.is_none() && game.turn <= game.max_turns {
                let pid = game.current;
                if pid == 0 {
                    let flat = AdvancedAi::expansion_window_open(&game);
                    for cid in game.player_city_ids(0) {
                        let pays = treated.expansion_pays_back_for(&game, 0, cid);
                        match (flat, pays) {
                            (a, b) if a == b => agree += 1,
                            (false, true) => opened += 1,
                            (true, false) => closed += 1,
                            _ => {}
                        }
                    }
                }
                ais[pid].take_turn(&mut game, pid);
                if game.winner.is_none() && game.current == pid {
                    let _ = game.apply(pid, &crate::game::Action::EndTurn);
                }
            }
        }
        let total = agree + opened + closed;
        println!("\n=== expansion payback vs flat reserve [{label}]: {total} city-turns ===",);
        println!(
            "  agree                     {agree:>6}  ({:>5.1}%)",
            agree as f64 / total.max(1) as f64 * 100.0
        );
        println!(
            "  payback OPENS what the flat reserve shut   {opened:>6}  ({:>5.1}%)",
            opened as f64 / total.max(1) as f64 * 100.0
        );
        println!(
            "  payback SHUTS what the flat reserve opened {closed:>6}  ({:>5.1}%)",
            closed as f64 / total.max(1) as f64 * 100.0
        );
    }
    println!();
}

/// Census, not an assertion: where does an empire's production actually go,
/// and how much of it would the missing cities have cost?
///
/// This is the last open question on the expansion axis, and the axis is
/// worth closing properly because #554 measured real headroom there — a
/// free Settler while short of the city target more than doubles the win
/// rate (23.0% → 52.3%, p=0.0000), the only subsystem grant this harness
/// has ever returned HEADROOM for.
///
/// Every *decision* mechanism proposed for it has since measured null:
///
/// - the expansion window (#562): +0.12 cities, wins unmeasurable
/// - production preemption (`docs/EVAL.md` 2026-07-28): cities at end
///   **2.21 vs 2.21**, settlers started 2.46 vs 2.42
/// - the settler's own valuation: when a city is free it already picks the
///   settler, and the genuine free-city loss is only **2.6%**
/// - capital growth (`docs/OPENINGS.md` §12): every city after the first
///   arrives **later**, monotonically in the dose
///
/// That leaves one explanation standing, and it is not a decision at all:
/// **the empire cannot afford the settlers.** This measures it directly.
/// If the settler share of production is already large and the shortfall
/// would cost more than the empire ever produces, the axis is closed to
/// decision changes and the oracle's headroom is only reachable by having a
/// bigger economy — which #532 measured at 99.5% of its own ceiling.
///
/// Run with `cargo test --release production_allocation_census -- --ignored --nocapture`.
#[test]
#[ignore = "census, not an assertion; run explicitly with --nocapture"]
fn production_allocation_census() {
    for (label, players, width, height) in [
        ("eval 4p 24x16", 4usize, 24i32, 16i32),
        ("large 6p 74x46", 6, 74, 46),
    ] {
        let mut spent = BTreeMap::<&str, f64>::new();
        let mut total = 0.0f64;
        let mut end_cities = 0.0f64;
        let mut target = 0.0f64;
        let mut shortfall_cost = 0.0f64;
        let maps = 6u64;

        for map in 0..maps {
            let mut game = Game::new_full(players, width, height, 480_000 + map, 200, 1, false);
            let mut ais: Vec<AdvancedAi> =
                (0..game.players.len()).map(|_| deployed_agent()).collect();
            game.set_fog_memory(false);
            let mut prev: BTreeMap<u32, f64> = BTreeMap::new();
            while game.winner.is_none() && game.turn <= game.max_turns {
                let pid = game.current;
                ais[pid].take_turn(&mut game, pid);
                if game.winner.is_none() && game.current == pid {
                    let _ = game.apply(pid, &crate::game::Action::EndTurn);
                }
                if pid != 0 {
                    continue;
                }
                // Production is banked per item key, so the turn-over-turn
                // rise in a city's yield is what it actually spent, and the
                // queue head says on what.
                for cid in game.player_city_ids(0) {
                    let city = &game.cities[&cid];
                    let yield_now = game.city_yields(cid).production.max(0.0);
                    let key = match city.queue.first() {
                        Some(Item::Unit { unit }) if unit.as_str() == "settler" => "settler",
                        Some(Item::Unit { unit }) => {
                            if game.rules.units[unit.as_str()].class == "military" {
                                "military unit"
                            } else {
                                "civilian unit"
                            }
                        }
                        Some(Item::Formation { .. }) => "military unit",
                        Some(Item::Building { .. }) => "building",
                        Some(Item::District { .. }) => "district",
                        Some(Item::Wonder { .. }) => "wonder",
                        Some(Item::Project { .. }) => "project",
                        Some(Item::Product { .. }) => "product",
                        Some(Item::Repair { .. }) => "repair",
                        None => "idle",
                    };
                    *spent.entry(key).or_default() += yield_now;
                    total += yield_now;
                    prev.insert(cid, yield_now);
                }
            }
            let held = game.player_city_ids(0).len() as f64;
            end_cities += held;
            let want = ais[0]
                .plan
                .as_ref()
                .map(|p| p.desired_cities as f64)
                .unwrap_or(0.0);
            target += want;
            // Civ VI escalates settler cost 80/110/140/...; price the
            // cities the empire never built at that schedule.
            let missing = (want - held).max(0.0) as usize;
            let built = held.max(1.0) as usize;
            for n in 0..missing {
                shortfall_cost += 80.0 + 30.0 * (built + n) as f64;
            }
        }

        println!(
            "\n=== production allocation [{label}]: {total:.0} production over {maps} maps ==="
        );
        let mut rows: Vec<(&&str, &f64)> = spent.iter().collect();
        rows.sort_by(|a, b| b.1.partial_cmp(a.1).unwrap());
        for (kind, amount) in rows {
            println!(
                "  {kind:<14} {amount:>10.0}  ({:>5.1}%)",
                amount / total.max(1.0) * 100.0
            );
        }
        println!(
            "  cities held {:.2} against a target of {:.2}",
            end_cities / maps as f64,
            target / maps as f64
        );
        println!(
                "  the missing cities would have cost {:.0} production — {:.1}% of everything the empire made",
                shortfall_cost / maps as f64,
                shortfall_cost / total.max(1.0) * 100.0
            );
    }
    println!();
}

/// Fires-check for `city_target_floor`, at both map scales.
///
/// ⚠ The criterion is the **outcome** — cities at end — not a mechanism
/// bucket. `docs/EVAL.md` records the last expansion fires-check choosing
/// "the every-city-mid-build bucket must collapse", which the treatment
/// could never have moved, so it was unfalsifiable in the helpful
/// direction. If cities at end do not rise, nothing else here matters.
///
/// Run with `cargo test --release city_target_floor_fires -- --ignored --nocapture`.
#[test]
#[ignore = "census, not an assertion; run explicitly with --nocapture"]
fn city_target_floor_fires() {
    for (label, players, width, height) in [
        ("eval 4p 24x16", 4usize, 24i32, 16i32),
        ("large 6p 74x46", 6, 74, 46),
    ] {
        for floor in [3usize, 6] {
            let mut cities = 0.0f64;
            let mut target = 0.0f64;
            let mut score = 0.0f64;
            let maps = 6u64;
            for map in 0..maps {
                let mut game = Game::new_full(players, width, height, 480_000 + map, 200, 1, false);
                let mut ais: Vec<AdvancedAi> = (0..game.players.len())
                    .map(|_| {
                        let mut ai = AdvancedAi::new();
                        ai.city_target_floor = floor;
                        ai
                    })
                    .collect();
                game.set_fog_memory(false);
                while game.winner.is_none() && game.turn <= game.max_turns {
                    let pid = game.current;
                    ais[pid].take_turn(&mut game, pid);
                    if game.winner.is_none() && game.current == pid {
                        let _ = game.apply(pid, &crate::game::Action::EndTurn);
                    }
                }
                cities += game.player_city_ids(0).len() as f64;
                score += game.score(0) as f64;
                target += ais[0]
                    .plan
                    .as_ref()
                    .map(|p| p.desired_cities as f64)
                    .unwrap_or(0.0);
            }
            println!(
                "  [{label}] floor={floor}  cities {:.2} / target {:.2}   score {:.0}",
                cities / maps as f64,
                target / maps as f64,
                score / maps as f64
            );
        }
    }
    println!();
}

