/// Our capital at (10, 10) and a neighbour's at (22, 10), twelve tiles
/// east; the neighbour is met when `met` says so. Two Warriors of ours,
/// one of theirs, and nothing else on the board.
fn a_neighbour_twelve_tiles_east(met: bool) -> Game {
    let mut game = Game::new_full(3, 40, 20, 7_802, 250, 0, false);
    game.current = 0;
    for uid in game.units.keys().copied().collect::<Vec<_>>() {
        game.remove_unit(uid);
    }
    game.found_city_for(0, (10, 10), None);
    game.found_city_for(1, (22, 10), None);
    if met {
        game.record_contact(0, 1);
    }
    game.spawn_unit("warrior", 0, (10, 11));
    game.spawn_unit("warrior", 0, (11, 10));
    game.spawn_unit("warrior", 1, (22, 11));
    assert_eq!(game.wdist((10, 10), (22, 10)), 12, "fixture: the gap");
    game
}

/// The frontier holds: a city within eight of a met neighbour's prices its
/// first Walls higher and, with nothing hostile in sight, still wants a
/// garrison — the capital twelve tiles out does neither.
#[test]
fn a_frontier_city_is_walled_and_garrisoned_under_contested_land_first() {
    use super::contested_land::CONTESTED_LAND_FRONTIER_WALLS;
    let mut game = a_neighbour_twelve_tiles_east(true);
    game.found_city_for(0, (16, 10), None);
    let shipped = AdvancedAi::new();
    let mut ai = AdvancedAi::new();
    ai.enable_contested_land_first();

    assert_eq!(
        shipped.contested_land_walls_value(&game, 0, (16, 10), "walls"),
        0.0
    );
    assert_eq!(
        ai.contested_land_walls_value(&game, 0, (16, 10), "walls"),
        CONTESTED_LAND_FRONTIER_WALLS
    );
    assert_eq!(
        ai.contested_land_walls_value(&game, 0, (16, 10), "medieval_walls"),
        0.0,
        "the first Walls only"
    );
    assert_eq!(
        ai.contested_land_walls_value(&game, 0, (10, 10), "walls"),
        0.0,
        "the capital, twelve tiles out, is no frontier"
    );

    assert!(
        shipped.base.garrison_assignments(&game, 0, &[]).is_empty(),
        "the shipped garrison answers live pressure only"
    );
    let assigned = ai.base.garrison_assignments(&game, 0, &[]);
    assert_eq!(
        assigned.iter().map(|(_, city)| *city).collect::<Vec<_>>(),
        vec![(16, 10)],
        "one Warrior walks to the frontier city; the other stays free"
    );
    assert!(
        ai.base
            .garrison_assignments(&game, 0, &[])
            .iter()
            .all(|(_, city)| *city != (10, 10)),
        "the capital wants none"
    );
}

// ---- gold_and_cards: which currency pays for an item ---------------------

/// `native-emergency-purchase`: the frozen controller leaves a bleeding city
/// to the reserve arithmetic; the gene buys the defender the live doctrine
/// would, with the treasury below the ordinary reserve.
#[test]
fn the_native_emergency_purchase_spends_through_the_reserve() {
    let (mut game, city, home) = empire_with_a_capital(71_121);
    let state = game.cities.get_mut(&city).expect("capital exists");
    state.buildings.push(crate::name!("walls"));
    state.wall_hp = 100;
    state.hp = 29;
    game.turn = 30;
    game.cities.get_mut(&city).unwrap().last_attacked = 29;
    let barbarians = game
        .players
        .iter()
        .position(|player| player.is_barbarian)
        .expect("a barbarian seat");
    let raiders: Vec<Pos> =
        game.wdisk(home, 2)
            .into_iter()
            .filter(|position| {
                *position != home
                    && game.map.get(*position).is_some_and(|tile| {
                        game.rules.is_passable(tile) && !game.rules.is_water(tile)
                    })
                    && game.unit_ids_at(*position).is_empty()
            })
            .take(2)
            .collect();
    assert_eq!(
        raiders.len(),
        2,
        "fixture needs two raiders beside the capital"
    );
    for position in raiders {
        game.spawn_test_unit("warrior", barbarians, position);
    }
    let plan = StrategicPlan {
        strategy: GrandStrategy::Science,
        target_player: None,
        target_city: None,
        threatened_city: Some(city),
        desired_cities: 1,
        assessed_turn: game.turn,
        rush: false,
    };
    game.players[0].gold = 1_000.0;
    let mut native = AdvancedAi::new();
    native.enable_native_emergency_purchase();
    let Some(Item::Unit { unit: wanted }) = native.native_emergency_item(&game, 0, city) else {
        panic!("walls already stand, so the emergency must ask for a defender");
    };
    let action = native
        .legal_purchase_actions(&game, 0)
        .into_iter()
        .find(|action| match action {
            Action::Buy {
                city: where_,
                unit,
                formation,
                currency,
            } => *where_ == city && unit == &wanted && *formation == 0 && currency == "gold",
            _ => false,
        })
        .expect("the local defender has a Gold purchase action");
    let mut quote = game.clone();
    let before_quote = quote.players[0].gold;
    quote.apply(0, &action).expect("the defender quote applies");
    let cost = before_quote - quote.players[0].gold;
    assert!(
        cost > 0.0 && cost < 300.0,
        "fixture must sit below the reserve: {cost}"
    );
    game.players[0].gold = cost;

    let stock = AdvancedAi::new();
    let mut stock_game = game.clone();
    assert!(
        !stock.emergency_city_defense_purchase(&mut stock_game, 0, &plan),
        "off, the native signal is not consulted"
    );
    assert!(
        !stock.advanced_gold_spending(&mut stock_game, 0, &plan),
        "off, the reserve holds the treasury"
    );
    assert_eq!(stock_game.players[0].gold, cost);

    assert!(native.advanced_gold_spending(&mut game, 0, &plan));
    let bought = game.player_unit_ids(0);
    assert_eq!(bought.len(), 1, "one defender, bought through the reserve");
    assert_eq!(game.units[&bought[0]].kind, wanted);
    assert!(
        game.players[0].gold < 1.0,
        "the whole treasury went to the defence"
    );
}

/// `government-reach-pays-the-switch`: Communism's eight slots stay against
/// Corporate Libertarianism's ten, and a seat stuck on four still reaches. See
/// `advanced/government_reach.rs`.
#[test]
fn a_two_slot_gain_does_not_pay_for_the_switch() {
    let (mut game, _capital, _home) = empire_with_a_capital(71_503);
    for civic in [
        "code_of_laws",
        "political_philosophy",
        "class_struggle",
        "corporate_libertarianism",
    ] {
        game.players[0].civics.insert(Name::new(civic));
    }
    game.players[0].government = Some("communism".to_string());

    let seat = || {
        let mut ai = AdvancedAi::new();
        ai.victory_target = Some(VictoryTarget::Science);
        ai.enable_government_capacity_fallback();
        ai
    };
    let mut off = game.clone();
    seat().strategic_government(&mut off, 0, GrandStrategy::Science);
    assert_eq!(
        off.players[0].government.as_deref(),
        Some("corporate_libertarianism"),
        "the shipped fallback takes the two slots: the live t187 switch"
    );

    let mut armed = seat();
    armed.enable_government_reach_pays_the_switch();
    let mut on = game.clone();
    armed.strategic_government(&mut on, 0, GrandStrategy::Science);
    assert_eq!(
        on.players[0].government.as_deref(),
        Some("communism"),
        "the seat keeps the listed pick it holds"
    );
}

/// ★★★★ SETTLERS WITH NOWHERE TO GO. The city target is a land census; the
/// map is not obliged to seat it. Live King seat `civvis-20260826T112920Z`
/// wanted sixteen cities, founded twelve and burned 168 idle settler-turns.
/// See `AdvancedAi::city_target_meets_the_map`.
#[test]
fn the_city_target_is_capped_by_the_sites_the_map_can_seat() {
    let (game, _capital, home) = empire_with_a_capital(71_507);
    let ai = AdvancedAi::new();

    let room = ai.map_settlement_room(&game, 0, &[home], 16);
    assert!(
        room <= 16,
        "the walk stops once it has counted what was asked for"
    );

    // Every counted site stands at least the exclusion distance from the
    // others, so two plots three tiles apart are one seat, not two.
    let plenty = ai.map_settlement_room(&game, 0, &[home], 4);
    assert!(
        plenty <= 4,
        "the cap is honoured for a smaller ask as well: {plenty}"
    );
    assert!(
        room >= plenty,
        "asking for more never seats fewer: {room} against {plenty}"
    );

    // No origins is no room, and no want is no work.
    assert_eq!(ai.map_settlement_room(&game, 0, &[], 16), 0);
    assert_eq!(ai.map_settlement_room(&game, 0, &[home], 0), 0);
}

/// ★★★★ THE ONLY COUNTER IS RANKED LAST. `governor_priority` reads the grand
/// strategy and nothing else, so an empire with no religion of its own ranks
/// Moksha -- whose `citadel_of_god` is the only thing in the ruleset that
/// stops a foreign faith taking a city it holds -- sixth of seven under
/// Expansion and seventh under Diplomacy. Live King seat
/// `civvis-20260826T112920Z` spent fifteen governor titles on Amani, Victor,
/// Pingala and Reyna while eleven of its twelve cities converted. See
/// `AdvancedAi::moksha_defends_the_faithless`.
#[test]
fn a_religionless_empire_under_conversion_raises_moksha_first() {
    let (mut game, capital, _home) = empire_with_a_capital(71_701);
    // A rival founds a faith and presses it into our capital: this is exactly
    // what `home_conversion_threat` reads.
    game.players[1].religion = Some("faith_theirs".to_string());
    {
        let city = game.cities.get_mut(&capital).unwrap();
        city.pressure.insert("faith_theirs".to_string(), 400.0);
        city.atheist_pressure = 0.0;
    }
    assert!(
        game.players[0].religion.is_none(),
        "the fixture's empire founded nothing"
    );

    let mut ai = AdvancedAi::new();
    ai.enable_moksha_defends_the_faithless();
    assert!(
        ai.home_conversion_threat(&game, 0).is_some(),
        "the fixture must present a live conversion threat"
    );

    // Shipped: Moksha is last under Diplomacy and sixth under Expansion.
    let shipped_diplomacy = AdvancedAi::governor_priority(GrandStrategy::Diplomacy);
    assert_eq!(
        shipped_diplomacy.last(),
        Some(&"moksha"),
        "the shipped Diplomacy list ranks the only counter dead last"
    );

    for strategy in [
        GrandStrategy::Diplomacy,
        GrandStrategy::Expansion,
        GrandStrategy::Recovery,
        GrandStrategy::Science,
    ] {
        let order = ai.governor_priority_for(&game, 0, strategy);
        assert_eq!(
            order.first(),
            Some(&"moksha"),
            "a religionless empire under conversion raises Moksha first on {strategy:?}"
        );
        // Nothing is dropped or duplicated — it is a reordering.
        let shipped = AdvancedAi::governor_priority(strategy);
        assert_eq!(order.len(), shipped.len(), "no governor is lost");
        for name in shipped {
            assert!(order.contains(name), "{name} survives the reorder");
        }
    }

    // An empire with a faith of its own has Missionaries, Apostles and
    // Inquisitors it can actually buy; it keeps the shipped order.
    game.players[0].religion = Some("faith_ours".to_string());
    assert_eq!(
        ai.governor_priority_for(&game, 0, GrandStrategy::Diplomacy),
        shipped_diplomacy.to_vec(),
        "an empire that founded a religion is untouched"
    );
    game.players[0].religion = None;

    // No threat, no reorder: the gene reads the board, not a preference.
    {
        let city = game.cities.get_mut(&capital).unwrap();
        city.pressure.clear();
        city.atheist_pressure = 200.0;
    }
    assert!(ai.home_conversion_threat(&game, 0).is_none());
    assert_eq!(
        ai.governor_priority_for(&game, 0, GrandStrategy::Diplomacy),
        shipped_diplomacy.to_vec(),
        "with nobody converting us the shipped order stands"
    );

    // Off, it is an exact no-op even with the threat live.
    {
        let city = game.cities.get_mut(&capital).unwrap();
        city.pressure.insert("faith_theirs".to_string(), 400.0);
        city.atheist_pressure = 0.0;
    }
    ai.disable_moksha_defends_the_faithless();
    assert_eq!(
        ai.governor_priority_for(&game, 0, GrandStrategy::Diplomacy),
        shipped_diplomacy.to_vec(),
        "off, the shipped order is returned unchanged"
    );
}

/// The host's projection for a (origin, destination) pair — exported while a
/// route slot is open — is what the trader chooser prices for that pair; the
/// model's own route yields stand everywhere else, and the premiums on top
/// are the board's own either way.
#[test]
fn a_host_priced_route_option_is_what_the_trader_chooser_prices() {
    let mut game = Game::new_full(2, 18, 10, 79_002, 200, 0, false);
    for pid in 0..2 {
        let settler = game
            .player_unit_ids(pid)
            .into_iter()
            .find(|unit| game.units[unit].kind == "settler")
            .unwrap();
        game.current = pid;
        game.apply(pid, &Action::FoundCity { unit: settler })
            .unwrap();
    }
    game.current = 0;
    let origin = game.player_city_ids(0)[0];
    let destination = game.player_city_ids(1)[0];
    let ai = AdvancedAi::new();
    let strategy = GrandStrategy::Conquest;
    let model = ai.trade_route_destination_value_from(
        &game,
        0,
        Some(origin),
        &game.cities[&destination],
        strategy,
    );
    assert_eq!(
        model,
        ai.trade_route_destination_value(&game, 0, &game.cities[&destination], strategy),
        "without a host projection the origin changes nothing"
    );
    let host = crate::rules::Yields {
        gold: 12.0,
        science: 6.0,
        ..Default::default()
    };
    std::sync::Arc::make_mut(&mut game.observed_route_options).insert((origin, destination), host);
    let priced = ai.trade_route_destination_value_from(
        &game,
        0,
        Some(origin),
        &game.cities[&destination],
        strategy,
    );
    let expected = model - ai.yield_value(game.trade_route_yields(0, destination), strategy)
        + ai.yield_value(host, strategy);
    assert!(
        (priced - expected).abs() < 1e-9,
        "the host's yields replace the model's for the pair: {priced} vs {expected}"
    );
    assert_eq!(
        ai.trade_route_destination_value_from(
            &game,
            0,
            Some(origin + 1_000),
            &game.cities[&destination],
            strategy,
        ),
        model,
        "another origin is not priced by this pair's projection"
    );
}

mod forcing_reply_lazy_key_tests {
    use super::*;

    /// Reimplements the old, eager form of the forcing-reply tie-break:
    /// format every candidate's Debug label up front, then sort on
    /// score descending and label ascending.
    fn eager_order(candidates: &[(f64, Action, Option<Action>)]) -> Vec<String> {
        let mut eager: Vec<(f64, String)> = candidates
            .iter()
            .map(|(score, reply, followup)| {
                (*score, AdvancedAi::forcing_reply_label(reply, followup))
            })
            .collect();
        eager.sort_by(|left, right| {
            right
                .0
                .total_cmp(&left.0)
                .then_with(|| left.1.cmp(&right.1))
        });
        eager.into_iter().map(|(_, label)| label).collect()
    }

    /// The new, lazy form actually used by forcing_reply_line: sort directly
    /// on raw candidates, formatting a label only for a score tie.
    fn lazy_order(candidates: &[(f64, Action, Option<Action>)]) -> Vec<String> {
        let mut lazy = candidates.to_vec();
        lazy.sort_by(|left, right| {
            right.0.total_cmp(&left.0).then_with(|| {
                AdvancedAi::forcing_reply_label(&left.1, &left.2)
                    .cmp(&AdvancedAi::forcing_reply_label(&right.1, &right.2))
            })
        });
        lazy.into_iter()
            .map(|(_, reply, followup)| AdvancedAi::forcing_reply_label(&reply, &followup))
            .collect()
    }

    #[test]
    fn lazy_tie_break_matches_eager_key_ordering() {
        let candidates: Vec<(f64, Action, Option<Action>)> = vec![
            (
                8.0,
                Action::Ranged {
                    unit: 9,
                    target: (1, 1),
                },
                None,
            ),
            (
                5.0,
                Action::Attack {
                    unit: 5,
                    target: (2, 3),
                },
                None,
            ),
            (
                5.0,
                Action::Attack {
                    unit: 1,
                    target: (0, 0),
                },
                None,
            ),
            (
                5.0,
                Action::Move {
                    unit: 2,
                    to: (4, 4),
                },
                Some(Action::Attack {
                    unit: 2,
                    target: (5, 5),
                }),
            ),
            (
                1.0,
                Action::Attack {
                    unit: 3,
                    target: (9, 9),
                },
                None,
            ),
        ];

        let lazy = lazy_order(&candidates);
        let eager = eager_order(&candidates);
        assert_eq!(
            lazy, eager,
            "lazily-formatted tie-break keys must sort identically to eagerly-formatted ones"
        );
        assert_eq!(
            lazy,
            vec![
                "Ranged { unit: 9, target: (1, 1) }".to_string(),
                "Attack { unit: 1, target: (0, 0) }".to_string(),
                "Attack { unit: 5, target: (2, 3) }".to_string(),
                "Move { unit: 2, to: (4, 4) } -> Attack { unit: 2, target: (5, 5) }".to_string(),
                "Attack { unit: 3, target: (9, 9) }".to_string(),
            ]
        );
    }
}

// ═══ What twenty-four live captures taught (2026-08-28) ═══
//
// Two host-only treatments, `live-barbarian-scouts-capture` and
// `live-settler-capture-lessons`; see `advanced/civilian_safety.rs`. Each
// fixture below is one of the day's mechanisms, on `barbarian_field`'s flat
// board.

/// Run civvis-20260828T122324Z: a barbarian scout two tiles from an unguarded
/// settler took it, and three more after it. Native boards' recon cannot
/// capture and stays out of the reach; the live seat's counts.
#[test]
fn a_barbarian_scout_is_a_capture_threat_on_the_live_seat() {
    let (mut game, _city, home) = barbarian_field(71_301);
    let start = game
        .wdisk(home, 2)
        .into_iter()
        .find(|pos| game.wdist(*pos, home) == 2 && open_land(&game, *pos))
        .expect("open ground two tiles from home");
    let scout_at = game
        .wdisk(start, 2)
        .into_iter()
        .find(|pos| {
            game.wdist(*pos, start) == 2 && game.wdist(*pos, home) == 2 && open_land(&game, *pos)
        })
        .expect("a post two tiles from the settler, in the capital's sight");
    let _settler = game.spawn_test_unit("settler", 0, start);
    let scout = game.spawn_test_unit("scout", 1, scout_at);

    let mut native = AdvancedAi::new();
    native.enable_civilian_out_of_reach();
    assert!(
        !native.live_barbarian_scouts_capture,
        "off for every native board"
    );
    assert!(
        native.barbarian_reach(&game, 0, start, 10).is_empty(),
        "a native barbarian scout is not a raider"
    );

    let mut live = AdvancedAi::new();
    live.enable_live_bridge();
    assert!(
        live.live_barbarian_scouts_capture && live.live_settler_capture_lessons,
        "the live universe carries both treatments"
    );
    let reach = live.barbarian_reach(&game, 0, start, 10);
    assert!(
        reach.covers(&game, start),
        "on the live seat the scout's three moves cover the settler's tile"
    );
    // The host safety floor is deliberately geometric because a path query
    // can refuse a civilian-occupied destination.  Keep the native live
    // answer conservative on that same floor even when the exact movement
    // flood is narrower around a blocker or zone of control.
    let exact = game.threat_reach(scout);
    let geometric = game.wdisk(scout_at, 2).into_iter().find(|pos| {
        game.map
            .get(*pos)
            .is_some_and(|tile| !game.rules.is_water(tile))
            && !exact.contains(pos)
    });
    let pos = geometric
        .expect("the fixture must leave a geometric scout tile outside the exact movement flood");
    assert!(
        live.barbarian_reach(&game, 0, pos, 10).covers(&game, pos),
        "the live scout floor covers a geometric land tile the exact flood omitted"
    );
    let mut withheld = AdvancedAi::new();
    withheld.enable_live_bridge();
    withheld.disable_live_barbarian_scouts_capture();
    assert!(
        withheld.barbarian_reach(&game, 0, start, 10).is_empty(),
        "the withholding twin restores the exemption"
    );
}

/// The live host falls back to a barbarian combat unit's static `BaseMoves`
/// radius when a civilian destination cannot be answered by its path query.
/// Keep the native live reach at least that conservative, or a settler can
/// enter a tile the host will refuse as an escape and be captured in place.
#[test]
fn a_live_barbarian_combat_reach_matches_the_host_geometric_floor() {
    let (mut game, _city, home) = barbarian_field(71_307);
    let start = game
        .wdisk(home, 2)
        .into_iter()
        .find(|pos| game.wdist(*pos, home) == 2 && open_land(&game, *pos))
        .expect("open ground two tiles from home");
    let raider_at = game
        .wdisk(start, 4)
        .into_iter()
        .find(|pos| {
            game.wdist(*pos, start) == 4 && game.wdist(*pos, home) <= 2 && open_land(&game, *pos)
        })
        .expect("open ground four tiles from the settler");
    let _settler = game.spawn_test_unit("settler", 0, start);
    let raider = game.spawn_test_unit("saka_horse_archer", 1, raider_at);

    let exact = game.threat_reach(raider);
    let geometric = game
        .wdisk(raider_at, 4)
        .into_iter()
        .find(|pos| {
            game.map
                .get(*pos)
                .is_some_and(|tile| !game.rules.is_water(tile))
                && !exact.contains(pos)
        })
        .expect("the fixture must leave a geometric four-hex tile outside the exact flood");

    let mut native = AdvancedAi::new();
    native.enable_civilian_out_of_reach();
    assert!(
        !native
            .barbarian_reach(&game, 0, geometric, 10)
            .covers(&game, geometric),
        "native/evaluator reach remains terrain-constrained"
    );

    let mut live = AdvancedAi::new();
    live.enable_live_bridge();
    assert!(
        live.barbarian_reach(&game, 0, geometric, 10)
            .covers(&game, geometric),
        "the live reach includes the host's static four-hex land floor"
    );
}

/// Run civvis-20260829T022749Z, t78: boxed between a skirmisher and a warrior
/// with the sea behind it, the settler "held inside a barbarian's reach"
/// beside the skirmisher — two tiles from a full-health archer it could have
/// stood with. Under the lessons a tile one of our units holds beats every
/// bare tile, and the unit becomes the settler's guard.
#[test]
fn a_settler_with_no_safe_tile_flees_onto_a_friendly_stack_under_the_lessons() {
    let (mut game, _city, home) = barbarian_field(71_302);
    let start = game
        .wdisk(home, 2)
        .into_iter()
        .find(|pos| game.wdist(*pos, home) == 2 && open_land(&game, *pos))
        .expect("open ground two tiles from home");
    let raider_at = game
        .wdisk(start, 1)
        .into_iter()
        .find(|pos| {
            game.wdist(*pos, start) == 1 && game.wdist(*pos, home) == 2 && open_land(&game, *pos)
        })
        .expect("a raider beside the settler, in the capital's sight");
    let cover_at = game
        .wdisk(start, 2)
        .into_iter()
        .find(|pos| {
            game.wdist(*pos, start) == 2
                && game.wdist(*pos, raider_at) == 3
                && game.wdist(*pos, home) <= 3
                && open_land(&game, *pos)
        })
        .expect("ground two tiles from the settler on the far side of the raider");
    let settler = game.spawn_test_unit("settler", 0, start);
    let _horseman = game.spawn_test_unit("horseman", 1, raider_at);
    let guard = game.spawn_test_unit("man_at_arms", 0, cover_at);
    // The guard has already moved this turn: it cannot be summoned onto
    // the settler's tile, so the settler must go to it.
    game.units.get_mut(&guard).expect("spawned").moves_left = 0.0;

    let mut live = AdvancedAi::new();
    live.enable_live_bridge();
    let reach = live.barbarian_reach(&game, 0, start, 10);
    assert!(
        reach.covers(&game, start),
        "the settler stands inside the horseman's reach"
    );
    assert!(
        reach.covers(&game, cover_at),
        "the fixture leaves no safe tile: four moves on flat ground cover everything \
         the settler can reach"
    );
    assert_eq!(
        live.civilian_flee_step(&mut game, 0, settler),
        Some(true),
        "the flee decides the settler's turn"
    );
    assert_eq!(
        game.units[&settler].pos, cover_at,
        "it stands with the guard rather than on the least exposed bare tile"
    );
    assert_eq!(
        live.settler_guards.get(&settler),
        Some(&guard),
        "and binds the guard, so its own turn keeps it there"
    );
}

/// Run civvis-20260829T000643Z fed six settlers to the two plots beside one
/// nest over ninety turns, each retiring the site for itself alone. Under the
/// lessons a settler that leaves the board without a city near where it stood
/// retires every site within three tiles for every settler; a settler that
/// founded is not a loss; the scar expires; and it survives the live bridge's
/// unit-id remap because it is ground memory, not unit memory.
#[test]
fn a_lost_settler_retires_the_ground_around_it_for_every_settler() {
    let (mut game, _city, home) = barbarian_field(71_303);
    let far = game
        .wdisk(home, 6)
        .into_iter()
        .find(|pos| game.wdist(*pos, home) == 6 && open_land(&game, *pos))
        .expect("open ground six tiles from home");
    let taken = game.spawn_test_unit("settler", 0, far);
    let mut live = AdvancedAi::new();
    live.enable_live_bridge();
    // What `advanced_settler_step_inner` records each time it steps the unit.
    live.settler_last_seen.insert(taken, far);

    // The rebuilt board no longer carries the settler: nothing maps to it.
    game.remove_unit(taken);
    live.remap_unit_memory(&BTreeMap::new());
    assert_eq!(
        live.settler_vanished,
        vec![far],
        "its last position waits for the turn"
    );
    assert!(live.settler_last_seen.is_empty());

    let taken_turn = game.turn;
    live.resolve_vanished_settlers(&game, 0);
    let fresh = game.spawn_test_unit("settler", 0, home);
    assert!(
        live.settler_site_is_dead(fresh, far),
        "the ground that took it is dead"
    );
    let inside = game
        .wdisk(far, 3)
        .into_iter()
        .find(|pos| game.wdist(*pos, far) == 3)
        .expect("a tile three out");
    let beyond = game
        .wdisk(far, 4)
        .into_iter()
        .find(|pos| game.wdist(*pos, far) == 4)
        .expect("a tile four out");
    assert!(
        live.settler_site_is_dead(fresh, inside),
        "and three tiles around it"
    );
    assert!(!live.settler_site_is_dead(fresh, beyond), "but not four");
    assert!(live.settler_vanished.is_empty(), "resolved once");

    // The scar outlives a remap and expires with the avoid window.
    live.remap_unit_memory(&BTreeMap::from([(fresh, fresh + 1000)]));
    assert!(live.settler_site_is_dead(fresh + 1000, far));
    game.turn = taken_turn + game.standard_duration(SETTLER_DEAD_SITE_AVOID_TURNS) + 1;
    live.resolve_vanished_settlers(&game, 0);
    assert!(
        !live.settler_site_is_dead(fresh + 1000, far),
        "thirty standard turns later it is ground again"
    );

    // A settler that founded where it stood is not a loss.
    let founder = game.spawn_test_unit("settler", 0, far);
    live.settler_last_seen.insert(founder, far);
    game.apply(0, &Action::FoundCity { unit: founder })
        .expect("the site is legal");
    live.resolve_vanished_settlers(&game, 0);
    assert!(
        !live.settler_capture_scars.contains_key(&far),
        "a founding leaves a city where the settler stood, not a scar"
    );

    // Off, nothing is recorded and nothing is retired.
    let mut native = AdvancedAi::new();
    native.enable_civilian_out_of_reach();
    native.settler_last_seen.insert(taken, far);
    native.resolve_vanished_settlers(&game, 0);
    assert!(native.settler_capture_scars.is_empty());
}

/// Run civvis-20260829T022749Z bound a 15-strength archer over a warrior and
/// lost it, then the settler, to a skirmisher. Every candidate reaches the
/// settler this turn; under the lessons the strongest is the guard.
#[test]
fn the_strongest_guard_that_can_reach_the_settler_is_summoned_under_the_lessons() {
    let (mut game, _city, home) = barbarian_field(71_304);
    let start = game
        .wdisk(home, 2)
        .into_iter()
        .find(|pos| game.wdist(*pos, home) == 2 && open_land(&game, *pos))
        .expect("open ground two tiles from home");
    let near = game
        .wdisk(start, 1)
        .into_iter()
        .find(|pos| game.wdist(*pos, start) == 1 && open_land(&game, *pos))
        .expect("a tile beside the settler");
    let farther = game
        .wdisk(start, 2)
        .into_iter()
        .find(|pos| {
            game.wdist(*pos, start) == 2 && game.wdist(*pos, near) == 3 && open_land(&game, *pos)
        })
        .expect("a tile two from the settler");
    let settler = game.spawn_test_unit("settler", 0, start);
    let archer = game.spawn_test_unit("archer", 0, near);
    let warrior = game.spawn_test_unit("warrior", 0, farther);
    assert!(
        game.unit_strength(&game.units[&warrior], false)
            > game.unit_strength(&game.units[&archer], false),
        "the fixture's warrior is the stronger body"
    );

    let pristine = game.clone();
    let mut native = AdvancedAi::new();
    native.enable_civilian_out_of_reach();
    assert!(native.summon_guard_to(&mut game, 0, settler, start));
    assert_eq!(
        native.settler_guards.get(&settler),
        Some(&archer),
        "native: the nearest"
    );

    let mut fresh = pristine;
    let mut live = AdvancedAi::new();
    live.enable_live_bridge();
    assert!(live.summon_guard_to(&mut fresh, 0, settler, start));
    assert_eq!(
        live.settler_guards.get(&settler),
        Some(&warrior),
        "live: the strongest"
    );
}

/// Run civvis-20260829T022749Z, t103: "The settler's guard stands down — no
/// visible hostile within 8 tiles" on the tile where a settler had been taken
/// at t78; the next settler was taken at t104. Under the lessons the ground
/// that took a settler is not quiet because nothing is visible on it today.
#[test]
fn a_guard_is_not_released_on_ground_that_took_a_settler() {
    let (mut game, _city, home) = barbarian_field(71_305);
    let start = game
        .wdisk(home, 2)
        .into_iter()
        .find(|pos| game.wdist(*pos, home) == 2 && open_land(&game, *pos))
        .expect("open ground two tiles from home");
    let settler = game.spawn_test_unit("settler", 0, start);
    let warrior = game.spawn_test_unit("warrior", 0, start);
    let mut live = AdvancedAi::new();
    live.enable_live_bridge();
    live.settler_guards.insert(settler, warrior);
    let reach = live.barbarian_reach(&game, 0, start, 10);
    assert!(
        reach.is_empty(),
        "nothing is visible: the old rule would release"
    );

    let until = game.turn + 100;
    for tile in game.wdisk(start, 3) {
        live.settler_capture_scars.insert(tile, until);
    }
    live.release_guard_if_quiet(&game, 0, settler, &reach);
    assert_eq!(
        live.settler_guards.get(&settler),
        Some(&warrior),
        "the guard stays on the ground that took a settler"
    );

    live.settler_capture_scars.clear();
    live.release_guard_if_quiet(&game, 0, settler, &reach);
    assert!(
        !live.settler_guards.contains_key(&settler),
        "quiet, unscarred ground releases it as before"
    );
}

/// Run civvis-20260829T022749Z, t103–t104: the next settler marched alone
/// toward the site that had cost the last one and was taken two tiles short.
/// Under the lessons the ground within three tiles of a capture is entered
/// only with a guard stacked; alone, the settler waits for one.
#[test]
fn a_settler_does_not_cross_scarred_ground_alone() {
    let (mut game, _city, home) = barbarian_field(71_306);
    let start = game
        .wdisk(home, 2)
        .into_iter()
        .find(|pos| game.wdist(*pos, home) == 2 && open_land(&game, *pos))
        .expect("open ground two tiles from home");
    let target = game
        .wdisk(start, 3)
        .into_iter()
        .find(|pos| {
            game.wdist(*pos, start) == 3 && game.wdist(*pos, home) >= 4 && open_land(&game, *pos)
        })
        .expect("a site three tiles from the settler, away from home");
    let settler = game.spawn_test_unit("settler", 0, start);

    let mut native = AdvancedAi::new();
    native.enable_civilian_out_of_reach();
    let mut rehearsal = game.clone();
    assert!(
        native.settler_step_out_of_reach(&mut rehearsal, 0, settler, target),
        "off, the quiet march proceeds"
    );
    assert!(rehearsal.units[&settler].pos != start);

    let mut live = AdvancedAi::new();
    live.enable_live_bridge();
    let until = game.turn + 100;
    for tile in game.wdisk(target, 3) {
        live.settler_capture_scars.insert(tile, until);
    }
    assert!(
        !live.settler_step_out_of_reach(&mut game, 0, settler, target),
        "alone, it will not step onto scarred ground"
    );
    assert_eq!(game.units[&settler].pos, start, "it waits where it stands");

    // A guard that can reach it this turn is summoned. The summon turn is
    // spent standing together — run civvis-20260829T040648Z t43: the pair
    // that marched the turn the guard arrived lost the guard's follow on the
    // host, and the settler was taken.
    let beside = game
        .wdisk(start, 1)
        .into_iter()
        .find(|pos| {
            game.wdist(*pos, start) == 1 && game.wdist(*pos, target) >= 3 && open_land(&game, *pos)
        })
        .expect("a tile beside the settler, away from the site");
    let warrior = game.spawn_test_unit("warrior", 0, beside);
    assert!(
        !live.settler_step_out_of_reach(&mut game, 0, settler, target),
        "the summon turn is spent standing with the guard"
    );
    assert_eq!(game.units[&settler].pos, start, "the settler holds");
    assert_eq!(game.units[&warrior].pos, start, "the guard arrived");

    // Next turn the pair walks in together.
    game.turn += 1;
    game.units.get_mut(&settler).unwrap().moves_left = 2.0;
    game.units.get_mut(&warrior).unwrap().moves_left = 2.0;
    assert!(
        live.settler_step_out_of_reach(&mut game, 0, settler, target),
        "with a guard it marches"
    );
    let now = game.units[&settler].pos;
    assert!(now != start, "the settler stepped");
    assert_eq!(
        live.settler_guards.get(&settler),
        Some(&warrior),
        "bound on the way in"
    );
    assert_eq!(
        game.units[&warrior].pos, now,
        "and the guard stands with it"
    );
}

/// Run civvis-20260829T040648Z, t43: the brain called an archer onto the
/// settler's tile and marched the settler on in the same turn, trusting the
/// guard to follow; the host gave the guard no second move, the settler ended
/// the turn alone in reach and was taken. Under the lessons the turn a guard
/// is called is spent standing with it — the same summon that fires when the
/// route ahead is a raider's reach or the ground a capture scarred — and the
/// memory of the summons follows the unit through the live bridge's id remap.
#[test]
fn a_settler_waits_the_turn_its_guard_is_called() {
    let (mut game, _city, home) = barbarian_field(71_306);
    let start = game
        .wdisk(home, 2)
        .into_iter()
        .find(|pos| game.wdist(*pos, home) == 2 && open_land(&game, *pos))
        .expect("open ground two tiles from home");
    let target = game
        .wdisk(start, 3)
        .into_iter()
        .find(|pos| {
            game.wdist(*pos, start) == 3 && game.wdist(*pos, home) >= 4 && open_land(&game, *pos)
        })
        .expect("a site three tiles from the settler, away from home");
    let beside = game
        .wdisk(start, 1)
        .into_iter()
        .find(|pos| {
            game.wdist(*pos, start) == 1 && game.wdist(*pos, target) >= 3 && open_land(&game, *pos)
        })
        .expect("a tile beside the settler, away from the site");
    let settler = game.spawn_test_unit("settler", 0, start);
    let warrior = game.spawn_test_unit("warrior", 0, beside);

    let mut live = AdvancedAi::new();
    live.enable_live_bridge();
    let until = game.turn + 100;
    for tile in game.wdisk(target, 3) {
        live.settler_capture_scars.insert(tile, until);
    }
    assert!(
        !live.settler_step_out_of_reach(&mut game, 0, settler, target),
        "the turn the guard is called is spent standing with it"
    );
    assert_eq!(game.units[&settler].pos, start);
    assert_eq!(game.units[&warrior].pos, start, "the guard arrived");
    assert_eq!(
        live.settler_guards.get(&settler),
        Some(&warrior),
        "and is bound"
    );
    assert_eq!(live.summoned_guard_turn.get(&settler), Some(&game.turn));

    // A remap carries the memory with the unit; a fresh board drops it.
    live.remap_unit_memory(&BTreeMap::from([
        (settler, settler + 1000),
        (warrior, warrior + 1000),
    ]));
    assert_eq!(
        live.summoned_guard_turn.get(&(settler + 1000)),
        Some(&game.turn)
    );
    live.forget_unit_memory();
    assert!(live.summoned_guard_turn.is_empty());
}

/// `first-district-first`: a young capital's first specialty district
/// scores higher under the gene than off, and with an idle queue the gene
/// starts it. Off, the pricing is byte-identical to the legacy scorer.
#[test]
fn the_first_district_outranks_the_filler_under_the_gene() {
    let (mut game, city, _) = empire_with_a_capital(71_119);
    game.players[0].techs.extend([
        crate::name!("writing"),
        crate::name!("pottery"),
        crate::name!("mining"),
    ]);
    game.cities.get_mut(&city).expect("capital").pop = 3;
    assert!(
        game.cities[&city].districts.is_empty(),
        "fixture: the capital holds no district yet"
    );
    let owned: Vec<Pos> = game.cities[&city].owned_tiles.to_vec();
    let campus = owned
        .into_iter()
        .map(|pos| Item::District {
            district: crate::name!("campus"),
            pos,
        })
        .find(|item| game.can_produce(0, city, item))
        .expect("fixture: a legal Campus plot");
    let plan = StrategicPlan {
        strategy: GrandStrategy::Science,
        target_player: None,
        target_city: None,
        threatened_city: None,
        desired_cities: 1,
        assessed_turn: game.turn,
        rush: false,
    };
    let mut ai = AdvancedAi::new();
    assert!(!ai.first_district_first, "the gene ships off");
    assert!(!AdvancedAi::legacy().first_district_first);
    let counts = ai.counts(&game, 0);
    let off = ai.production_value(&game, 0, city, &campus, &plan, &counts);
    ai.enable_first_district_first();
    assert!(ai.first_district_first);
    let on = ai.production_value(&game, 0, city, &campus, &plan, &counts);
    assert!(
        on > off && on > 0.0,
        "the first Campus prices higher under the gene: off {off:.1}, on {on:.1}"
    );
    assert!(
        game.cities[&city].queue.is_empty(),
        "fixture: an idle queue"
    );
    ai.advanced_production(&mut game, 0, &plan, false);
    let started = game.cities[&city].queue.first().cloned();
    assert!(
        matches!(
            &started,
            Some(Item::District { district, .. }) if game.rules.districts[district].specialty
        ),
        "the idle capital starts a specialty district under the gene, not {started:?}"
    );
    ai.disable_first_district_first();
    assert!(!ai.first_district_first);
}

/// `walls-after-districts`: a frontier city under a barbarian alarm whose
/// garrison already closes the defender gap is answered with Walls by the
/// pre-emption; under the gene the wall waits until the city holds a
/// district, and the scorer picks instead. The unit answer is untouched.
#[test]
fn walls_wait_for_the_first_district_under_the_gene() {
    let (mut game, _safe, remote) = remote_barbarian_trade_board();
    game.players[0].techs.extend([crate::name!("masonry")]);
    let home = game.cities[&remote].pos;
    for _ in 0..4 {
        game.spawn_unit("warrior", 0, home);
    }
    let mut ai = AdvancedAi::new();
    assert!(!ai.walls_after_districts, "the gene ships off");
    assert!(!AdvancedAi::legacy().walls_after_districts);
    assert!(
        ai.base
            .barbarian_local_alarm_for_controller(&game, 0, remote),
        "fixture: the remote city is under a barbarian alarm"
    );
    assert_eq!(
        ai.base.barbarian_defense_gap(&game, 0, remote),
        0,
        "fixture: the garrison closes the defender gap"
    );
    let walls = Item::Building {
        building: crate::name!("walls"),
    };
    assert_eq!(
        ai.base.barbarian_defense_item(&game, 0, remote),
        Some(walls.clone()),
        "fixture: the pre-emption answers the alarm with Walls"
    );
    assert!(
        game.cities[&remote].districts.is_empty(),
        "fixture: no district yet"
    );
    game.cities.get_mut(&remote).expect("remote").queue.clear();
    let plan = StrategicPlan {
        strategy: GrandStrategy::Expansion,
        target_player: None,
        target_city: None,
        threatened_city: None,
        desired_cities: 2,
        assessed_turn: game.turn,
        rush: false,
    };
    let mut control = game.clone();
    ai.advanced_production(&mut control, 0, &plan, false);
    assert_eq!(
        control.cities[&remote].queue.first(),
        Some(&walls),
        "off, the alarm starts Walls ahead of the scorer"
    );
    ai.enable_walls_after_districts();
    assert!(ai.walls_after_districts);
    ai.advanced_production(&mut game, 0, &plan, false);
    let started = game.cities[&remote].queue.first().cloned();
    assert!(
        started.is_some() && started.as_ref() != Some(&walls),
        "under the gene the wall waits and the scorer picks: {started:?}"
    );
    ai.disable_walls_after_districts();
    assert!(!ai.walls_after_districts);
}

// ---------------------------------------------------------------------------
// Settler safety: what the live King seat's twenty-eight captures say.
//
// Eleven live King runs, 2026-08-29, twenty-eight real settler losses — one in
// three of every settler built. Classified: TEN walked into a hostile with
// none visible within three tiles on the previous turn's state, EIGHT were
// captured while parked waiting for a guard, six moved inside a visible
// hostile's reach unescorted, two were zone-of-control pinned, and TWO were
// taken by Free Cities units (player 62). Median settler age at loss: ten
// turns. Two opt-in genes answer the first, last and second groups.
// ---------------------------------------------------------------------------

/// `hostile-memory`: the capture envelope counts every at-war owner, and keeps
/// pricing a hostile the seat has actually seen for a few turns after it walks
/// back into the fog — from the tile it was last seen on, never from where it
/// really is.
#[test]
fn a_settler_prices_the_raider_it_saw_and_the_owner_that_is_not_a_barbarian() {
    assert!(
        GENES.iter().any(|gene| gene.opt_in()
            && gene.field == "hostile_memory"
            && gene.tag == "hostile-memory"),
        "the gene is registered as an opt-in"
    );
    let (mut game, _city, home) = barbarian_field(71_701);
    game.turn = 20;
    let start = game
        .wdisk(home, 2)
        .into_iter()
        .find(|pos| game.wdist(*pos, home) == 2 && open_land(&game, *pos))
        .expect("open ground two tiles from home");
    let settler = game.spawn_test_unit("settler", 0, start);
    // Where the seat SAW it: one tile off the settler, inside a Warrior's
    // one-turn reach of the settler's own tile.
    let seen_at = game
        .nbrs(start)
        .into_iter()
        .find(|pos| open_land(&game, *pos))
        .expect("open ground beside the settler");
    // Where it stands NOW: far enough that nothing of ours can see it, so
    // every arm agrees it is not a visible raider.
    let hidden_at = game
        .map
        .tiles
        .keys()
        .copied()
        .filter(|pos| {
            game.wdist(*pos, start) >= 12 && game.wdist(*pos, home) >= 12 && open_land(&game, *pos)
        })
        .min()
        .expect("open ground well outside the empire's sight");
    let raider = game.spawn_test_unit("warrior", 1, hidden_at);

    let mut shipped = AdvancedAi::new();
    shipped.enable_civilian_out_of_reach();
    assert!(
        !shipped
            .barbarian_reach(&game, 0, start, civilian_safety::REACH_SCAN_RADIUS)
            .covers(&game, start),
        "a raider nothing of ours can see is not in the shipped envelope"
    );

    let mut remembering = AdvancedAi::new();
    remembering.enable_civilian_out_of_reach();
    remembering.enable_hostile_memory();
    assert!(
        !remembering
            .barbarian_reach(&game, 0, start, civilian_safety::REACH_SCAN_RADIUS)
            .covers(&game, start),
        "and it is not in the widened one either until the seat has seen it: \
         the gene remembers sightings, it does not read the fog"
    );

    // The observation the seat makes before it has moved anything is where the
    // memory comes from. Put the raider in plain sight for that one call.
    let watched = game.spawn_test_unit("warrior", 1, seen_at);
    remembering.observe_turn_start_hostiles(&game, 0);
    assert_eq!(
        remembering.hostile_last_seen.get(&(watched as i64)),
        Some(&super::RememberedHostile {
            pos: seen_at,
            when: game.turn,
            owner: 1,
            kind: crate::name!("warrior"),
        }),
        "the turn-start observation records what the seat could see, and where"
    );
    game.remove_unit(watched);
    // The rest of this fixture uses a separate remembered identity to test
    // the projection window; do not let the observed unit we removed above
    // provide an additional recent threat.
    remembering.hostile_last_seen.remove(&(watched as i64));

    // Now the remembered fact, one turn old, standing in for the unit that
    // walked out of sight: the tile the settler is on is still priced.
    remembering.hostile_last_seen.insert(
        raider as i64,
        super::RememberedHostile {
            pos: seen_at,
            when: game.turn - 1,
            owner: 1,
            kind: crate::name!("warrior"),
        },
    );
    assert!(
        remembering
            .barbarian_reach(&game, 0, start, civilian_safety::REACH_SCAN_RADIUS)
            .covers(&game, start),
        "a raider seen beside the settler last turn still covers its tile"
    );
    assert!(
        !shipped
            .barbarian_reach(&game, 0, start, civilian_safety::REACH_SCAN_RADIUS)
            .covers(&game, start),
        "and with the gene off the same board reads exactly as it shipped"
    );

    // The window closes. A sighting older than `HOSTILE_MEMORY_TURNS` is a
    // rumour, not a threat: by then the settler has usually walked past it.
    remembering.hostile_last_seen.insert(
        raider as i64,
        super::RememberedHostile {
            pos: seen_at,
            when: game.turn - civilian_safety::HOSTILE_MEMORY_TURNS - 1,
            owner: 1,
            kind: crate::name!("warrior"),
        },
    );
    assert!(
        !remembering
            .barbarian_reach(&game, 0, start, civilian_safety::REACH_SCAN_RADIUS)
            .covers(&game, start),
        "a sighting older than the memory window is forgotten"
    );

    // The other half: an at-war owner that is not the Barbarian player at all.
    // `resolve_entered_units` has never asked who owns the unit that steps onto
    // a civilian, and two of the twenty-eight were Free Cities captures.
    game.players[1].is_barbarian = false;
    game.barb_pid = None;
    let neighbour = game.spawn_test_unit("warrior", 1, seen_at);
    assert!(
        shipped
            .barbarian_reach(&game, 0, start, civilian_safety::REACH_SCAN_RADIUS)
            .is_empty(),
        "the shipped envelope early-returns on `barb_pid` and models no other owner"
    );
    let widened = remembering.barbarian_reach(&game, 0, start, civilian_safety::REACH_SCAN_RADIUS);
    assert!(
        widened.covers(&game, start),
        "a visible at-war major beside the settler takes it exactly as a raider does"
    );
    assert_eq!(
        widened.nearest(&game, start),
        game.wdist(seen_at, start),
        "and it is measured from where that unit stands"
    );
    let _ = neighbour;
    let _ = settler;
}

/// The live mirror rebuilds its foreign roster from visible-only `hostiles[]`.
/// A barbarian revealed in one frame must therefore remain a capture threat
/// even when the next frame contains no hostile unit at all; otherwise the
/// Settler planner walks into the fogged unit's old reach.
#[test]
fn live_capture_lessons_remember_a_hostile_after_the_visible_export_drops_it() {
    let (mut game, _city, home) = barbarian_field(71_702);
    game.turn = 20;
    let start = game
        .wdisk(home, 2)
        .into_iter()
        .find(|pos| game.wdist(*pos, home) == 2 && open_land(&game, *pos))
        .expect("open ground two tiles from home");
    let seen_at = game
        .nbrs(start)
        .into_iter()
        .find(|pos| open_land(&game, *pos))
        .expect("open ground beside the Settler");
    let settler = game.spawn_test_unit("settler", 0, start);
    let raider = game.spawn_test_unit("warrior", 1, seen_at);
    let civ6_raider_id = 71_702_001;
    std::sync::Arc::make_mut(&mut game.host_unit_facts).insert(
        raider,
        crate::game::HostUnitFacts {
            civ6_id: Some(civ6_raider_id),
            ..Default::default()
        },
    );

    let mut live = AdvancedAi::new();
    live.enable_live_bridge();
    assert!(live.live_settler_capture_lessons);
    live.observe_turn_start_hostiles(&game, 0);
    assert!(
        live.hostile_last_seen.contains_key(&civ6_raider_id),
        "the live observation must use the stable Civ 6 id"
    );

    // This is the next fresh-board export: the hostile is in fog and is not
    // planted in `Game` at all. The remembered record still covers the
    // Settler's tile, while the exact current-frame path sees nothing.
    game.remove_unit(raider);
    game.turn += 1;
    let reach = live.barbarian_reach(&game, 0, start, civilian_safety::REACH_SCAN_RADIUS);
    assert!(reach.covers(&game, start));
    assert_eq!(game.player_unit_ids(0), vec![settler]);
}

/// `science-expansion-phase` remains an evaluable native hypothesis: it can
/// widen the Science land grab while a new city can still mature. The shared
/// production profiles deliberately keep that experiment inside the operator's
/// 10–15-city horizon, then the named Science contract returns to twelve.
#[test]
fn the_science_lane_widens_natively_but_live_verification_stays_bounded() {
    let mut game = Game::new_full(2, 74, 46, 11, 250, 0, false);
    game.game_speed = crate::setup::GameSpeed::Online;
    for pid in 0..2 {
        let settler = game
            .player_unit_ids(pid)
            .into_iter()
            .find(|unit| game.units[unit].kind == "settler")
            .expect("each major starts with a settler");
        let position = game.units[&settler].pos;
        game.found_city_for(pid, position, None);
        game.remove_unit(settler);
    }
    game.current = 0;
    let land = game
        .map
        .tiles
        .values()
        .filter(|tile| game.rules.is_passable(tile) && !game.rules.is_water(tile))
        .count();
    let sites = 2 + AdvancedAi::fog_land_estimate(&game, land) / LAND_GRAB_TILES_PER_CITY;
    let widened = sites.clamp(LAND_GRAB_CITY_FLOOR, SCIENCE_EXPANSION_CITY_CEILING);
    let shared = sites.clamp(LAND_GRAB_CITY_FLOOR, LAND_GRAB_CITY_CEILING);
    assert!(
        widened > shared,
        "the board must be roomy enough to tell the ceilings apart: {widened} vs {shared}"
    );
    let until = game.standard_duration(SCIENCE_EXPANSION_UNTIL_TURN);

    let mut native = AdvancedAi::new();
    native.enable_land_grab();
    native.enable_science_expansion_phase();
    native.victory_target = Some(VictoryTarget::Science);
    game.turn = until - 1;
    assert_eq!(
        native.assess(&game, 0).desired_cities,
        widened,
        "the native science phase can still price its wider hypothesis"
    );
    let native_contract = shared.clamp(1, SCIENCE_CITY_TARGET_CAP);
    game.turn = until;
    assert_eq!(
        native.assess(&game, 0).desired_cities,
        native_contract,
        "past the window the Science contract resumes"
    );

    let mut live = AdvancedAi::new();
    live.enable_live_bridge();
    live.enable_science_expansion_phase();
    // `rapid-city-expansion-2` is an independent deployment treatment whose
    // target precedes `land_grab`; withhold it to isolate this phase.
    live.disable_rapid_city_expansion_2();
    // The horizon is tested here; the map-cap test owns the practical-site
    // safety behavior separately.
    live.disable_city_target_meets_the_map();
    live.victory_target = Some(VictoryTarget::Science);
    game.turn = until - 1;
    assert_eq!(
        live.assess(&game, 0).desired_cities,
        widened.clamp(SHARED_CITY_TARGET_FLOOR, SHARED_CITY_TARGET_CEILING,),
        "a live Science phase stays inside the shared horizon"
    );
    game.turn = until;
    let live_contract = shared.clamp(1, SHARED_SCIENCE_CITY_TARGET);
    assert_eq!(
        live.assess(&game, 0).desired_cities,
        live_contract,
        "the late live Science contract still targets twelve cities"
    );

    game.turn = until - 1;
    live.victory_target = Some(VictoryTarget::Diplomacy);
    assert_eq!(
        live.assess(&game, 0).desired_cities,
        shared.clamp(SHARED_CITY_TARGET_FLOOR, SHARED_CITY_TARGET_CEILING,),
        "every live lane stays inside the same horizon"
    );

    let mut off = AdvancedAi::new();
    off.enable_land_grab();
    off.victory_target = Some(VictoryTarget::Science);
    assert_eq!(
        off.assess(&game, 0).desired_cities,
        shared,
        "withheld, the first half still follows the expansion horizon"
    );
}

/// A rival religion used to narrow the live horizon to eight cities, and an
/// explicit Science lane then narrowed it again to six. The live verifier and
/// active native tournament must share a city goal independent of that
/// victory-specific caution: all lanes need enough cities to exercise their
/// production, district, and growth systems.
#[test]
fn verification_and_standard_tournament_share_the_ten_to_fifteen_city_contract() {
    let mut game = Game::new_full(2, 74, 46, 11_733, 250, 0, false);
    for pid in 0..2 {
        let settler = game
            .player_unit_ids(pid)
            .into_iter()
            .find(|unit| game.units[unit].kind == "settler")
            .expect("each major starts with a settler");
        let position = game.units[&settler].pos;
        game.found_city_for(pid, position, None);
        game.remove_unit(settler);
    }
    game.current = 0;
    game.turn = 200;
    game.victory_conditions.religious = true;
    game.players[1].religion = Some("Rival Faith".to_string());

    #[derive(Clone, Copy)]
    enum Profile {
        LiveVerification,
        StandardTournament,
        NativeDeployment,
    }
    let profiles = [
        ("live verification", Profile::LiveVerification),
        // `gene_screen::seat_with_genome` starts here before it flips the
        // individual genes in a drawn tournament genome.
        ("standard tournament", Profile::StandardTournament),
        ("native deployment", Profile::NativeDeployment),
    ];
    for lane in [
        VictoryTarget::Science,
        VictoryTarget::Culture,
        VictoryTarget::Religion,
        VictoryTarget::Diplomacy,
        VictoryTarget::Domination,
        VictoryTarget::Score,
    ] {
        for (profile, configuration) in profiles {
            let mut ai = AdvancedAi::targeting(lane);
            match configuration {
                Profile::LiveVerification => ai.enable_live_bridge(),
                Profile::StandardTournament => ai.enable_engine_repairs_universe(),
                Profile::NativeDeployment => ai.enable_engine_repairs(),
            }
            assert!(
                ai.shared_city_target,
                "{profile} must carry the fixed shared city horizon"
            );
            // This test pins the policy horizon. The separate map-room test
            // keeps proving that a truly exhausted map can still stop Settler
            // production.
            ai.disable_city_target_meets_the_map();
            let desired = ai.assess(&game, 0).desired_cities;
            assert!(
                (SHARED_CITY_TARGET_FLOOR..=SHARED_CITY_TARGET_CEILING).contains(&desired),
                "{profile} {lane:?} planned {desired} cities instead of the shared band"
            );
        }
    }
    assert!(!AdvancedAi::new().shared_city_target);
    assert!(!AdvancedAi::legacy().shared_city_target);
}

/// Off, every touched path is byte-identical: nothing is recorded and nothing
/// is barred. The registry hygiene suite exercises enable/disable; this pins
/// the inertness the HostOnly contract promises the simulator.
#[test]
fn the_move_refusal_break_gene_off_records_and_bars_nothing() {
    let mut g = Game::new_full(2, 24, 16, 7_925, 250, 1, false);
    g.current = 0;
    let ai = AdvancedAi::new();
    let uid = g.player_unit_ids(0)[0];
    let from = g.units[&uid].pos;
    let step = g
        .wdisk(from, 1)
        .into_iter()
        .find(|pos| *pos != from)
        .expect("a neighboring tile");
    ai.base.record_move_refusal_watch(&g, uid, from, step);
    assert!(
        ai.base.move_refusal_watch.borrow().is_empty(),
        "with the gene off the watch must stay empty"
    );
    g.turn += 1;
    assert!(!ai.base.move_refusal_blocked(&g, uid));
}

/// A city site that is itself the refused tile has no alternate approach.
/// It is deferred until the host refusal expires.
#[test]
fn a_frozen_settlers_destination_is_retired_through_dead_sites() {
    let mut g = Game::new_full(2, 24, 16, 7_925, 250, 1, false);
    g.current = 0;
    let mut ai = AdvancedAi::new();
    ai.enable_live_move_refusal_break();
    let settler = g
        .player_unit_ids(0)
        .into_iter()
        .find(|uid| g.units[uid].kind == "settler")
        .expect("a starting settler");
    let here = g.units[&settler].pos;
    let step = g
        .wdisk(here, 1)
        .into_iter()
        .find(|pos| *pos != here)
        .expect("a neighboring tile");
    let target = step; // The unavailable tile is itself the city site.
    ai.settler_targets.insert(settler, target);
    ai.base
        .move_refusal_blocks
        .insert(settler, (step, g.turn + 10));

    ai.retire_frozen_settler_targets(&g);

    assert!(
        !ai.settler_targets.contains_key(&settler),
        "the frozen destination must be dropped"
    );
    assert!(
        ai.settler_dead_sites
            .get(&settler)
            .is_some_and(|sites| sites.contains_key(&target)),
        "the destination goes through the dead-site machinery, not into the void"
    );
}

// ── `commitment-owner-acts` ─────────────────────────────────────────────

/// The nearest land tile exactly `distance` hexes from `home`, by position
/// order, that a unit at `from` has a route step toward.
fn owner_acts_site(game: &Game, from_unit: u32, home: Pos, distance: i32) -> Pos {
    let mut candidates: Vec<Pos> = game
        .map
        .tiles
        .iter()
        .filter(|(pos, tile)| {
            game.wdist(**pos, home) == distance
                && !game.rules.is_water(tile)
                && game.rules.is_passable(tile)
                && game.units_at(**pos).is_empty()
                && game.route_step(from_unit, **pos, 0).is_some()
        })
        .map(|(pos, _)| *pos)
        .collect();
    candidates.sort_unstable();
    *candidates
        .first()
        .unwrap_or_else(|| panic!("no routable land tile sits {distance} hexes from the capital"))
}

/// A settler and a Builder the unit pass left standing — movement in hand,
/// no order, a target each — walk their route step with the gene on, and
/// stand exactly where they were with it off.
#[test]
fn a_forgotten_owner_walks_its_route_step_and_off_it_stands_still() {
    use super::commitments::{Kind, Owner};

    let (game, _capital, home) = empire_with_a_capital(71_201);
    let fixture = || {
        let mut game = game.clone();
        let start = anchor_at(&game, home, 1);
        let settler = game.spawn_test_unit("settler", 0, start);
        let builder = game.spawn_test_unit("builder", 0, start);
        let far = owner_acts_site(&game, settler, home, 6);
        let near = owner_acts_site(&game, builder, home, 3);
        (game, settler, builder, far, near, start)
    };

    let (mut game, settler, builder, far, near, start) = fixture();
    let mut ai = AdvancedAi::new();
    ai.enable_commitment_owner_acts();
    ai.settler_targets.insert(settler, far);
    ai.builder_targets.insert(builder, near);
    // Register both decisions, then read one forgotten turn so the journal
    // line carries a streak.
    ai.reconcile_commitments(&mut game, 0);
    game.turn += 1;
    ai.reconcile_commitments(&mut game, 0);
    assert_eq!(
        ai.commitments()
            .open_for(Kind::Settle, Owner::Unit(settler))
            .map(|c| c.forgotten_streak),
        Some(1)
    );
    let settler_before = game.wdist(game.units[&settler].pos, far);
    let builder_before = game.wdist(game.units[&builder].pos, near);
    assert!(!game.units[&settler].acted && game.units[&settler].moves_left > 0.0);
    ai.commitment_owners_act(&mut game, 0);
    assert!(game.units[&settler].acted, "the settler was ordered");
    assert!(
        game.wdist(game.units[&settler].pos, far) < settler_before,
        "the settler stepped toward its site"
    );
    assert!(game.units[&builder].acted, "the Builder was ordered");
    assert!(
        game.units[&builder].pos != start
            && game.wdist(game.units[&builder].pos, near) <= builder_before,
        "the Builder stepped along its route: {:?} -> {:?} for {near:?}",
        start,
        game.units[&builder].pos
    );
    assert_eq!(
        ai.settler_targets.get(&settler),
        Some(&far),
        "the decision stands"
    );
    assert_eq!(ai.builder_targets.get(&builder), Some(&near));
    assert_eq!(
        game.players[0].counters.get("commit:settle:owner_stepped"),
        Some(&1)
    );
    assert_eq!(
        game.players[0].counters.get("commit:improve:owner_stepped"),
        Some(&1)
    );
    // The ledger's reading at the boundary: acted, so not forgotten.
    ai.reconcile_commitments(&mut game, 0);
    assert_eq!(
        ai.commitments()
            .open_for(Kind::Settle, Owner::Unit(settler))
            .map(|c| c.forgotten_streak),
        Some(0)
    );

    let (mut game, settler, builder, far, near, _start) = fixture();
    let mut off = AdvancedAi::new();
    off.settler_targets.insert(settler, far);
    off.builder_targets.insert(builder, near);
    let settler_at = game.units[&settler].pos;
    off.commitment_owners_act(&mut game, 0);
    assert_eq!(game.units[&settler].pos, settler_at, "off: nothing moves");
    assert!(!game.units[&settler].acted && !game.units[&builder].acted);
    assert!(game.players[0]
        .counters
        .keys()
        .all(|key| !key.contains("owner_")));
    assert_eq!(off.settler_targets.get(&settler), Some(&far));
}

