/// A fixture guard: `false` skips the test the way the sibling raider
/// fixtures do, unless `CIVVIS_STRICT_FIXTURES` is set, when a fixture that
/// does not hold is a failure rather than a silent pass.
fn fixture_holds(condition: bool, what: &str) -> bool {
    if !condition && std::env::var_os("CIVVIS_STRICT_FIXTURES").is_some() {
        panic!("fixture does not hold: {what}");
    }
    condition
}

/// A flat plains board with one of our cities two tiles from an exposed
/// `front` tile and the Barbarian seat alive and at war with us. Every unit
/// the generator placed is removed so the only units are the test's own.
fn wounded_out_of_reach_board(seed: u64) -> Option<(Game, Pos, Pos, usize)> {
    let mut g = Game::new_full(2, 20, 14, seed, 80, 0, true);
    let barbarian = g.barb_pid?;
    for unit in g.units.keys().copied().collect::<Vec<_>>() {
        g.remove_unit(unit);
    }
    g.map.clear_rivers();
    for tile in g.map.tiles.values_mut() {
        tile.terrain = crate::name!("plains");
        tile.feature = None;
        tile.resource = None;
        tile.improvement = None;
        tile.district = None;
        tile.district_foundation = None;
        tile.wonder = None;
        tile.owner_city = None;
        tile.hills = false;
        tile.road = 0;
    }
    g.at_war.insert((0, barbarian));
    g.at_war.insert((barbarian, 0));
    g.current = 0;
    let front = g
        .map
        .tiles
        .keys()
        .copied()
        .find(|position| g.wdisk(*position, 3).len() == 37)?;
    let refuge = g
        .wdisk(front, 2)
        .into_iter()
        .find(|position| g.wdist(*position, front) == 2)?;
    g.found_city_for(0, refuge, Some("Refuge".to_string()));
    Some((g, front, refuge, barbarian))
}

/// A tile two steps from `front` on the far side from `refuge`, for the
/// raider to stand on: it can reach `front` next turn and not the city.
fn far_side_of(g: &Game, front: Pos, refuge: Pos) -> Option<Pos> {
    g.wdisk(front, 2)
        .into_iter()
        .filter(|position| g.wdist(*position, front) == 2 && g.wdist(*position, refuge) >= 3)
        .max_by_key(|position| g.wdist(*position, refuge))
}

#[test]
fn settler_site_gate_verdict_needs_a_free_seat_worth_the_floor() {
    use super::settler_site_gate::{
        SettlerSiteGateHold as Hold, SETTLER_SITE_GATE_EARLY_FLOOR as EARLY,
        SETTLER_SITE_GATE_FLOOR as FLOOR, SETTLER_SITE_GATE_SMALL_EMPIRE as SMALL,
    };
    let g = Game::new_full(2, 16, 12, 7, 50, 1, false);
    let (a, near_a, b) = ((2, 2), (3, 2), (10, 2));
    let verdict = |sites: &[(Pos, f64)], claimed: &[Pos], settlers: usize| {
        AdvancedAi::settler_site_gate_verdict(&g, sites, claimed, settlers, FLOOR)
    };
    assert_eq!(verdict(&[], &[], 0), Err(Hold::NoSite));
    // The best free seat goes to the Settler this city would start.
    assert_eq!(verdict(&[(a, 90.0), (b, 60.0)], &[], 0), Ok((a, 90.0)));
    // A claimed seat is taken, and so is every plot within settlement
    // spacing of it: two candidate plots one tile apart are one seat.
    assert_eq!(
        verdict(&[(a, 90.0), (near_a, 85.0), (b, 60.0)], &[a], 1),
        Ok((b, 60.0))
    );
    // A Settler alive without a target queues ahead of a new one.
    assert_eq!(verdict(&[(a, 90.0), (b, 60.0)], &[], 1), Ok((b, 60.0)));
    assert_eq!(
        verdict(&[(a, 90.0), (b, 60.0)], &[a], 2),
        Err(Hold::AllClaimed {
            seats: 1,
            unseated: 1
        })
    );
    // Run 182050Z's wandering targets were worth 13.8–24.1; its founded
    // sites 96–140. The floor sits between them, and a seat under it is
    // not a seat worth a Settler.
    assert_eq!(
        verdict(&[(a, 18.9)], &[], 0),
        Err(Hold::BelowFloor {
            worth: 18.9,
            floor: FLOOR
        })
    );
    assert_eq!(verdict(&[(a, FLOOR)], &[], 0), Ok((a, FLOOR)));
    assert!(Hold::BelowFloor {
        worth: 18.9,
        floor: FLOOR
    }
    .describe()
    .contains("18.9"));
    // A small empire takes the seat run 201841Z's Rome was held off at t16:
    // worth 29.9 clears the early floor and not the late one.
    assert_eq!(AdvancedAi::settler_site_gate_floor(SMALL - 1), EARLY);
    assert_eq!(AdvancedAi::settler_site_gate_floor(SMALL), FLOOR);
    assert_eq!(
        AdvancedAi::settler_site_gate_verdict(&g, &[(a, 29.9)], &[], 0, EARLY),
        Ok((a, 29.9))
    );
}

#[test]
fn settler_site_gate_is_off_by_default_and_reads_the_live_board() {
    use super::settler_site_gate::SettlerSiteGateHold as Hold;
    let mut ai = AdvancedAi::new();
    assert!(!ai.settler_site_gate, "an OptIn gene ships off");
    ai.enable_settler_site_gate();
    assert!(ai.settler_site_gate);
    ai.disable_settler_site_gate();
    assert!(!ai.settler_site_gate);

    let mut game = Game::new_full(4, 24, 16, 470_001, 200, 1, false);
    let mut ais: Vec<AdvancedAi> = (0..game.players.len()).map(|_| AdvancedAi::new()).collect();
    while game.player_city_ids(0).is_empty() && game.turn < 40 && game.winner.is_none() {
        let pid = game.current;
        ais[pid].take_turn(&mut game, pid);
        if game.winner.is_none() && game.current == pid {
            let _ = game.apply(pid, &crate::game::Action::EndTurn);
        }
    }
    let cid = game.player_city_ids(0)[0];
    let capital = game.cities[&cid].pos;
    ai.enable_settler_site_gate();
    // With no Settler alive the gate is the pure verdict over the capital's
    // acceptable sites — the walker's own refusals applied, nothing claimed.
    let sites: Vec<(Pos, f64)> = ai
        .settle_sites(&game, 0, capital, 11)
        .into_iter()
        .filter(|(site, _)| {
            ai.exhaustion_site_unpriceable(&game, 0, *site).is_none()
                && !AdvancedAi::inside_rival_sphere(&game, 0, *site)
        })
        .collect();
    assert_eq!(
        ai.settler_site_gate(&game, 0, capital, 0),
        AdvancedAi::settler_site_gate_verdict(
            &game,
            &sites,
            &[],
            0,
            AdvancedAi::settler_site_gate_floor(game.player_city_ids(0).len())
        )
    );
    // More Settlers alive than the map has seats: the city holds.
    assert!(matches!(
        ai.settler_site_gate(&game, 0, capital, 99),
        Err(Hold::AllClaimed { .. }) | Err(Hold::NoSite)
    ));
}

/// Production is the common prerequisite of every named victory lane. The
/// deployment ledger can keep the adaptive industrial-chain gene off while a
/// live named lane still pays the Workshop/Factory/power chain before a
/// repeatable project. This is intentionally a Culture fixture: Science's
/// existing research-project contract would otherwise hide the industrial
/// gate we need to prove.
#[test]
fn named_victory_targets_make_industrial_production_foundational() {
    let mut game = Game::new(2, 32, 24, 5_416, 250, 0);
    let settler = game
        .player_unit_ids(0)
        .into_iter()
        .find(|unit| game.units[unit].kind == "settler")
        .expect("starting settler");
    game.apply(0, &Action::FoundCity { unit: settler })
        .expect("found city");
    let city = game.player_city_ids(0)[0];
    game.players[0]
        .techs
        .insert(crate::name!("industrialization"));
    game.players[0].techs.insert(crate::name!("currency"));
    game.players[0].gpp.insert("merchant".to_string(), 30.0);
    game.cities.get_mut(&city).unwrap().pop = 6;
    game.turn = 120;

    install_ai_test_district(&mut game, city, "industrial_zone");
    install_ai_test_district(&mut game, city, "commercial_hub");
    game.cities
        .get_mut(&city)
        .unwrap()
        .buildings
        .extend([crate::name!("workshop"), crate::name!("market")]);

    let factory = Item::Building {
        building: crate::name!("factory"),
    };
    let project = Item::Project {
        project: crate::name!("commercial_hub_investment"),
    };
    assert!(game.can_produce(0, city, &factory), "the Factory is owed");
    assert!(
        game.can_produce(0, city, &project),
        "the repeatable project is legal"
    );
    let plan = StrategicPlan {
        strategy: GrandStrategy::Culture,
        target_player: None,
        target_city: None,
        threatened_city: None,
        desired_cities: 6,
        assessed_turn: game.turn,
        rush: false,
    };

    let mut named = AdvancedAi::targeting(VictoryTarget::Culture);
    named.enable_live_bridge();
    named.refresh_research_weight(&game);
    let mut adaptive = named.clone();
    adaptive.victory_target = None;
    // The deployed ledger may independently select the industrial-chain
    // treatment. This control isolates the named-lane contract from that
    // screenable choice.
    adaptive.disable_industrial_chain_debt();
    assert!(
        named.industrial_production_foundation(&game),
        "an active named lane must carry the production contract"
    );
    assert!(
        !adaptive.industrial_production_foundation(&game),
        "the explicitly withheld adaptive controller remains unchanged"
    );
    for target in VictoryTarget::ALL {
        let mut lane = AdvancedAi::targeting(target);
        lane.enable_live_bridge();
        assert!(
            lane.industrial_production_foundation(&game),
            "{} must value the production foundation",
            target.as_str()
        );
    }

    let counts = named.counts(&game, 0);
    let factory_uplift = named.production_value(&game, 0, city, &factory, &plan, &counts)
        - adaptive.production_value(&game, 0, city, &factory, &plan, &counts);
    assert!(
        factory_uplift > 0.0,
        "the named Culture lane must owe its Factory: {factory_uplift}"
    );

    let named_project =
        named.district_project_value(&game, 0, city, "commercial_hub_investment", &plan);
    let adaptive_project =
        adaptive.district_project_value(&game, 0, city, "commercial_hub_investment", &plan);
    assert!(
        named_project <= PROJECT_BEHIND_BUILDINGS_CAP,
        "the Factory must precede the repeatable project: {named_project}"
    );
    assert!(
        adaptive_project > named_project,
        "only the named lane holds the project for the Factory: {adaptive_project}"
    );
}

// ── settler-walk-deadline ────────────────────────────────────────────────
//
// See `advanced/settler_walk_deadline.rs`: an opening Settler out of a city
// past the deadline founds the best legal site within reach.

use super::settler_walk_deadline::{
    SETTLER_WALK_DEADLINE_RADIUS, SETTLER_WALK_DEADLINE_STEP_MARGIN,
    SETTLER_WALK_DEADLINE_VALUE_SHARE,
};

/// A board with two settled capitals and a lone Settler on open ground far
/// enough from both that the tiles around it are legal city sites.
fn walk_deadline_board(seed: u64) -> (Game, u32) {
    let (mut game, home) = camp_bounty_board(seed);
    let far = open_ground_at(&game, home, 7);
    let settler = game.spawn_test_unit("settler", 0, far);
    (game, settler)
}

/// A walk clock that began on turn one and has run `out` turns.
fn walk_out(ai: &mut AdvancedAi, game: &Game, settler: u32, out: u32) {
    ai.settler_walk_clock.insert(settler, (1, game.turn, out));
}

#[test]
fn the_walk_clock_counts_turns_out_of_a_city_and_follows_the_unit() {
    let (mut game, home) = camp_bounty_board(93_200);
    let settler = game.spawn_test_unit("settler", 0, home);
    let mut ai = AdvancedAi::new();
    ai.enable_settler_walk_deadline();
    // On the city tile: the clock starts but a turn at home is not a turn out.
    assert_eq!(ai.note_settler_walk(&game, 0, settler), (game.turn, 0));
    game.turn += 1;
    assert_eq!(ai.note_settler_walk(&game, 0, settler), (game.turn - 1, 0));
    // Out on open ground: one turn out per turn, noted once however often
    // the step runs in a turn.
    let began = game.turn - 1;
    game.units.get_mut(&settler).unwrap().pos = open_ground_at(&game, home, 5);
    game.turn += 1;
    assert_eq!(ai.note_settler_walk(&game, 0, settler), (began, 1));
    assert_eq!(ai.note_settler_walk(&game, 0, settler), (began, 1));
    game.turn += 1;
    assert_eq!(ai.note_settler_walk(&game, 0, settler), (began, 2));
    assert_eq!(ai.settler_turns_out(settler), 2);
    // Settler memory: it follows a live-bridge id remap and dies with the unit.
    let mut map = BTreeMap::new();
    map.insert(settler, settler + 1000);
    ai.remap_unit_memory(&map);
    assert_eq!(ai.settler_turns_out(settler + 1000), 2);
    assert_eq!(ai.settler_turns_out(settler), 0);
    ai.forget_unit_memory();
    assert!(ai.settler_walk_clock.is_empty());
}

#[test]
fn science_production_recovers_in_peace_without_war_economy() {
    let (mut game, city, home) = empire_with_a_capital(79_101);
    found_nearby_test_city(&mut game, 0, home);
    game.at_war.clear();
    game.players[0].civics.insert(crate::name!("foreign_trade"));
    game.players[0].gold = 0.0;
    game.players[0].gold_per_turn = -18.0;
    let mut ai = AdvancedAi::targeting(VictoryTarget::Science);
    ai.disable_war_economy();
    let plan = StrategicPlan {
        strategy: GrandStrategy::Science,
        target_player: None,
        target_city: None,
        threatened_city: None,
        desired_cities: 2,
        assessed_turn: game.turn,
        rush: false,
    };
    let recovery = ai
        .base
        .economic_recovery_item(&game, 0, city, ai.counts(&game, 0).traders)
        .expect("two cities with Foreign Trade can add a recovery Trader");
    assert!(matches!(&recovery, Item::Unit { unit } if unit == "trader"));
    assert!(ai.live_war_economy_requires_recovery(&game, 0, &ai.counts(&game, 0)));
    ai.advanced_production(&mut game, 0, &plan, false);
    assert_eq!(game.cities[&city].queue.first(), Some(&recovery));

    // Positive cash flow and a sufficient reserve both leave science free
    // to use the normal scorer, even with the war gene disabled.
    game.players[0].gold_per_turn = 1.0;
    assert!(!ai.live_war_economy_requires_recovery(&game, 0, &ai.counts(&game, 0)));
    game.players[0].gold_per_turn = -18.0;
    game.players[0].gold = 150.0;
    assert!(!ai.live_war_economy_requires_recovery(&game, 0, &ai.counts(&game, 0)));
}

fn envoy_dividend_board(city_count: usize) -> (Game, Vec<usize>) {
    let mut g = Game::new_full(2, 48, 30, 7_713, 250, 3, false);
    for _ in 0..city_count {
        let pos = *g
            .map
            .tiles
            .iter()
            .find(|(pos, tile)| {
                matches!(tile.terrain.as_str(), "plains" | "grassland")
                    && g.cities.values().all(|city| g.wdist(city.pos, **pos) > 3)
            })
            .unwrap()
            .0;
        let city = g.found_city_for(0, pos, None);
        install_ai_test_district(&mut g, city, "campus");
        g.cities
            .get_mut(&city)
            .unwrap()
            .buildings
            .extend(["library", "university"].into_iter().map(Name::new));
    }
    let states: Vec<_> = g
        .players
        .iter()
        .filter(|p| p.is_minor && !p.is_barbarian)
        .map(|p| p.id)
        .collect();
    for (minor, name) in states.iter().zip(["Hattusa", "Geneva", "Zanzibar"]) {
        g.players[*minor].civ = name.to_string();
        g.record_contact(0, *minor);
    }
    g.players[0].envoys.clear();
    g.players[0].envoys_free = 3;
    (g, states)
}

#[test]
fn envoy_dividends_price_ten_city_buildings_and_pillage() {
    let (mut g, states) = envoy_dividend_board(10);
    let options = g.envoy_investment_options(0, states[0]);
    assert_eq!(
        options
            .iter()
            .map(|(cost, count, y)| (*cost, *count, y.science))
            .collect::<Vec<_>>(),
        vec![(1, 1, 11.0), (3, 3, 31.0)]
    );
    let city = g.player_city_ids(0)[0];
    g.cities
        .get_mut(&city)
        .unwrap()
        .pillaged_buildings
        .insert(Name::new("university"));
    assert_eq!(g.envoy_investment_options(0, states[0])[1].2.science, 29.0);
}

#[test]
fn envoy_dividends_policy_packages_match_actual_placements() {
    for cards in [
        vec![],
        vec!["diplomatic_league"],
        vec!["containment"],
        vec!["diplomatic_league", "containment"],
    ] {
        let (mut g, states) = envoy_dividend_board(1);
        let minor = states[0];
        g.players[0].policies = cards.into_iter().map(Name::new).collect();
        g.players[0].government = Some("democracy".to_string());
        g.players[1].government = Some("communism".to_string());
        g.players[1].envoys = vec![(minor, 3)];
        g.players[0].envoys_free = 6;
        let options = g.envoy_investment_options(0, minor);
        for (cost, projected, _) in options {
            let mut actual = g.clone();
            for _ in 0..cost {
                actual
                    .apply(0, &Action::SendEnvoy { player: minor })
                    .unwrap();
            }
            assert_eq!(actual.envoys_at(0, minor), projected);
            assert_eq!(actual.players[0].envoys_free, 6 - cost);
        }
    }
}

/// Live Rome turn 33: a wounded finisher walks onto its victim's tile,
/// then a second visible cavalry unit removes it. A direct kill is not safety.
#[test]
fn immediate_kill_priority_rejects_a_poisoned_finish() {
    let (mut g, front, refuge, barbarian) =
        wounded_out_of_reach_board(91_633).expect("flat barbarian fixture");
    let target = g
        .nbrs(front)
        .into_iter()
        .find(|p| g.city_at(*p).is_none() && g.wdist(*p, refuge) > 1)
        .expect("open adjacent target");
    let counter_at = g
        .nbrs(target)
        .into_iter()
        .find(|p| *p != front && g.city_at(*p).is_none())
        .expect("adjacent counterattack");
    let ours = g.spawn_test_unit("warrior", 0, front);
    let victim = g.spawn_test_unit("scout", barbarian, target);
    let counter = g.spawn_test_unit("horseman", barbarian, counter_at);
    g.units.get_mut(&ours).unwrap().hp = 46;
    g.units.get_mut(&victim).unwrap().hp = 1;
    // Host exports exhausted enemies; they refresh before the reply.
    g.units.get_mut(&counter).unwrap().moves_left = 0.0;
    g.units.get_mut(&counter).unwrap().attacks_left = 0;
    let action = Action::Attack { unit: ours, target };
    let plan = StrategicPlan {
        strategy: GrandStrategy::Conquest,
        target_player: Some(barbarian),
        target_city: None,
        threatened_city: None,
        desired_cities: 3,
        assessed_turn: g.turn,
        rush: false,
    };
    let mut ai = AdvancedAi::new();
    let mut after = g.speculative_clone();
    after.apply(0, &action).expect("legal finishing strike");
    assert!(!after.units.contains_key(&victim));
    assert!(
        after.units.contains_key(&ours),
        "survives the direct exchange"
    );
    assert_eq!(after.units[&ours].pos, target);
    assert!(
        !ai.finisher_survives_reach(&after, 0, ours),
        "remaining cavalry can kill the finisher"
    );
    assert!(ai.immediate_kill_value(&g, 0, &action, &plan).is_none());
    let mut tactical = g.speculative_clone();
    ai.advanced_military_step(&mut tactical, 0, ours, &plan);
    assert!(
        tactical.units.contains_key(&victim),
        "the ordinary military path must not reopen the rejected finish"
    );
    assert_eq!(
        ai.prioritize_immediate_kills(&mut g, 0, &plan, &BTreeSet::new()),
        0
    );
    assert!(g.units.contains_key(&victim));

    // Removing the second hostile makes the same blow a safe finish. The
    // killed victim must not remain in a cached attack envelope.
    g.remove_unit(counter);
    assert!(ai.immediate_kill_value(&g, 0, &action, &plan).is_some());
    assert_eq!(
        ai.prioritize_immediate_kills(&mut g, 0, &plan, &BTreeSet::new()),
        1
    );
    assert!(!g.units.contains_key(&victim));
}

fn remembered_naval_escort_field() -> (Game, AdvancedAi, u32, u32, Pos, Pos) {
    let (mut game, _, home) = barbarian_field(99_132_700);
    for uid in game.player_unit_ids(0) {
        game.remove_unit(uid);
    }
    game.turn = 30;
    game.players[0].techs.insert(crate::name!("shipbuilding"));
    let start = game
        .map
        .tiles
        .keys()
        .copied()
        .find(|pos| {
            game.wdist(*pos, home) > 4
                && game.nbrs(*pos).len() == 6
                && [
                    (pos.0 + 1, pos.1),
                    (pos.0 + 2, pos.1),
                    (pos.0 + 2, pos.1 - 1),
                ]
                .iter()
                .all(|p| game.map.get(*p).is_some() && game.city_at(*p).is_none())
        })
        .unwrap();
    let water = (start.0 + 1, start.1);
    let target = (start.0 + 2, start.1);
    let seen = (start.0 + 2, start.1 - 1);
    for pos in game.nbrs(start) {
        game.map.tiles.get_mut(&pos).unwrap().terrain = crate::name!("mountain");
    }
    for pos in [water, seen] {
        let tile = game.map.tiles.get_mut(&pos).unwrap();
        tile.terrain = crate::name!("coast");
        tile.improvement = None;
    }
    let guard = game.spawn_test_unit("archer", 0, start);
    let settler = game.spawn_test_unit("settler", 0, target);
    let mut ai = AdvancedAi::new();
    ai.enable_hostile_memory();
    ai.disable_come_ashore(); // Matches the recorded live deployment.
    ai.bind_settler_guard(&game, settler, guard);
    ai.hostile_last_seen.insert(
        999_999,
        super::RememberedHostile {
            pos: seen,
            when: game.turn - 1,
            owner: 1,
            kind: crate::name!("caravel"),
        },
    );
    assert!(
        game.can_move(guard, water),
        "the risky embarkation is legal"
    );
    (game, ai, guard, settler, start, water)
}

fn remembered_shore_gun_fixture() -> (Game, AdvancedAi, u32, Pos) {
    let (mut g, front, refuge, barbarian) =
        wounded_out_of_reach_board(91_623).expect("barbarian fixture");
    let gun_at = far_side_of(&g, front, refuge).expect("shore opposite refuge");
    for tile in g.map.tiles.values_mut() {
        if tile.pos != refuge && tile.pos != gun_at {
            tile.terrain = crate::name!("coast");
        }
    }
    let ours = g.spawn_test_unit("galley", 0, front);
    g.units.get_mut(&ours).unwrap().hp = 31;
    let gun = g.spawn_test_unit("field_cannon", barbarian, gun_at);
    g.turn = 134;
    let mut ai = AdvancedAi::new();
    ai.enable_hostile_memory();
    ai.enable_wounded_out_of_reach();
    ai.observe_turn_start_hostiles(&g, 0);
    assert!(
        ai.hostile_last_seen.contains_key(&(gun as i64)),
        "the gun must actually have been seen"
    );
    g.remove_unit(gun);
    g.turn = 136;
    (g, ai, ours, gun_at)
}

#[test]
fn a_wounded_galley_leaves_a_remembered_shore_guns_reach() {
    let (mut g, ai, ours, gun_at) = remembered_shore_gun_fixture();
    let before = g.units[&ours].pos;
    assert!(
        ai.wounded_out_of_reach_step(&mut g, 0, ours).is_some(),
        "a remembered land gun still threatens a wounded ship on water"
    );
    assert!(
        g.wdist(g.units[&ours].pos, gun_at) > g.wdist(before, gun_at),
        "if the unseen gun's entire projection cannot be escaped, increase separation"
    );
    assert_eq!(g.units[&ours].hp, 31);
}

#[test]
fn a_shore_gun_without_an_in_scope_memory_does_not_move_the_ship() {
    let (g, ai, ours, _) = remembered_shore_gun_fixture();
    for mode in [
        "gene-off",
        "memory-off",
        "unseen",
        "expired",
        "future",
        "peace",
        "melee-only",
    ] {
        let mut policy = ai.clone();
        let mut board = g.clone();
        match mode {
            "gene-off" => policy.disable_wounded_out_of_reach(),
            "memory-off" => policy.disable_hostile_memory(),
            "unseen" => policy.hostile_last_seen.clear(),
            "expired" => board.turn = 139,
            "future" => {
                for record in policy.hostile_last_seen.values_mut() {
                    record.when = 140;
                }
            }
            "peace" => {
                assert!(!board.is_at_war(0, 1));
                for record in policy.hostile_last_seen.values_mut() {
                    record.owner = 1;
                }
            }
            "melee-only" => {
                for record in policy.hostile_last_seen.values_mut() {
                    record.kind = crate::name!("warrior");
                }
            }
            _ => unreachable!(),
        }
        let before = board.units[&ours].pos;
        assert_eq!(
            policy.wounded_out_of_reach_step(&mut board, 0, ours),
            None,
            "{mode}"
        );
        assert_eq!(board.units[&ours].pos, before, "{mode}");
    }
}

